(window.GIM_TS=window.GIM_TS||{})["Bekhorot.0"]={"from":0,"a":[["\u0003הלוקח\u0004 (הקונה) \u0003עובר חמורו של נכרי,\u0004 כשהוא בבטן האתון; \u0003והמוכר לו\u0004 לנכרי את עובר חמורו שלו, \u0003אף על פי שאינו רשאי,\u0004 שאסור למכור בהמה גסה לגוי; ו\u0003המשתתף לו,\u0004 הנעשה שותף עם הגוי באתון או בעובר; \u0003והמקבל הימנו\u0004 אתון כדי לטפל בה, ובתמורה לכך להשתתף עמו בוולדותיה; \u0003והנותן לו\u0004 לגוי אתון \u0003בקבלה,\u0004 שיטפל בה הגוי וישתתף עמו בוולדות יה; בכל המקרים הללו, הנולד בכור לאמו \u0003פטור מן הבכורה,\u0004 ואינו צריך לפדותו, \u0003שנאמר:\u0004 \"הקדשתי לי כל בכור \u0003בישראל\u0004 מאדם עד בהמה\" (במדבר ג, יג) — \u0003אבל לא באחרים,\u0004 וכל שיש לגוי חלק — אינו קדוש בבכורה.","ושואלים: \u0003כל הני\u0004 \u0005[\u0006המקרים \u0005הללו]\u0006 ששנינו במשנתנו \u0003למה לי?\u0004","ומשיבים: \u0003צריכי\u0004 \u0005[נצרכים\u0006 הם\u0005],\u0006 \u0003דאי תנא\u0004 \u0005[שאם שנה]\u0006 רק ב\u0003לוקח\u0004 מן הגוי שהוא פטור, הוה אמינא \u0005[הייתי אומר]:\u0006 טעם הדבר — משום דקא מייתי לה \u0005[שהוא מביא אותה]\u0006 \u0003לקדושה,\u0004 שתהא שובתת בשבת, כדין בהמת ישראל, \u0003אבל מוכר\u0004 עובר לגוי, \u0003דקא מפקע לה\u0004 \u0005[שהוא מפקיע אותה]\u0006 \u0003מקדושה\u0004 — \u0003אימא ליקנסיה\u0004 \u0005[אמור שנקנוס אותו]\u0006 לנהוג בו דין בכור, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שפטור.","ושואלים, ומה ששנינו: \u0003והמשתתף לו, למה לי\u0004 לאומרו? ומשיבים: \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' יהודה,\u0004 ש\u0003אמר: שותפות גוי חייבת בבכורה,\u0004 \u0003קמשמע לן\u0004 \u0005[משמיע לנו]\u0006 במשנה זו ש\u0003פטורה מן הבכורה.\u0004","ושואלים: ומעתה, מה ששנינו: \u0003והמקבל\u0004 אתון מן הגוי, שהוא משתתף בוולדותיה, \u0003למה לי\u0004 לומר שהוא פטור? והרי זה בכלל הדין הקודם! ומשיבים: \u0003משום דקא בעי למיתני\u0004 \u0005[שהוא רוצה לשנות]\u0006 את המקרה המקביל לו: \u0003והנותן לו בקבלה,\u0004 לומר שהוא פטור.","ושואלים: \u0003ו\u0004באמת, \u0003הנותן לו בקבלה למה לי?\u0004 ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך\u0006 הדבר\u0005],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ועיקר בהמה\u0004 של \u0003ישראל היא, ליקנסיה דלמא אתי לאיחלופי בבהמה אחריתי\u0004 \u0005[שנקנוס אותו,\u0006 נחייבו לפדותו, \u0005שמא יבוא להחליף\u0006 ולפטור גם \u0005בבהמה אחרת]\u0006 שנותן לגוי לטפל בה, גם כשאין לגוי חלק בוולדות, והיא חייבת בבכורה, על כן \u0003קמשמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין קונסים.","ומביאים דיון שהובאה בו משנתנו כראיה. \u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]\u0006 במסכת עבודה זרה, בענין איסור מכירת בהמה גסה לגוי, שמא יעבוד בה בשבת: \u0003ר' יהודה מתיר\u0004 למכור לגוי בהמה \u0003שבורה,\u0004 שנשברו רגליה, מפני שאינה ראויה למלאכה. \u0003בן בתירא מתיר בסוס,\u0004 מפני שאין נוהגים לעבוד בו, אלא לרכב עליו, ואין זה אסור מן התורה בשבת.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לחכמים שאלה זו: \u0003עובר מה לי אמר ר' יהודה?\u0004 מה דעתו? האם מותר למכור את העובר לגוי, כדרך שהתיר בשבורה? ומסבירים את השאלה: \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' יהודה התם דשרי\u0004 \u0005[שם שהתיר],\u0006 הרי זה \u0003משום\u0004 שהיא \u0003שבורה\u0004 ואינה יכולה לעבוד, ולפי זה יש לומר כי \u0003עובר נמי\u0004 \u0005[גם כן]\u0006 הוא מתיר, שהרי \u0003שבור הוא,\u0004 ואינו יכול לעשות שום מלאכה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר: \u0003שבורה\u0004 הוא מתיר למכור, משום ש\u0003לאו היינו אורחיה\u0004 \u0005[אין זו דרכו],\u0006 אין דרכה של בהמה להיות שבורה, ואין זה בכלל איסור מכירת בהמה. \u0003אבל עובר, כיון דהיינו אורחיה\u0004 \u0005[שזו דרכו],\u0006 שהוא נעשה ראוי למלאכה לכשיגדל, שמא \u0003לאו\u0004 \u0005[לא]\u0006 \u0003שבור הוא\u0004 נחשב?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדעת ר' יהודה ממה ששנינו במשנתנו: \u0003והמוכר לו\u0004 (עובר לגוי) \u0003אף על פי שאינו רשאי\u0004 למכור לו, \u0003ולא פליג\u0004 \u0005[חולק]\u0006 \u0003ר' יהודה,\u0004 לומר שרשאי למוכרו.","ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 שאתה רוצה להוכיח בדרך זו, מה ששנינו במשנתנו: \u0003המשתתף לו, והמקבל ממנו, והנותן לו בקבלה, דלא קתני\u0004 \u0005[שאינו שונה]\u0006 שר' יהודה חולק על כך, \u0003הכי נמי דלא פליג\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שאינו חולק]?\u0006 והרי לדעתו שותפות הגוי אינה פוטרת מן הבכורה!","\u0003אלא\u0004 בוודאי \u0003פליג\u0004 \u0005[חולק\u0006 בזה\u0005],\u0006 \u0003ו\u0004מכל מקום \u0003לא קתני\u0004 \u0005[שונה]\u0006 התנא את דעתו. \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 לענין מכירת עובר, יש לומר שהוא \u0003פליג\u0004 \u0005[חולק],\u0006 ומתיר, \u0003ולא קתני\u0004 \u0005[שונה]\u0006 התנא את הדבר במשנה, שלא הביא בה את כל הדעות.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא, \u0003ר' יהודה אומר: המקבל בהמה מן הגוי\u0004 לטפל בה ולהשתתף בוולדותיה, \u0003וילדה\u0004 בכור — \u0003מעלין\u0004 \u0003אותו\u0004 \u0003בשוויו\u0004 (אומדים כמה הוא שווה), \u0003ונותן\u0004 הישראל \u0003חצי דמיו לכהן,\u0004 לפדיון חלקו של הישראל, שהוא קדוש בבכורה. והנותן לו לגוי בהמה \u0003בקבלה, אף על פי שאינו רשאי,\u0004 הואיל ועשה כן — \u0003קונסים אותו\u0004 לקנות את חלקו של הגוי בבכור, \u0003עד\u0004 אפילו פי \u0003עשרה בדמיו, ונותן כל דמיו לכהן.\u0004"],["\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 משום ה\u0003עובר\u0004 נאמר שאינו רשאי למוכרו? ודוחים: \u0003לא,\u0004 מדובר על הבהמה, שאינו רשאי ליתנה לגוי בקבלה, ועל כך קונסים אותו. ומקשים:","\u0003והא\u0004 \u0005[והרי]\u0006 \"קונסים אותו עד עשרה בדמיו\" קתני \u0005[הוא שונה],\u0006 בלשון זכר! ומשיבים, \u0003תני\u0004 \u0005[שנה]:\u0006 \u0003\"דמיה\".\u0004 ומקשים: \u0003והא\u0004 \u0005[והרי] \"\u0006\u0003נותן כל דמיו לכהן\" קתני\u0004 \u0005[הוא שונה],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 על הבהמה מדובר, \u0003כהן מאי עבידתיה\u0004 \u0005[מה מעשהו\u0006 כאן]? ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון דיהיב ליה בהמה מעברתא לפטומה\u0004 \u0005[שנותן לו,\u0006 לגוי, \u0005בהמה מעוברת לפטם אותה],\u0006 כדי להתחלק בשבחה, וגם להתחלק בוולדותיה. \u0003דמיגו דקנסינן ליה\u0004 \u0005[שמתוך שאנו קונסים אותו]\u0006 על ה\u0003בהמה,\u0004 שעשה שלא כדין, \u0003קנסינן ליה\u0004 \u0005[קונסים אנו אותו]\u0006 גם על ה\u0003עובר\u0004 ליתן דמיו לכהן.","\u0003אמר רב אשי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא: \u0003ר' יהודה מתיר בשבורה\u0004 למוכרה לגוי, \u0003מפני שאינה יכולה להתרפאות.\u0004 ונדייק: \u0003הא\u0004 \u0005[אבל]\u0006 אם \u0003יכולה להתרפאות\u0004 — \u0003אסר. והא\u0004 \u0005[והרי]\u0006 \u0003עובר נמי\u0004 \u0005[גם כן],\u0006 \u0003כיכול להתרפאות דמי\u0004 \u0005[נחשב],\u0006 שהרי בסופו של דבר יוכל לעבוד. \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהוא אוסר למוכרו לגוי.","ומעירים: סוגיה זו ששנינו הובאה לברר דעתו של ר' יהודה במשנה שבמסכת עבודה זרה, \u0003ואיכא דמתני לה אמתניתין\u0004 \u0005[ויש ששונים אותה,\u0006 סוגיה זו, על משנתנו], ששנינו בה: \u0003והמוכר לו\u0004 עובר לנכרי, \u0003אף על פי שאינו רשאי.\u0004 וכך שאלו: \u0003לימא מתניתין\u0004 \u0005[האם נאמר שמשנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' יהודה\u0004 היא? דתנן \u0005[ש\u0006הרי \u0005שנינו]\u0006 במשנה שבמסכת עבודה זרה: \u0003ר' יהודה מתיר בשבורה\u0004 למוכרה לגוי, לפי שאינה עושה מלאכה בשבת. והוא הדין, איפוא, לעובר, שאינו ראוי למלאכה!","ודוחים: ניתן להסביר את משנתינו \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיא כר' יהודה; \u0003שבורה\u0004 — \u0003לאו היינו אורחיה\u0004 \u0005[אין זה דרכה]\u0006 של בהמה, ולכן אין זה בכלל האיסור. אבל \u0003עובר\u0004 — \u0003היינו אורחיה\u0004 \u0005[זהו דרכו],\u0006 שהוא נעשה ראוי למלאכה לכשיגדל, ואין הוא בכלל שבור.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא: \u0003ר' יהודה אומר: המקבל בהמה מן הגוי וילדה\u0004 — \u0003מעלין\u0004 (אומדים) \u0003אותו בשויו, ונותן חצי דמיו לכהן. והנותן לו\u0004 לגוי \u0003בקבלה, אף על פי שאינו רשאי\u0004 לעשות כן — \u0003קונסין אותו עד עשרה בדמיו, ונותן כל דמיו לכהן. מאי לאו\u0004 \u0005[האם לא]\u0006 משום ה\u0003עובר,\u0004 נאמר שאינו רשאי? ודוחים: \u0003לא,\u0004 מדובר על ה\u0003בהמה.\u0004","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"דמיו\" קתני\u0004 \u0005[שנה],\u0006 בלשון זכר! ודוחים, \u0003תני\u0004 \u0005[שנה]:\u0006 \u0003\"דמיה\".\u0004 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"נותן כל דמיו לכהן\" קתני\u0004 \u0005[הוא שונה],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 משום ה\u0003בהמה, כהן מאי עבידתיה\u0004 \u0005[מה מעשהו]?\u0006 ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון דיהיב בהמה מעברתא לפטומה\u0004 \u0005[שנותן\u0006 לגוי \u0005בהמה מעוברת לפטם אותה], להתחלק בשבח שישביח גופה,\u0006 וגם להתחלק בוולדותיה. \u0003דמיגו דקנסינן ליה\u0004 \u0005[שמתוך שאנו קונסים אותו]\u0006 על ה\u0003בהמה, קנסינן ליה\u0004 \u0005[קונסים אנו אותו]\u0006 על ה\u0003עובר.\u0004","\u0003אמר רב אשי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא: \u0003ר' יהודה מתיר בשבורה\u0004 למוכרה לגוי, \u0003מפני שאינה יכולה להתרפאות.\u0004 ונדייק: \u0003הא\u0004 \u0005[אבל]\u0006 אם \u0003יכולה להתרפאות\u0004 — \u0003אסור. והאי נמי\u0004 \u0005[וזה גם כן],\u0006 העובר, \u0003כיכול להתרפאות דמי\u0004 \u0005[נחשב].\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהוא אוסר למוכרו.","ועוד בענין איסור מכירת בהמה גסה לגוי, \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 שאלה לחכמים: \u0003מכר בהמה\u0004 לגוי רק \u0003ל\u0004ענין \u0003עובריה,\u0004 אבל הבהמה גופה שייכת לישראל, מאי \u0005[מהו]?\u0006 האם מותר הדבר? ומסבירים: \u0003תיבעי\u0004 \u0005[תישאל\u0006 השאלה] \u0003ל\u0004דעת \u0003ר' יהודה\u0004 שהתיר למכור בהמה שבורה לגוי, וכן \u0003תיבעי לרבנן\u0004 \u0005[תישאל\u0006 השאלה \u0005ל\u0006שיטת חכמים] החולקים עליו.","ומפרטים, \u0003תיבעי\u0004 \u0005[תישאל\u0006 השאלה] \u0003ל\u0004דעת \u0003ר' יהודה: עד כאן לא\u0004 שמענו כי \u0003קא שרי\u0004 \u0005[מתיר]\u0006 \u0003ר' יהודה אלא בשבורה, דלא אתיא לאיחלופי\u0004 \u0005[שאינה באה,\u0006 עשויה, \u0005להתחלף],\u0006 שאין חשש שבעקבות היתר זה יבואו אנשים למכור לגוי בהמה שלמה, שהרי ניכר הדבר, \u0003אבל\u0004 המוכר בהמה לעובריה, כשהיא עצמה \u0003שלמה, דאתיא לאיחלופי\u0004 \u0005[שעשויה להתחלף]\u0006 — \u0003אסר\u0004 \u0005[\u0006הריהו אוסר].","\u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר מצד אחר: \u0003ומה שבורה דפסקה מיניה\u0004 \u0005[ש\u0006היא \u0005פסוקה,\u0006 חתוכה \u0005ממנו],\u0006 שמוכרה מכירה גמורה לגוי, מתיר ר' יהודה, ואינו חושש להחלפה — \u0003כל שכן\u0004 שהוא מתיר למכור \u0003שלמה\u0004 לעובריה, \u0003דלא פסקה מיניה\u0004 \u0005[שאינה חתוכה ממנו],\u0006 שהרי לא מכר את גוף הפרה?","וכן \u0003תיבעי לרבנן\u0004 \u0005[תישאל\u0006 השאלה \u0005ל\u0006דעת \u0005חכמים]:\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאסרי רבנן\u0004 \u0005[אסרו חכמים]\u0006 למכור \u0003אלא בשבורה,\u0004 משום \u0003דפסקה מיניה\u0004 \u0005[ש\u0006היא \u0005חתוכה ממנו]\u0006 ועוברת לגמרי לרשות הגוי, ויבואו למכור לגוי בהמה שלמה, \u0003אבל שלמה\u0004 לעובריה, \u0003דלא פסקה מיניה\u0004 \u0005[שאינה פסוקה,\u0006 חתוכה, \u0005ממנו],\u0006 ואין חשש שיבוא להחליף ולמכור מכירה גמורה — \u0003שרו\u0004 \u0005[\u0006הם \u0005מתירים]. או דלמא\u0006","\u0005[שמא]\u0006 נאמר: \u0003ומה שבורה דלא אתיא לאיחלופי\u0004 \u0005[שאינה עשויה להתחלף]\u0006 בבהמה שלמה. \u0003אסרי\u0004 \u0005[אוסרים]\u0006 חכמים למוכרה — \u0003וכל שכן\u0004 שהם אוסרים מכירת \u0003שלמה\u0004 לעובריה, דאתיא לאיחלופי \u0005[ש\u0006היא עשויה להתחלף] במכירה גמורה של בהמה שלמה? אופן הצגת השאלה מניח שחכמים לא אסרו מכירת שבורה, אלא משום שיבואו להחליף ולמכור גם בהמה שלמה, ולכן נוצר הספק בענין מכירת בהמה לעובריה.","ועל כך תמהים: \u0003וטעמא דרבנן משום הכי הוא\u0004 \u0005[ו\u0006כי \u0005טעמם של חכמים משום כך הוא]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמרו לו\u0004 חכמים לר' יהודה: ומדוע לא תאסור למכור שבורה? \u0003והלא מרביעין עליה ויולדת! אלמא\u0004 \u0005[מכאן]\u0006 שטעמם \u0003משום עובריה הוא,\u0004 ואדרבה, מכאן עולה בבירור כי הם אוסרים למכור בהמה לעובריה!","ומשיבים: אין זה משום שכך הם עצמם סבורים, אלא \u0003הכי קאמרי ליה\u0004 \u0005[כך הם אומרים לו]\u0006 לר' יהודה: \u0003טעמא דידן משום דאתיא לאיחלופי\u0004 \u0005[הטעם שלנו\u0006 לאסור שבורה, \u0005הוא משום שהיא עשויה להתחלף]\u0006 \u0003בבהמה\u0004 אחרת, שלמה. \u0003אלא את\u0004 \u0005[אתה],\u0006 \u0003מאי טעמא שרית\u0004 \u0005[מה טעם התרת]\u0006 למכור שבורה? \u0003משום\u0004 ש\u0003אין יכולה להתרפאות,\u0004 ולכן \u0003כמאן דזבנה\u0004 \u0005[כמי שמוכרה]\u0006 לגוי במפורש \u0003ל\u0004צורך \u0003שחיטה דמי\u0004 \u0005[נחשב],\u0006 ודבר זה מותר.","\u0003והלא מרביעין עליה ויולדת, וכיון\u0004 ש\u0003מרביעין עליה ויולדת משהא לה\u0004 \u0005[משהה אותה],\u0006 ויבואו אנשים לטעות ולהתיר מכירת בהמה רגילה!","\u0003ואמר להו\u0004 \u0005[להם]\u0006 ר' יהודה: \u0003לכשתלד\u0004 בהמה שבורה אחשוש לכך שישהה אותה אצלו. ואולם, בהמה כזו שנשברו רגליה לא מקבלת עליה \u0003זכר.\u0004 ואין מכאן, איפוא, ראיה לדעת חכמים בדין המוכר פרה לעובריה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממשנתנו, ששנינו: \u0003והנותן לו\u0004 לגוי בהמה \u0003בקבלה,\u0004 כלומר, להתחלק בוולדות תמורת טיפול בבהמה. והרי זה ממש מוכר בהמה לעובריה, \u0003ולא קתני\u0004 \u0005[ואינו שונה]\u0006 \u0003\"אף על פי שאינו רשאי\"!\u0004","ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 שאתה מוכיח באופן זה, מה ששנינו במשנה: \u0003המשתתף לו, דלא קתני\u0004 \u0005[ש\u0006גם כן אינו שונה] אף על פי שאינו רשאי, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 אתה רוצה לדייק שהוא \u0003רשאי\u0004 לעשות כן? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל: אסור לאדם שיעשה שותפות עם הגוי, שמא\u0004 מתוך דין ודברים שביניהם יתחייב לו הגוי \u0003שבועה\u0004 בבית המשפט, ונשבע לו בשם עבודה זרה שלו, והתורה אמרה: \"ושם אלהים אחרים לא תזכירו, \u0003לא ישמע על פיך\"\u0004 (שמות כג, יג), שאסור לאדם לגרום שיישמע שם עבודה זרה על ידו!","\u0003אלא, תנא\u0004 \u0005[שנה\u0006 במשנה\u0005]\u0006 \u0003מכירה,\u0004 שאינו רשאי למכור לגוי, \u0003והוא הדין לשותפות\u0004 עמו. \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 אמור בענייננו: \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003מכירה והוא הדין לקבלנות,\u0004 שאינו רשאי לתת לו בהמה לוולדותיה. ושואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003מכירה,\u0004 שדווקא בדוגמא זו \u0003נקט\u0004 \u0005[\u0006הוא \u0005תופס]?\u0006 ומשיבים: משום ש\u0003עיקר\u0004 האיסור בענין זה \u0003מכירה היא.\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדין המוכר בהמה לעובריה ממה ששנינו בברייתא, \u0003ר' יהודה אומר: המקבל בהמה מן הגוי\u0004 להתחלק בוולדות, \u0003וילדה\u0004 בכור — \u0003מעלין אותו\u0004 את הוולד \u0003בשוויו,\u0004 כלומר, מעריכים את דמיו, \u0003ונותן\u0004 הישראל חצי דמיו לכהן, שהוא חלקו בוולד זה. והנותן לגוי בהמה \u0003בקבלה, אף על פי שאינו רשאי\u0004 לעשות כן — \u0003קונסין אותו\u0004 לקנות את חלקו של הגוי \u0003עד עשרה בדמיו, ונותן כל דמיו לכהן.\u0004","\u0003וחכמים אומרים: כל זמן שיד הגוי באמצע,\u0004 שיש לו בעלות מסויימת באם או בבכור — \u0003פטורה מן הבכורה.\u0004"],["\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 על ה\u0003בהמה\u0004 נאמר שאינו רשאי לתיתה בקבלה למחצית עובריה, ובודאי שלא לכל עובריה? ועונים: \u0003לא,\u0004 על ה\u0003עובר.\u0004 כלומר, מדובר כשהיה עובר במעיה, ואינו רשאי למוכרו. אבל מותר למכור בהמה שאינה מעוברת לעובריה.","ומעירים: \u0003דיקא נמי דקתני\u0004 \u0005[מדוייק גם כן ששנינו]:\u0006 \u0003קונסין אותו עד עשרה בדמיו\u0004 בלשון זכר, משמע שעל העובר מדברים. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא. ואין מכאן ראיה שאסור למכור לגוי בהמה לעובריה.","ומעירים: ברייתא זו שהבאנו, ששנינו בה: קונסים אותו עד עשרה בדמיו, \u0003מסייעא ליה\u0004 \u0005[מסייעת לו]\u0006 \u0003לריש לקיש,\u0004 ש\u0003אמר ריש לקיש: המוכר בהמה גסה לגוי\u0004 — \u0003קונסין אותו\u0004 לקנותה מן הגוי \u0003עד עשרה בדמיה.\u0004","לגוף הענין שואלים: האם \"עד עשרה\" נאמר \u0003דוקא או לאו דוקא\u0004 \u0005[בדיוק או לא בדיוק]? ומציעים,\u0006 \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיה ממה ש\u0003אמר ר' יהושע בן לוי: המוכר עבדו\u0004 הכנעני לגוי — קונסין אותו עד מאה בדמיו, ומכאן שמה שנאמר בבהמה \"עד עשרה\" — לא בדיוק נאמר. ודוחים: אין להשוות ביניהם, שמא \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003עבד, דכל יומא ויומא מפקע ליה\u0004 \u0005[שכל יום ויום\u0006 שהוא בידי הגוי הריהו מפקיע אותו] \u0003ממצו‍ת,\u0004 ולכן צריך לקנוס אותו יותר.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 את דברי ריש לקיש והדיון שעליהם באופן אחר. \u0003אמר ריש לקיש: המוכר בהמה גסה לגוי\u0004 — \u0003קונסין אותו עד מאה בדמיה.\u0004 ומתקשים: והרי \u0003תנן\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003והנותן לו\u0004 לגוי בהמה \u0003בקבלה, אף על פי שאינו רשאי, קונסין אותו עד עשרה בדמיה,\u0004 ולא עד מאה!","ומשיבים: ב\u0003מכירה\u0004 לגוי \u0003פסקה מיניה\u0004 \u0005[\u0006\u0005נפסקת\u0006 הבהמה ממנו לגמרי], ב\u0003קבלנות לא פסקה מיניה\u0004 \u0005[אינה פוסקת ממנו\u0006 לגמרי] אלא חוזרת אליו, ולכן אין קונסים אותו כל כך.","ושואלים: מה שאמר ריש לקיש, שקונסים את המוכר עד מאה בדמיה, האם \u0003דוקא או לאו דוקא\u0004 \u0005[בדיוק\u0006 נאמר \u0005או לא בדיוק]?\u0006 ומציעים, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיה ממה ש\u0003אמר ר' יהושע בן לוי: המוכר עבדו לגוי\u0004 — \u0003קונסין אותו עד עשרה בדמיו,\u0004 נמצא שמה שנאמר בבהמה \"עד מאה\" — לא בדיוק נאמר. ודוחים: אין מכאן ראיה, שכן \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003עבד,\u0004 שכבר קנסוהו חכמים \u0003דלא הדר ליה\u0004 \u0005[שאינו חוזר אליו],\u0006 שתיקנו חכמים כי המוכר עבדו לגוי — יצא לחירות.","ושואלים: לפי הסבר זה, \u0003בהמה מאי טעמא\u0004 \u0005[מה טעם]\u0006 קנסוהו לקנותה ביותר ממה שקנסוהו בעבד — \u0003משום דקא הדרא ליה\u0004 \u0005[שהיא חוזרת אליו],\u0006 אם כן \u0003ניקנסיה טפי חד\u0004 \u0005[שנקנוס אותו\u0006 רק \u0005באחד יותר]\u0006 כאילו לא היתה חוזרת אליו, כלומר, רק עד פי אחת עשרה בדמיה, ולא עד פי מאה! \u0003אלא\u0004 יש להסביר באופן אחר: במכירת בהמה, שהיא דבר מצוי, קנסו עד מאה בדמיה, אבל \u0003עבד\u0004 — \u0003מילתא דלא שכיחא היא\u0004 \u0005[דבר שאינו מצוי הוא],\u0006 שאדם מוכר עבדו לגוי, \u0003וכל מילתא דלא שכיחא לא גזרו ביה רבנן\u0004 \u0005[וכל דבר שאינו מצוי לא גזרו בו חכמים]\u0006 כל כך, אלא עד עשרה בדמיו.","שנינו בברייתא, ר' יהודה אומר: המקבל בהמה מן הגוי להשתתף בוולדותיה, או הנותן לו בהמה בקבלה — חלקו של הישראל קדוש בבכורה. \u0003וחכמים אומרים כל זמן שיד הגוי\u0004 באמצע, כלומר, שיש לו חלק בבכור — הריהו פטור מן הבכורה. \u0003אמר ר' יהושע: ושניהם מקרא אחד דרשו,\u0004 שנאמר: \"קדש לי \u0003כל בכור\u0004 פטר כל רחם בבני ישראל\" (שמות יג, ב),","\u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003\"בכור...\u0004 בבני ישראל\" — \u0003מקצת בכור משמע,\u0004 שאפילו מקצת הבכור של ישראל — חייב בבכורה, לכך \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"כל\"\u0004 — ללמד שאינו קדוש בבכורה \u0003עד דאיכא כוליה\u0004 \u0005[עד שישנו כולו]\u0006 של ישראל. ואילו \u0003ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003\"בכור\"\u0004 — \u0003כוליה\u0004 \u0005[כל]\u0006 ה\u0003בכור משמע,\u0004 שדוקא אם כולו של ישראל חייב בבכורה, לכך \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"כל\"\u0004 — ש\u0003אפילו כל\u0004 ש","\u0003הוא\u0004 מן הבכור של ישראל — חייב בבכורה. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 באופן אחר: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003\"בכור\"\u0004 — \u0003רובא\u0004 \u0005[הרוב]\u0006 \u0003משמע,\u0004 שאם רובו של ישראל — חייב בבכורה. מר סבר \u0005[חכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003\"כל\" משמע למלויי אתא\u0004 \u0005[למלא בא],\u0006 ללמד שדוקא אם כולו של ישראל חייב. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה, \u0005סבור]:\u0006 \"כל\" \u0003לגרועי אתא\u0004 \u0005[לגרוע בא],\u0006 ללמד שאפילו מקצתו חייב.","ושואלים: \u0003ו\u0004לדעת חכמים, \u0003כמה תהא שותפות של גוי\u0004 בעובר, \u0003ותהא פטורה מן הבכורה? אמר רב הונא: אפילו\u0004 אין לו אלא \u0003אזנו. מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב נחמן: ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 הכהן לגוי: \u0003שקיל אזנך וזיל\u0004 \u0005[קח את אזנך ולך]!\u0006","ומעירים: \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בנושא זה, \u0003רב חסדא אמר:\u0004 אם יש לגוי שותפות ב\u0003דבר שעושה אותו\u0004 \u0003נבלה\u0004 כלומר, שאם יינטל ממנו ימות — הריהו פוטר מבכורה, \u0003ורבא אמר:\u0004 אם יש לגוי שותפות ב\u0003דבר שעושה אותו טריפה\u0004 שאינו מת מיד אם יינטל, אבל התורה אסרה אותו באכילה מפני שהוא עתיד למות מחמת כן.","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חלוקים]?\u0006 ומשיבים: \u0003ב\u0004שאלה האם \u0003טריפה\u0004 שאסרה התורה \u0003חיה,\u0004 האם היא יכולה להמשיך ולחיות כך לאורך זמן. \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי שותפות הגוי ב\u0003דבר שעושה אותו טריפה\u0004 פוטרת מן הבכורה, הרי זה משום שהוא \u0003קסבר\u0004 \u0005[סבור]\u0006 ש\u0003טריפה אינה חיה,\u0004 ויש לגוי איפוא חלק מהותי בבהמה. \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 ששותפות הגוי ב\u0003דבר שעושה אותו נבלה\u0004 פוטרת מן הבכורה — הרי זה משום שאינה יכולה לחיות בלא חלק זה, \u0003אבל טריפה\u0004 — \u0003חיה.\u0004","\u0003אמרוה רבנן קמיה\u0004 \u0005[אמרו חכמים לפני]\u0006 \u0003רב פפא: הא\u0004 \u0005[זה]\u0006 שאמר \u0003רב הונא,\u0004 ששותפות הגוי אפילו באזנו של הבכור פוטרת, \u0003ו\u0004זה שאמרו \u0003רב חסדא ורבא,\u0004 שדווקא אם היה שותף בעיקר חייה של הבהמה הרי זה פוטר — \u0003לא פליגי\u0004 \u0005[אינם חלוקים],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר רב הונא — \u0003בו,\u0004 בעובר, \u0003הא\u0004 \u0005[זה]\u0006 שאמרו רב חסדא ורבא — \u0003באמו.\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב פפא: מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003בו,\u0004 שדי בשותפות באוזנו — משום \u0003דבעינן\u0004 \u0005[שאנו צריכים]\u0006 לקיים \u0003\"כל בכור\"\u0004 (שמות יג, טו) \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 ב\u0003אמו נמי\u0004 \u0005[גם כן]\u0006 \u0003בעינן\u0004 \u0005[אנו צריכים]\u0006 \u0003\"כל מקנך תזכר\"\u0004 (שמות לד, יט) \u0003וליכא\u0004 \u0005[ואין כאן]!\u0006 \u0003אלא, לא שנא\u0004 \u0005[אינו שונה],\u0006 וכשם שהם חלוקים בעובר כך הם חלוקים באם.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003מר בר רב אשי:\u0004 ומדוע אם עיקר חייו של העובר בידיו של הגוי הרי זה פוטר מן הבכורה? \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 הדבר \u0003מנפלים, דאף על גב דלאו בני חיותא נינהו קדשי\u0004 \u0005[שאף על פי שאין להם חיות\u0006 וכנבילה הם, הריהם קדושים], \u0003דאמר מר\u0004 \u0005[שאמר החכם]\u0006 על הכתוב: \u0003\"פטר שגר בהמה\u0004 וכו' הזכרים לה' \" (שמות יג, יב) — העובר \u0003שגר בבהמה,\u0004 שמקומו ברחם אמו, ויצא קודם זמנו, גם הוא קדוש בבכורה!","ומשיבים: \u0003התם\u0004 \u0005[שם,\u0006 בנפלים] \u0003כיון דלא עריבו בהו\u0004 \u0005[שלא נתערבו בהם\u0006\u0005]\u0006 \u0003חולין\u0004 — \u0003קרינא בהו\u0004 \u0005[קוראים אנו בהם]\u0006 \u0003בבהמה \"כל בכור...\u0004 בישראל\", אבל \u0003הכא\u0004 \u0005[כאן],\u0006 כשיש לגוי חלק בעוברים, \u0003כיון דעריבו בהו\u0004 \u0005[שמעורבים בהם]\u0006 \u0003חולין\u0004 — \u0003לא קרינא בהו\u0004 \u0005[אין קוראים בהם]\u0006 \u0003\"כל בכור\u0004 בישראל\".","מסופר, פעם אחת \u0003ר' אלעזר לא על לבי מדרשא\u0004 \u0005[לא נכנס לבית המדרש],\u0006 \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 את \u0003ר' אסי, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי אמור רבנן בי מדרשא\u0004 \u0005[מה אמרו חכמים בבית המדרש]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006"],["\u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: אפילו\u0004 יש לגוי בבהמה איבר שאם יינטל יהיה בה \u0003מום קל,\u0004 הריהי פטורה מן הבכורה. ועוד אמר ר' יוחנן, \u0003והדתנן\u0004 \u0005[וזו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003רחל שילדה\u0004 בכור שהוא \u0003מין עז, ועז שילדה מין רחל\u0004 — \u0003פטורה מן הבכורה, ואם יש בו מקצת סימנין\u0004 של אימו — \u0003חייב\u0004 בבכורה, מכל מקום אין מקריבים אותו, לפי ש\u0003מום קבוע הוי\u0004 \u0005[הוא],\u0006 שאינו עתיד לעבור, שמותר לכהן \u0003לשחוט עליו\u0004 (בגללו) את הבכור מחוץ למקדש.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מה שאמר ר' יוחנן: אפילו \u0003מום קל, קא משמע לן\u0004 \u0005[\u0006הריהו \u0005משמיע לנו]\u0006 \u0003כ\u0004דברי \u0003רב הונא\u0004 בעמוד הקודם, שגם אם אין לגוי שותפות אלא באזנו של עובר הריהו פטור מן הבכורה, \u0003ולאפוקי\u0004 \u0005[ולהוציא]\u0006 \u0003מ\u0004דברי \u0003רב חסדא ורבא,\u0004 שאמרו שצריך שיהיה לגוי חלק בעובר שאם יינטל יעשה אותו נבילה או טריפה.","\u0003אלא\u0004 מה שאמר ר' יוחנן שרחל שילדה מין עז, אם יש בו מקצת סימנים של אמו הרי זה \u0003מום קבוע\u0004 — \u0003מאי קא משמע לן\u0004 \u0005[מה הוא משמיע,\u0006 מחדש, \u0005לנו]?\u0006 \u0003דכיון דאישתני הוה ליה מומא\u0004 \u0005[שכיון שנשתנה\u0006 ממראה כבש \u0005הרי זה מום]?\u0006 הלוא \u0003תנינא\u0004 \u0005[\u0006כבר \u0005שנינו]\u0006 דבר זה במשנה: אם \u0003פיו\u0004 של טלה \u0003דומה כשל חזיר\u0004 — \u0003הרי זה מום!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שהיה מקום לחלק: \u0003התם\u0004 \u0005[שם]\u0006 שפיו דומה לשל חזיר — \u0003נשתנה ב\u0004צורת \u0003דבר שאין במינו קדוש בבכורה,\u0004 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 שהוא כמין עז \u0003נשתנה בדבר שבמינו קדוש בבכורה,\u0004 והוצרך ר' יוחנן לחדש שאף זה נחשב מום — \u0003הא נמי תנינא\u0004 \u0005[זו גם כן שנינו]\u0006 ברשימת בעלי המומים שמותר לשוחטם מחוץ למקדש: \u0003עינו אחת\u0004 של כבש \u0003גדולה ואחת קטנה\u0004,","\u0003ותנא\u0004 \u0005[ושנה\u0006 החכם\u0005]\u0006 בהסבר המשנה: \u0003גדולה\u0004 — \u0003גדולה כשל עגל, וקטנה\u0004 — \u0003קטנה כשל אווז!\u0004 ומוסיפים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 כשהוא אומר \u0003קטנה כשל אווז,\u0004 יכול אתה לומר כי טעם הדבר הוא — משום ש\u0003אין במינו קדוש בבכורה,\u0004 שאין דין בכורה בעוף. \u0003אלא גדולה כשל עגל,\u0004 הלוא \u0003יש במינו קדוש בבכורה! אלא לאו משום דאמרינן\u0004 \u0005[האם לא משום שאנו אומרים]:\u0006 \u0003כיון דאישתני הוה ליה מומא\u0004 \u0005[כיון שהשתנה\u0006 מצורת כבש \u0005הרי זה מום]?\u0006 ואם כן לא חידש ר' יוחנן דבר!","ודוחים: \u0003לא,\u0004 טעם הדבר שעינו גדולה כשל עגל הרי זה מום — אין זה משום שנשתנה מצורת כבש, אלא \u0003משום דהוה ליה\u0004 \u0005[שהוא נעשה]\u0006 \u0003שרוע,\u0004 שנזכר בתורה ברשימת בעלי המומים (ויקרא כב, כג), כלומר, שאחד מאיבריו גדול במיוחד. ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר\u0006 לומר\u0005],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מומין אלו\u0004 שמנתה המשנה בבהמה, שפוסלים אותה להקרבה, \u0003בין\u0004 מומין \u0003קבועין בין עוברין\u0004 — \u0003פוסלין\u0004 באדם, שאם היו בכהן — הריהו פסול לעבודה. \u0003יתר עליהן\u0004 על מומי הבהמה, מומים נוספים ב\u0003אדם,\u0004 ובכללם — אם היו \u0003עיניו שתיהן גדולות\u0004 או \u0003שתיהן קטנות.\u0004","וטעם הדבר: \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003אדם הוא דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"איש איש מזרע אהרן\"\u0004 (ויקרא כב, ד), \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 לעבודת המקדש \u0003איש\u0004 שהוא \u0003שוה\u0004 (רגיל) \u0003בזרעו של אהרן,\u0004 ולא משונה. \u0003אבל\u0004 ב\u0003בהמה,\u0004 אם עיניה \u0003שתיהן גדולות\u0004 או \u0003שתיהן קטנות\u0004 — \u0003נמי לא הוי מומא\u0004 \u0005[גם כן איננו מום].\u0006","ויש לשאול: עינו \u0003אחת גדולה ואחת קטנה מאי טעמא\u0004 \u0005[מה טעם]\u0006 הוא מום בבהמה? \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום שינוי,\u0004 שאין הוא נראה ככבש — \u0003אפילו שתיהן גדולות\u0004 או \u0003שתיהן קטנות נמי\u0004 \u0005[גם כן]\u0006 היה צריך לפסול! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום דהוה ליה\u0004 \u0005[שהוא]\u0006 \u0003שרוע?\u0004","ודוחים: \u0003לא, לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 שהטעם בעינו אחת גדולה ואחת קטנה הוא \u0003משום שינוי,\u0004 ו\u0003שינוי הוי מומא\u0004 \u0005[הרי הוא מום].\u0006 \u0003ודקא קשיא\u0004 \u0005[ו\u0006מה \u0005שהיה קשה]\u0006 \u0003לך:\u0004 אם משום שינוי, \u0003אפילו שתיהן גדולות\u0004 או \u0003שתיהן קטנות\u0004 צריך היה להיות מום — \u0003התם\u0004 \u0005[שם]\u0006 אין זה נחשב שינוי, שבהמה בריאה ושמנה במיוחד עיניה גדולות, וכחושה במיוחד עיניה קטנות. ודוקא בעין אחת גדולה ואחת קטנה הרי זה נחשב כשינוי שהוא מום, שכן \u0003אי מחמת בריותא יתירא\u0004 — \u0003תרווייהו בעי למיברא\u0004 \u0005[אם מחמת בריאות יתירה\u0006 — \u0005שתיהם היו צריכות להבריא],\u0006 \u0003אי מחמת כחישותא יתירא תרווייהו בעי מיכחש\u0004 \u0005[אם מחמת כחש יתר\u0006 — \u0005שתיהם היו צריכות לכחוש].\u0006","כאמור לעיל נחלקו ר' יהודה וחכמים האם שותפות הגוי בבהמה פוטרת מן הבכורה. ובענין זה מסופר, \u0003ההיא גיורתא דהוו מסרין לה אחי חיותא לפטומה\u0004 \u0005[גיורת אחת שהיו מוסרים לה אחיה\u0006 הגויים \u0005בהמות לפיטום]\u0006 ולהשתתף בשבח שתשביח הפרה, \u0003אתאי לקמיה\u0004 \u0005[באה לפני]\u0006 \u0003רבא\u0004 לשאול האם הבכורות של בהמות אלו קדושים בבכורה. \u0003אמר לה: לית דחש לה להא\u0004 \u0005[אין מי שחושש לה ל\u0006הלכה \u0005זו]\u0006 של \u0003ר' יהודה,\u0004 ש\u0003אמר: שותפות גוי חייבת בבכורה.\u0004","ועוד מסופר, \u0003רב מרי בר רחל הויא ליה ההיא חיותא\u0004 \u0005[היה לו\u0006 עדר \u0005בעלי חיים,\u0006 בהמות\u0005],\u0006 \u0003הוה מקנה לאודנייהו\u0004 \u0005[היה מקנה את אוזניהם]\u0006 של העוברים \u0003לגוי\u0004 כדי להפקיעם מן הבכורה, וכך לא היו קדושים בבכורה בלידתם (שאין קדושת בכורה חלה אלא בשעת הלידה, ובשעת הלידה יש לגוי בהם חלק). \u0003ו\u0004מכל מקום \u0003אסר להו\u0004 \u0005[\u0006היה \u0005אוסר אותם\u0006 את הבכורות\u0005]\u0006 \u0003בגיזה ועבודה\u0004 כדין בכור, שאסור לגזוז את צמרו ולעבוד בו, \u0003ויהיב להו\u0004 \u0005[ו\u0006כן היה \u0005נותן אותם]\u0006 \u0003לכהנים,\u0004 כדין בכור. \u0003ו\u0004מסופר כי \u0003כלאי חיותא\u0004 \u0005[כלו,\u0006 מתו, \u0005הבהמות]\u0006 של \u0003רב מרי בר רחל.\u0004","ושואלים: \u0003וכי מאחר דאסר להו\u0004 \u0005[ש\u0006היה \u0005אוסר אותם]\u0006 \u0003בגיזה ועבודה, ויהיב להו\u0004 \u0005[ונותן אותם]\u0006 \u0003לכהנים,\u0004 כדין בכור, \u0003אמאי מקנה להו לאודנייהו\u0004 \u0005[מדוע\u0006 היה \u0005מקנה את אוזניהם]\u0006 מתחילה \u0003לגוי,\u0004 ומפקיעם מן הבכורה? ומשיבים: עשה כן מחשש \u0003דלמא אתי בהו\u0004 \u0005[שמא יבואו בהם]\u0006 \u0003לידי תקלה,\u0004 שיגזזו אותם או יעבדו בהם. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003מאי טעמא כלו חיותא\u0004 \u0005[מה הטעם כלו הבהמות]\u0006 של \u0003רב מרי?\u0004 מדוע נענש? ומשיבים: \u0003משום דמפקע להו מקדושתייהו\u0004 \u0005[ש\u0006היה \u0005מפקיע אותם מקדושתם]\u0006 על ידי מכירת אוזניהם.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה: מותר לאדם להטיל מום בבכור קודם שיצא לאויר העולם!\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 שמטיל בו מום — \u0003מקדושת מזבח קא מפקע ליה\u0004 \u0005[הוא מפקיע אותו],\u0006 שאינו ראוי להקרבה. אבל \u0003מקדושת כהן,\u0004 שיהיה של הכהן, \u0003לא מפקע ליה\u0004 \u0005[אינו מפקיע אותו],\u0006 \u0003הכא\u0004 \u0005[כאן],\u0006 שמוכר את אוזנו לגוי — \u0003אפילו מקדושת כהן קא מפקע ליה\u0004 \u0005[מפקיע אותו],\u0006 שהרי שותפות הגוי פוטרת את העובר מן הבכורה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר, מדוע מתו בהמותיו של רב מרי בר רחל: \u0003רב מרי בר רחל ידע לאקנויי\u0004 \u0005[יודע\u0006 היה \u0005להקנות]\u0006 לגוי \u0003קנין גמור\u0004 את אוזנו של העובר, \u0003ו\u0004אולם \u0003חזי ליה איניש אחרינא, ואזיל ועביד\u0004 \u0005[רואה\u0006 היה \u0005אדם אחר\u0006 את רב מרי עושה כן, \u0005והולך ועושה\u0006 כמותו\u0005],\u0006 למכור את אוזן העובר לגוי, \u0003וסבר\u0004 \u0005[וסבור]\u0006 כי \u0003רב מרי מילתא הוא דעבד\u0004 \u0005[דבר\u0006 של מה בכך \u0005הוא שעשה]\u0006 לצורך הקנאה זו, הפקעת הבכורה, ואין לדקדק בדבר ולהקנות כראוי. \u0003ואתי\u0004 \u0005[ובא]\u0006 \u0003בה\u0004 אותו אדם \u0003לידי תקלה,\u0004 שלא להקנות כראוי, ומשום כך מתו בהמותיו של רב מרי, שבאה תקלה על ידן.","\u0003כהנים ולוים פטורין\u0004 מפדיון פטר חמור שלהם \u0003מקל וחומר: אם פטרו את\u0004 בכורותיהם \u0003של ישראל במדבר\u0004 מן הבכורה, שנפדו על ידם, שנאמר: \"קח את הלויים תחת כל בכור בבני ישראל\" (במדבר ג, מה), \u0003דין הוא שיפטרו את\u0004 בכורות חמוריהם \u0003של עצמן\u0004 מן הבכורה."],["מלשון המשנה \"אם פטרו את של ישראל במדבר\", משמע שהכהנים והלויים עצמם באו תחת פטרי חמוריהם של ישראל. ותמהים: \u0003אינהו פטרי\u0004 \u0005[\u0006וכי \u0005הם\u0006 עצמם \u0005פטרו]?\u0006 הלוא \u0003אדם\u0004 — \u0003אדם פטר, בהמה\u0004 — \u0003בהמה פטרה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"קח את הלוים תחת\u0004 כל \u0003בכור בבני ישראל ואת בהמת הלוים תחת בהמתם\"\u0004 (במדבר ג, מה)!","\u0003אמר אביי, הכי קאמר\u0004 \u0005[כך הוא,\u0006 התנא \u0005אומר]:\u0006 \u0003כהנים ולוים\u0004 — \u0003פטורין בהמתם\u0004 מן הבכורה \u0003מקל וחומר: אם הפקיעה\u0004 (הוציאה, פטרה) \u0003בהמתם של לוים\u0004 (בני לוי, כהנים ולויים) \u0003בהמה של ישראל במדבר\u0004 מן הבכורה — \u0003דין הוא שתפקיע את\u0004 בהמתם \u0003של עצמן\u0004 מן הבכורה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 כיצד יכול אתה לפרש את הקל וחומר שבמשנה על בהמתם של הכהנים והלויים? \u0003והא \"פטרו\" אינהו קתני\u0004 \u0005[והרי פטרו הם,\u0006 הכהנים והלויים, הוא \u0005שונה],\u0006 ולא בהמתם פטרה!","\u0003ועוד, אם איתא\u0004 \u0005[אם כן הוא],\u0006 שבהמתם פטורה מקל וחומר — \u0003אפילו מבכור בהמה טהורה נפטרו\u0004 \u0005[ייפטרו]\u0006 הכהנים והלויים, שהרי גם בהמה טהורה שלהם פטרה בהמה טהורה של ישראל במדבר. \u0003אלמה תנן\u0004 \u0005[מדוע שנינו]\u0006 להלן: \u0003לא נפטרו\u0004 הכהנים והלויים \u0003מבכור בהמה טהורה, אלא מפדיון הבן ופטר חמור?\u0004","\u0003אלא אמר רבא, הכי קתני\u0004 \u0005[כך\u0006 הוא \u0005שונה]\u0006 במשנה: \u0003כהנים ולוים פטרו הן עצמן מקל וחומר, אם הפקיעה קדושתן של לוים קדושה של\u0004 בכורי \u0003ישראל במדבר, לא יפקיע את\u0004 קדושת הבכורה \u0003של\u0004 בכורי הלויים \u0003עצמן?\u0004","ויש לשאול: \u0003אשכחן\u0004 \u0005[מצאנו\u0006 איפוא\u0005]\u0006 מקור לפטור את הלויים מדין בכור \u0003אדם, בהמה טמאה\u0004 (כלומר, פטר חמור) שלהם, \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 על כך יש להשיב, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אך פדה תפדה את בכור האדם ואת בכור הבהמה הטמאה תפדה\"\u0004 (במדבר יח, טו), כדי להקישם זה לזה: \u0003כל שישנו בבכור אדם\u0004 — \u0003ישנו בבכור בהמה טמאה, וכל שאינו בבכור אדם\u0004 — \u0003אינו בבכור בהמה טמאה.\u0004","בעקבות דיון זה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ספרא לאביי\u0004 בתמיהה: \u0003לדידך דאמרת\u0004 \u0005[לשיטתך שאתה אומר]\u0006 ש\u0003בהמתם\u0004 של הלויים נפטרה מן הבכורה בקל וחומר, שהרי הפקיעה את בהמתם של ישראל מן הבכורה, צריכים אנו לומר: \u0003בן\u0004 שבט \u0003לוי דהוה ליה\u0004 \u0005[שהיה לו]\u0006 \u0003שה דאפקע\u0004 \u0005[שהפקיע]\u0006 פטרי חמורי ישראל במדבר מן הבכורה — \u0003ליפקע\u0004 \u0005[שיפקע]\u0006 דין בכורה מבהמותיו, אבל זה \u0003דלא הוה ליה שה דליפקע\u0004 \u0005[שלא היה לו שה שיפקיע]\u0006 — \u0003לא ליפקע\u0004 \u0005[שלא יפקע].\u0006","וכן יש להקשות: \u0003בין לדידך\u0004 \u0005[לשיטתך]\u0006 ו\u0003בין ל\u0004שיטת \u0003רבא,\u0004 שלדעת שניכם נפטרו הלויים עצמם מתוך שהפקיעו את קדושת בכורות ישראל, יש להסיק: דווקא לוי \u0003בן חדש,\u0004 שנמנה במנין הלויים שבאו תחת בכורות ישראל, \u0003דאפקע\u0004 \u0005[ש\u0006יכול היה \u0005להפקיע]\u0006 — \u0003ליפקע\u0004 \u0005[שיפקע]\u0006 דין הבכורה ממנו, \u0003פחות מבן חדש דלא אפקע\u0004 \u0005[שלא\u0006 יכול היה \u0005להפקיע]\u0006 בכורה במדבר — \u0003לא ליפקע\u0004 \u0005[שלא יפקע]\u0006 דין הבכורה ממנו!","ועוד, אשה \u0003לויה\u0004 שילדה בן ואביו ישראל — \u0003לא תיפקע\u0004 \u0005[תפקע]\u0006 קדושת הבכורה ממנה, שהרי הנשים לא נמנו במנין הלויים שבאו תחת בכורות ישראל, \u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003אמר רב אדא בר אהבה: לויה שילדה\u0004 — \u0003בנה פטור מחמש סלעים\u0004 של פדיון הבן?","ודוחים: \u0003הא לא קשיא\u0004 \u0005[זו אינה קשה],\u0006 \u0003כ\u0004מו שאמר \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא,\u0004 ש\u0003אמר:\u0004 ממה שנאמר בענין קדושת הבכור \u0003\"פטר רחם\"\u0004 (שמות יג, יב ועוד) יש ללמוד כי \u0003בפטר רחם תלה רחמנא\u0004 \u0005[תלתה התורה]\u0006 את דין הבכורה, כלומר, באם היולדת. וכיון שכן — כל שנולד ללויה הריהו פטור מן הבכורה.","וחוזר ומקשה רב ספרא על שיטת אביי ורבא: \u0003ואהרן שלא היה\u0004 מנוי \u0003באותו מנין\u0004 של הלויים, ואם כן לא הפקיע את הקדושה מבכור ישראל — \u0003לא ליפקע\u0004 \u0005[יפקע]\u0006 דין בכורה ממנו, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003למה נקוד\u0004 (רשומות נקודות) \u0003על\u0004 המלה \u0003\"אהרן\" שבחומש הפקודים,\u0004 בפסוק \"כל פקודי הלויים אשר פקד משה ואהרן\" (במדבר ג, לט) — כדי ללמד \u0003שלא היה באותו מנין\u0004 של הלויים!","ומשיבים, \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בענין זה: \u0003\"הלוים\"\u0004 (במדבר ג, מה), לומר: \u0003הוקשו כל הלוים זה לזה,\u0004 ואף לוי שלא הפקיע בעצמו את בכורות ישראל פוקע ממנו דין בכורה.","ומוסיפים: \u0003כהנים\u0004 ובכללם אהרן, מנלן \u0005[מנין לנו]\u0006 שגם הם בכלל זה — \u0003כ\u0004דברי \u0003ר' יהושע בן לוי,\u0004 ש\u0003אמר ר' יהושע בן לוי: בעשרים וארבעה מקומות נקראו\u0004 ה\u0003כהנים \"לוים\", וזה אחד מהן: \"והכהנים הלוים בני צדוק\"\u0004 (יחזקאל מד,טו), ומשם יש ללמוד כי גם במקום שלא נזכרו במפורש — הריהם בכלל הלויים."],["ועוד שואלים: \u0003ולדורות מנלן\u0004 \u0005[מנין לנו]\u0006 שהכהנים והלויים פטורים מן הבכורה? ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 באותה פרשה: \u0003\"והיו לי הלוים\"\u0004 (במדבר ג, יח), \u0003\"והיו\"\u0004 — כוונתו \u0003בהווייתן יהו,\u0004 כפי שהם, בקדושתם.","בדברי רב ספרא שבעמוד הקודם נזכר כי בשעה שנבחרו הלויים במדבר, פטר שה של לוי את פטרי חמוריהם של ישראל מן הבכורה. ושואלים: \u0003וממאי\u0004 \u0005[ומנין]\u0006 שהיה הדבר \u0003בשה? אמר רב חסדא: נאמר כסף לדורות\u0004 בפדיון בכור אדם (\"תפדה בערכך כסף חמשת שקלים\", במדבר יח, טז), \u0003ונאמר שה לדורות\u0004 בפדיון פטר חמור (\"וכל פטר חמור תפדה בשה\", שמות יג, יג), ויש ללמוד מזה על זה:","\u0003מה כסף האמור לדורות\u0004 — \u0003בו פדו לדורות,\u0004 וגם \u0003בו פדו לאותה שעה,\u0004 שהרי הבכורות העודפים על מנין הלויים צריכים היו לפדות עצמם בחמשה שקלים (ראה במדבר ג, מז), \u0003אף שה האמור לדורות\u0004 — \u0003בו פדו לדורות, בו פדו באותה שעה.\u0004","ודוחים את ההוכחה: \u0003מה לכסף\u0004 שפדו בו לשעה ולדורות, שהרי הוא משמש באופן כללי לפדיון, \u0003שכן פודין בו הקדשות ומעשר שני,\u0004 אבל לא מצאנו כן לגבי שה!","\u0003אלא\u0004 מכאן יש ללמוד, ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אך פדה תפדה את בכור האדם ואת בכור הבהמה הטמאה תפדה\"\u0004 (במדבר יח, טו), והכתוב מקישם זה לזה: \u0003מה בכור אדם לא חלקת בין לדורות בין לאותה שעה\u0004 שהוא נפדה \u0003בכסף, אף בהמה טמאה\u0004 — \u0003לא תחלוק בו בין לדורות בין לאותה שעה,\u0004 שהוא נפדה \u0003בשה.\u0004","ועוד בפדיון פטרי החמורים שבאותה שעה, שנלקחו הלויים תחת בכורות ישראל ובהמות הלויים תחת בכורות בהמות ישראל. \u0003אמר ר' חנינא: שה אחד של בן לוי\u0004 במדבר \u0003פטר כמה פטרי חמורים מישראל. אמר אביי: תדע\u0004 שכן הוא, \u0003שהרי מנה הכתוב עודפים באדם,\u0004 שהזכיר הכתוב שהיו בכורות ישראל יתירים על מנין הלויים מאתיים שבעים ושלושה, והוצרכו לפדיון בכסף, \u0003ולא מנה עודפין בבהמה.\u0004","ושואלים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מניין\u0005]\u0006 אתה מוכיח? \u0003דילמא לא הוי נפישי להו בהמות טובא\u0004 \u0005[שמא לא היו להם\u0006 לישראל \u0005בהמות הרבה],\u0006 ולא היו בכורי החמורים עודפים על בהמות הלויים! ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 לומר כן, \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"ומקנה רב היה לבני ראובן ולבני גד\"\u0004 (במדבר לב, א).","ומקשים: \u0003דילמא אפילו הכי\u0004 \u0005[שמא אפילו כך],\u0006 \u0003פשוטים דלוים הוו קיימי לבהדי\u0004 \u0005[\u0006בהמות \u0005פשוטות של הלויים,\u0006 שאינן בכורות, \u0005היו עומדות,\u0006 שוות במספרן, \u0005כנגד]\u0006 \u0003בכורי\u0004 בהמות \u0003ישראל!\u0004 ומשיבים: מכל מקום, ראיה יש לדבר מלשון המקרא, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 קח את הלויים תחת כל בכור בבני ישראל, \u0003ואת בהמת הלוים תחת בהמתם\"\u0004 (במדבר ג, מה) — \u0003בהמה אחת\u0004 (\"בהמת\") \u0003תחת בהמות הרבה\u0004 (\"בהמות\").","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כי \"בהמת\" משמעו לשון כללית, כמו \u0003\"בהמה רבה\"\u0004 (יונה ד, יא)! ומשיבים: \u0003אם כן, ליכתוב קרא\u0004 \u0005[שיכתוב המקרא]\u0006 \u0003או \"בהמה תחת בהמה\" או \"בהמתם תחת בהמתם\", מאי\u0004 \u0005[מה]\u0006 משמעות שינוי הלשון \u0003\"בהמת תחת בהמתם\"?\u0004 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003חד פטר טובא\u0004 \u0005[אחד\u0006 של לויים \u0005פטר הרבה\u0006 של ישראל\u0005].\u0006","\u0003אמר רבא, אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 כדברי ר' חנינא, במשנה להלן: \u0003ופודה בו,\u0004 בשה אחד, \u0003פעמים הרבה,\u0004 שנותנו לכהן בפדיון פטר חמור, וחוזר ולוקחו ממנו, ופודה בו פטר חמור נוסף, וכן הלאה. ולפי זה \u0003ר' חנינא\u0004 לא חידוש משלו אמר, אלא \u0003טעמא דמתניתא\u0004 \u0005[\u0006את \u0005טעמה של המשנה]\u0006 הוא \u0003מפרש, והכי קאמר\u0004 \u0005[וכך\u0006 הוא \u0005אומר]:\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003פודה בו פעמים הרבה? משום\u0004 ש\u0003שה אחד של בן לוי פוטר\u0004 היה במדבר \u0003כמה פטרי חמורים של ישראל.\u0004","ובענין קדושת הבכורות שבמדבר, \u0003איתמר\u0004 \u0005[נאמר],\u0006 \u0003ר' יוחנן אמר: קדשו בכורות\u0004 שנולדו \u0003במדבר\u0004 (בין בכור אדם ובין בכור בהמה), \u0003וריש לקיש אמר: לא קדשו בכורות\u0004 שנולדו \u0003במדבר.\u0004","ומסבירים את טעמיהם, \u0003ר' יוחנן אמר קדשו בכורות\u0004 שנולדו \u0003במדבר\u0004 — \u0003דרחמנא אמר\u0004 \u0005[ש\u0006הרי \u0005התורה אמרה]\u0006 \u0003ליקדשו\u0004 \u0005[שיתקדשו], כדכתיב\u0006 \u0005[כמו שנאמר]\u0006 קודם יציאת מצרים: \u0003\"קדש לי כל בכור\"\u0004 (שמות יג, ב).","\u0003וריש לקיש אמר:\u0004 אמנם קדשו הבכורות שבמצרים, אבל \u0003לא קדשו בכורות\u0004 שנולדו \u0003במדבר.\u0004 וראייתו, \u0003מדכתיב\u0004 \u0005[ממה שנאמר]\u0006 בענין הבכורות: \u0003\"והיה כי יביאך\u0004 אל ארץ הכנעני\" (שמות יג, יא) \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו]:\u0006 \u0003\"והעברת\u0004 כל פטר רחם לה'\" (במדבר ג, יב), ו\u0003מכלל\u0004 הדברים אתה למד \u0003דמעיקרא\u0004 \u0005[שמתחילה],\u0006 במדבר, אלה שנולדו שם \u0003לא\u0004 \u0003קדוש\u0004 \u0005[קדשו].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו במשנה: \u0003עד שלא הוקם המשכן\u0004 במדבר \u0003היו במות מותרות,\u0004 כלומר, מותר היה לכל אחד לבנות מזבח ולהקריב עליו קרבן, ועבודה של הקרבת הקרבנות היתה \u0003בבכורות.\u0004 הרי שהיו הבכורות קדושים במדבר! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: מדובר שם \u0003באותן\u0004 בכורות \u0003שיצאו ממצרים,\u0004 ולא אלו שנולדו במדבר.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר],\u0006 שהבכורות שיצאו ממצרים הם שהקריבו קודם שהוקם המשכן, \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך],\u0006 וכי \u0003בן שנה בר מיעבד\u0004 \u0005[בן עשיית]\u0006 \u0003עבודה הוא?\u0004 והרי שנה לאחר שיצאו ממצרים כבר הוקם המשכן.","ושואלים: \u0003ודקארי לה מאי קארי לה\u0004 \u0005[ומי שמקשה אותה,\u0006 ר' יוחנן שמביא ראיה זו כנגד ריש לקיש, \u0005מהו מקשה אותה]?\u0006 הרי ברור שהבכורות שנולדו במצרים הם שהקריבו באותה שעה!","ומשיבים: \u0003הכי קא קשיא ליה\u0004 \u0005[כך קשה לו]:\u0006 \u0003אי אמרת בשלמא דלא פסיק קדושתייהו\u0004 \u0005[נניח אם אתה אומר שלא פסקה קדושתם]\u0006 של בכורות, משעה שנאמר במצרים \"קדש לי כל בכור\", וגם אלו שנולדו במדבר היו קדושים — \u0003הנך דמעיקרא נמי לא פקעא קדושתייהו\u0004 \u0005[אלה שמתחילה,\u0006 הבכורות שנולדו במצרים, \u0005גם כן לא פקעה קדושתם],\u0006 ולכן הקריבו קודם שהוקם המשכן. \u0003אלא אי אמרת דפסק קדושתייהו\u0004 \u0005[אם אתה אומר שפסקה קדושתם]\u0006 של בכורות, ולא קדשו בכורות במדבר — \u0003הנך דמעיקרא נמי פקעא ליה קדושתייהו\u0004 \u0005[אלה שמתחילה גם כן פקעה קדושתם]!\u0006","\u0003ואידך\u0004 \u0005[והאחר,\u0006 ריש לקיש\u0005]\u0006 משיב: אין מכאן ראיה, אלא \u0003דקדוש\u0004 — \u0003קדוש\u0004 \u0005[\u0006מי \u0005שקדש\u0006 במצרים — \u0005קדש]\u0006 ושוב לא פקעה קדושה ממנו, מי \u0003דלא קדוש\u0004 — \u0003לא קדוש\u0004 \u0005[\u0006\u0005שלא קדש\u0006 במצרים — \u0005לא קדש\u0006 במדבר\u0005].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ר' יוחנן לריש לקיש, ממה ששנינו בברייתא: \u0003אותו היום שהוקם המשכן קרבו להם בישראל\u0004 כל סוגי הקרבנות, \u0003נדרים ונדבות, חטאות ואשמות, בכורות\u0004 בהמה טהורה \u0003ומעשרות\u0004 (מעשר בהמה). הרי שהיו בכורות בהמה קדושים במדבר! השיב לו: \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 מדובר \u0003באותן\u0004 בכורות \u0003שיצאו ממצרים\u0004 ונתקדשו כבר שם. ומעירים: \u0003ומינה\u0004 \u0005[וממנה,\u0006 מברייתא זו עצמה\u0005]\u0006 יש לדייק כדברי ריש לקיש: \u0003אותו היום הוא דקרוב\u0004 \u0005[שקרבו]\u0006 בכורות, \u0003מיכן ואילך לא קרוב\u0004 \u0005[קרבו]!\u0006","ומעירים: הדיון בברייתא זו \u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 אותו בלשון זו: \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ריש לקיש לר' יוחנן\u0004 ממה ששנינו בה: \u0003אותו היום שהוקם המשכן קרבו להם ישראל נדרים ונדבות חטאות ואשמות בכורות ומעשרות.\u0004 ונדייק מכאן: \u0003אותו היום\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מיכן ואילך\u0004 — \u0003לא.\u0004 הרי שלא קדשו בכורות במדבר! ודוחים: \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003מאותו היום ואילך\u0004 קרבו כל אותם קרבנות.","ושואלים: \u0003ומאי קמשמע לן\u0004 \u0005[ומה הוא משמיע לנו]\u0006 בכך? ומשיבים: \u0003מאותו היום\u0004 ואילך — \u0003אין\u0004 \u0005[כן],\u0006 הקריבו אותם קרבנות, אבל \u0003מעיקרא\u0004 \u0005[מתחילה],\u0006 קודם שהוקם המשכן — \u0003לא. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003חובות,\u0004 כלומר, קרבנות חובה, כגון אלו, \u0003בבמה לא קרוב\u0004 \u0005[קרבו],\u0006 אלא דווקא קרבנות נדבה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת לשיטת ר' יוחנן, ממה ששנינו בברייתא: \u0003נמצאת אתה אומר: בשלשה מקומות קדשו בכורות לישראל: במצרים, ובמדבר, ובכניסתן\u0004 של \u0003ישראל לארץ. במצרים מהו אומר? \"קדש לי כל בכור\"\u0004 (שמות יג, ב), \u0003במדבר הוא אומר: \"כי לי כל בכור בבני ישראל\"\u0004 (במדבר ח, יז), \u0003בכניסתם לארץ הוא אומר: \"והיה כי יביאך\u0004 ה' אל ארץ הכנעני וכו' \u0003והעברת\u0004 כל פטר רחם לה' \"(שמות יג, יא). הרי שבכורות קדשו במדבר!","\u0003אמר רב נחמן בר יצחק:\u0004 כוונת הברייתא היא ש\u0003בשלשה מקומות הוזהרו\u0004 (נצטוו) ישראל \u0003על הבכורות ליקדש, ו\u0004אולם \u0003לא קדשו\u0004 בפועל. ומקשים: \u0003ו\u0004לפי זה, \u0003במצרים נמי לא קדוש\u0004 \u0005[גם כן לא קדשו]?\u0006 \u0003הא קאמרינן דקדוש\u0004 \u0005[הרי אמרנו שקדשו]\u0006 לדעת הכל! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אומר]\u0006 התנא: בשלשה מקומות הוזהרו, \u0003מהן קדשו\u0004 (במצרים ובארץ) \u0003ומהן לא קדשו\u0004 (במדבר).","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: ו\u0004האם \u0003במדבר לא קדשו? והכתיב\u0004 \u0005[והרי נאמר]\u0006 בשעה שנבחרו הלויים תחת בכורות ישראל: \u0003\"פקד כל בכר זכר לבני ישראל\u0004 מבן חדש ומעלה\" (במדבר ג, מ), ואלו בוודאי נולדו במדבר, שהרי מניין זה היה בשנה השנית לצאתם ממצרים! \u0003אלא, אי איתמר הכי איתמר\u0004 \u0005[אם נאמר\u0006 שנחלקו ר' יוחנן וריש לקיש בענין זה, \u0005כך נאמר],\u0006 \u0003ר' יוחנן אמר: קדשו\u0004 בכורות במדבר \u0003ולא פסקו\u0004 מקדושתם, \u0003וריש לקיש אמר: קדשו\u0004 בכורות במדבר עד אותה שעה,"],["\u0003ופסקו\u0004 מאותה שעה שנמנו במדבר.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח,\u0006 מובן הדבר\u0005]\u0006 לשיטתו של \u0003ריש לקיש,\u0004 שלא קדשו יותר עד שנכנסו לארץ — כמו ש\u0003אמר\u0004 את ה\u0003טעם,\u0004 המקור לדבריו, שנאמר: \"והיה כי יביאך אל ארץ הכנעני וכו' והעברת כל פטר רחם\" (שמות יג, יא), \u0003אלא ל\u0004שיטת \u0003ר' יוחנן,\u0004 שלא פסקו ליקדש גם לאחר המנין שבמדבר, \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006","\u0003אמר ר' אלעזר:\u0004 את \u0003ר' יוחנן חזאי בחילמא\u0004 \u0005[ראיתי בחלום],\u0006 וסימן הוא \u0003דמילתא מעליתא אמינא\u0004 \u0005[שדבר טוב אני אומר]\u0006 בטעם דבריו: \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 באותה שעה \"כי לי כל בכור ביום הכותי בארץ מצרים הקדשתי לי כל בכור בישראל מאדם עד בהמה לי יהיו\" (במדבר ג, יג), והתוספת \u0003\"לי יהיו\"\u0004 באה להדגיש: \u0003בהוייתן,\u0004 כפי שהם, כן \u0003יהו\u0004 לי.","ושואלים: \u0003ור' יוחנן,\u0004 את הפסוק הזה \u0003\"והיה כי יביאך... והעברת\" מאי עביד ליה\u0004 \u0005[מה עושה הוא בו]?\u0006 ומשיבים: \u0003ההוא מיבעי ליה\u0004 \u0005[אותו פסוק נצרך לו]\u0006 \u0003לכ\u0004 מו ששנה ה\u0003תנא דבי\u0004 \u0005[מבית מדרשו]\u0006 של \u0003ר' ישמעאל: עשה מצוה זו\u0004 של קידוש בכורות, \u0003שבשבילה,\u0004 כלומר, בגללה, \u0003תיכנס לארץ.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי: אתון הכי מתניתו לה\u0004 \u0005[אתם כך אתם שונים אותה]\u0006 את מחלוקת ר' יוחנן וריש לקיש, \u0003אנן איפכא מתנינן לה\u0004 \u0005[אנו להיפך שונים אנו אותה],\u0006 \u0003ר' יוחנן אמר: לא קדשו בכורות במדבר, וריש לקיש אמר: קדשו בכורות במדבר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003ואפכית נמי תיובתא\u0004 \u0005[והופכים אתם גם כן את הקושיות]\u0006 שהקשו זה על זה, \u0003ואפכיתו לה להא\u0004 \u0005[ו\u0006כן \u0005הופכים אתם אותה לזו]\u0006 שאמר \u0003ר' אלעזר,\u0004 שלא ראה את ר' יוחנן בחלום, אלא את ריש לקיש, ותירץ את דבריו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 לפי מסורת זו שבידי, \u0003לא קדשו\u0004 בכורות במדבר, שאמר ר' יוחנן, כוונתו \u0003לא הוצרכו\u0004 בכורות \u0003ליקדש,\u0004 לפי שכבר היו קדושים.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003היינו דידן\u0004 \u0005[זו היא\u0006 המסורת \u0005שלנו]\u0006 ביחס למחלוקת, שלדעת ר' יוחנן קדשו בכורות במדבר! ומשיבים: על כל פנים \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 רב מרדכי ש\u0003חייב אדם לומר בלשון רבו.\u0004","ובענין הפקעת הקדושה מן הבכורות, על ידי הלויים במדבר, מסופר: \u0003שאל קונטרוקוס השר את רבן יוחנן בן זכאי: בפרטן של לוים,\u0004 כאשר מנו אותם למשפחותם, \u0003אתה מוצא\u0004 שהיו \u0003עשרים ושנים אלף ושלש מאות\u0004 (ראה במדבר ג, כב. במדבר ג, כח. במדבר ג, לד). ואילו \u0003בכללן,\u0004 כאשר נמנו כאחד, \u0003אתה מוצא\u0004 שהיו \u0003עשרים ושנים אלף,\u0004 שנאמר בסוף המנין: \"כל זכר מבן חדש ומעלה שנים ועשרים אלף\" (במדבר ג, לט). \u0003ו\u0004אותם \u0003שלש מאות\u0004 שנמנו בפרט, \u0003להיכן הלכו?\u0004","\u0003אמר לו:\u0004 במנין הכללי נמנו בני לוי שבאו תחת בכורות ישראל באותה שעה. ואילו \u0003אותן שלש מאות\u0004 — \u0003בכורות היו, ואין בכור\u0004 לוי \u0003מפקיע\u0004 קדושת \u0003בכור\u0004 ישראל. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר אביי: דיו ל\u0004לוי \u0003בכור שיפקיע\u0004 את \u0003קדושת\u0004 הבכורה של \u0003עצמו.\u0004","\u0003ועוד שאלו\u0004 קונטרוקוס השר את רבן יוחנן בן זכאי: \u0003בגיבוי כסף\u0004 כאשר גבה משה כסף לצורך המשכן, \u0003אתה מוצא\u0004 שמשקל הכסף מגיע ל\u0003מאתים ואחת ככר\u0004 \u0003ואחת עשרה מנה, דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]\u0006 כי נאספו \u0003\"בקע לגלגלת מחצית השקל בשקל הקדש וגו'\u0004 לשש מאות אלף ושלשת אלפים וחמש מאות וחמשים\" (שמות לח, כו), שהם שלש מאות ואחד אלף ועוד שבע מאות שבעים וחמישה שקלים. וסכום זה מגיע למאתיים ואחת כיכר ואחת עשרה מנה (בכל כיכר אלף וחמש מאות שקלים, ובכל מנה עשרים וחמישה שקלים).","\u0003ו\u0004אילו \u0003בנתינת הכסף\u0004 בפועל לצורך המשכן \u0003אתה מוצא\u0004 רק \u0003מאת ככר, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי מאת ככר הכסף לצקת\u0004 את אדני הקדש ואת אדני הפרוכת\" (שמות לח, כז). וכי \u0003משה רבכם גנב היה, או קוביוסטוס\u0004 (משחק בקוביה) היה, או אינו בקי בחשבונות? נתן מחצה לצורך המשכן, \u0003ונטל\u0004 לעצמו \u0003מחצה, ו\u0004אפילו \u0003מחצה שלם לא החזיר,\u0004 כלומר, נתן לצורך המשכן פחות ממחצית!","אמר לו רבן יוחנן: \u0003משה רבינו גיזבר נאמן היה, ובקי בחשבונות היה,\u0004 אלא \u0003מנה של קודש,\u0004 שעל פיו חושבו מאת הכיכר לאדנים, \u0003כפול היה,\u0004 היה בו מנין כפול של שקלים (חמשים שקלים למנה), ומאת הכיכר שווים למאתיים הכיכר שגבה משה מבני ישראל.","\u0003הוי\u0004 \u0005[התקשה]\u0006 \u0003בה רב אחאי: מאי קא קשיא ליה\u0004 \u0005[מה קשה לו],\u0006 לרבן יוחנן, שהוצרך להידחק? האם מה שנאמר \u0003\"ויהי מאת ככר הכסף לצקת\" וגו'?\u0004 והרי אפשר לומר כי \u0003הנך\u0004 \u0005[\u0006מאה כיכרות \u0005אלה]\u0006 יועדו \u0003לצקת\u0004 מהם את האדנים, \u0003ואינך\u0004 \u0005[ו\u0006מאה הכיכרות \u0005האחרים]\u0006 שלא נזכרו שם, ניתנו \u0003בי גזא\u0004 \u0005[באוצר]!\u0006 ומשיבים: \u0003כתב קרא אחרינא\u0004 \u0005[כתוב פסוק אחר]\u0006 שלא נזכרו בו אלא מאה כיכר: \u0003\"וכסף פקודי העדה מאת ככר\"\u0004 \u0003וגו'\u0004 (שמות לח, כה), ושם לא ניתן להסביר שמדובר רק במחצית הסכום.","ושואלים: \u0003ודקאמר ליה\u0004 \u0005[ומה שאמר לו]\u0006 רבן יוחנן בן זכאי: \u0003מנה של קודש כפול היה, מנא ליה\u0004 \u0005[מנין לו]?\u0006","\u0003אילימא מיניה\u0004 \u0005[אם תאמר ממנו]\u0006 מפסוק זה עצמו, שהקשה ממנו קונטרוקוס השר \"ויהי מאת ככר הכסף לצקת\" וכו' (שמות לח, כד), \u0003שהרי\u0004 בנוסף למאה כיכר, נזכרו \u0003כאן\u0004 שקלי כסף נוספים במשקל \u0003שבעים ואחד מנה,\u0004 שנאמר: \u0003\"ואת האלף ושבע מאות וחמשה ושבעים עשה ווים לעמודים\"\u0004 (שמות לח, כח), שהם עולים לכיכר (ששים מנה) ועוד אחד עשר מנה, \u0003ולא מנאן הכתוב\u0004 במנין של כיכרות, \u0003אלא בפרוטרוט,\u0004 במנין של מטבעות קטנים, שקלים. \u0003ואם איתא\u0004 \u0005[אכן]\u0006 מנה של קודש מנה רגיל היה, אם כן \u0003מאה\u0004 כיכר (לאדנים) \u0003ואחד ככר ואחת עשרה מנה\u0004 (לווים) \u0003מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לכתוב!","\u0003אלא, מ\u0004ש\u0003לא מנאן הכתוב אלא בפרוטרוט, שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003מנה של קודש כפול היה,\u0004 שהיו בו חמשים שקלים. ובאופן זה, אלף שבע מאות שבעים וחמישה שקלים אינם מגיעים אלא לשלושים וחמשה וחצי מנים, שהם פחות מכיכר שלם (שהוא בן ששים מנה).","יש לדחות ראיה זאת: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 מגיעים השקלים לסכום של כיכר, ומכל מקום \u0003כללי קחשיב בככרי\u0004 \u0005[\u0006דווקא כללים, מאות, \u0005הוא מחשב ב\u0006מנין ה\u0005כיכרות],\u0006 אבל \u0003פרטי\u0004 \u0005[פרטים,\u0006 כל שהוא פחות ממאה כיכר\u0005]\u0006 \u0003לא קא חשיב בככרי\u0004 \u0005[אינו מחשב בכיכרות],\u0006 אלא בשקלים!","\u0003אלא מהכא\u0004 \u0005[מכאן]\u0006 אתה למד, שנאמר: \u0003\"ונחושת התנופה שבעים ככר ואלפים וארבע מאות שקל\"\u0004 (שמות לח, כט) \u0003ש\u0004מלבד שבעים הכיכר \u0003הרי כאן תשעים וששה מנה,\u0004 כלומר, כיכר ועוד שלושים וששה מנה, \u0003ולא מנאן הכתוב אלא בפרוטרוט,\u0004 בשקלים, \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003מנה של קודש כפול היה,\u0004 ולכן לא הגיע סכום השקלים לכדי כיכר שלם.","גם ראיה זו יש לדחות: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 מדובר במנה רגיל, ומכל מקום \u0003פרטא רבה קא חשיב בככרי\u0004 \u0005[פרט מרובה,\u0006 כלומר, מנין של עשרות, \u0005הוא מחשב בכיכרים],\u0006 \u0003פרטא זוטא לא קחשיב בככרי\u0004 \u0005[פרט קטן,\u0006 כיכרות בודדים, \u0005אינו מחשב בכיכרות]!\u0006","\u0003אלא אמר רב חסדא: מהכא\u0004 \u0005[מכאן]\u0006 אתה למד שמנה של קודש כפול היה, ממה שאמר יחזקאל הנביא, כאשר הגדיר את המשקלות שבמקדש: \u0003\"והשקל עשרים גרה עשרים שקלים חמשה ועשרים שקלים עשרה וחמשה שקל המנה יהיה לכם\"\u0004 (יחזקאל מה, יב). כלומר, בכל שקל כסף יש עשרים מעות. וכן הצירוף של עשרים שקלים, ועוד עשרים וחמשה, ועוד עשרה, ועוד חמשה, ובסך הכל ששים שקלים — הריהו מנה, כלומר, משקל מאה דינרים."],["\u0003והא\u0004 \u0005[והרי]\u0006 בכל שקל יש ארבעה דינרים, ואם כן ששים שקלים — \u0003מאתן וארבעין הויין\u0004 \u0005[מאתיים וארבעים\u0006 דינרים \u0005הם],\u0006 ולא מנה! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 מספר דברים: האחד, שנוגע לסוגייתנו — \u0003מנה של קודש\u0004 אליו התייחס יחזקאל הנביא, \u0003מנה כפול היה,\u0004 של חמשים שקלים. והיו בו איפוא מאתיים דינרים.","\u0003ו\u0004ממה שאמר הנביא שבמנה יהיו מעתה ששים שקלים, \u0003שמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003מוסיפין על המדות,\u0004 כלומר, מותר להגדיל את שיעור מדות הנפח והמשקל, וכן המטבעות. ואין לחשוש לתקלה שתבוא על ידי כך. \u0003ו\u0004מכל מקום \u0003אין מוסיפין יתר על שתות\u0004 (ששית) מן המידה הקיימת. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי שתות האמורה בענין זה הריהי \u0003שתותא מלבר\u0004 \u0005[שתות מבחוץ],\u0006 כלומר, שישית לאחר ההוספה, שהוא חמישית מן הסכום הראשוני, כפי שנוספו כאן עשרה שקלים על החמישים.","ושבים לענין פדיון פטר חמור. \u0003אמר ר' חנינא, שאלתי את ר' אליעזר בבית מותבא רבא\u0004 \u0005[בבית המדרש הגדול]:\u0006 \u0003מה נשתנו פטרי חמורים מפטרי\u0004 בהמה טמאה אחרת, כגון \u0003סוסים וגמלים,\u0004 שאין פודים אותם? \u0003אמר לי: גזירת הכתוב היא. ועוד, שסייעו ישראל בשעת יציאתם ממצרים, שאין לך כל אחד ואחד מישראל שלא היו עמו תשעים חמורים לובים\u0004 (שהיו חמורים משובחים) \u0003טעונים מכספה וזהבה של מצרים.\u0004","הוסיף ר' חנינא, \u0003ועוד שאלתיו\u0004 את ר' אליעזר: \u0003מאי\u0004 \u0005[מהו\u0006 פירוש\u0005]\u0006 \u0003לשון \"רפידים\"\u0004 (\"ויבוא עמלק וילחם עם ישראל ברפידים\", שמות יז, ח)? \u0003ואמר לי: רפידים שמה,\u0004 זהו שם המקום. ומעירים: דבר זה הוא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים],\u0006 \u0003ר' אליעזר אומר: רפידים שמה, ר' יהושע אומר:\u0004 קראו כך למקום משום \u0003שריפו עצמן\u0004 שם \u0003מדברי תורה, וכן הוא אומר: \"לא הפנו אבות אל בנים מרפיון ידים\"\u0004 (ירמיהו מז, ג), הרי שיש בכתוב ביטוי דומה ל\"רפידים\" שמשמעו רפיון.","\u0003ועוד שאלתיו: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003לשון \"שטים\"\u0004 (\"וישב ישראל בשטים ויחל העם לזנות אל בנות מואב\", , א)? \u0003ואמר לי: שטים שמה.\u0004 ומעירים: אף דבר זה הוא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים],\u0006 \u0003ר' אליעזר אומר: שטים שמה, ר' יהושע אומר:\u0004 קראו כך למקום משום \u0003שנתעסקו בדברי שטות.\u0004","ועוד נחלקו בפירוש מה שנאמר שם: \u0003\"ותקראן לעם לזבחי אלהיהן\"\u0004 (במדבר כה ב), מהו \"ותקראנה\", מה עניינה של קריאה זו, שהביאה אותם לעבודה זרה. \u0003ר' אליעזר אומר: ערומות פגעו בהן,\u0004 וכך קראו להן. \u0003ר' יהושע אומר: שנעשו כולן בעלי קריין,\u0004 ומכאן לשון \"ותקראנה\", שעשו אותם בעלי קרי.","\u0003פרה שילדה\u0004 בלידתה הראשונה \u0003מין חמור,\u0004 כלומר, יצור הדומה במראהו לחמור, \u0003וחמור שילדה כמין סוס\u0004 — הרי זו \u0003פטורה מן הבכורה, שנאמר: \"פטר חמור\"\u0004 (שמות יג, יג) \u0003\"פטר חמור\"\u0004 (שמות לד, כ), \u0003שני פעמים\u0004 — \u0003עד שיהא היולד חמור, והנולד חמור.\u0004","\u0003ומה הם באכילה,\u0004 האם ולדות שאינם נראים כבני מין אמם מותרים באכילה? \u0003בהמה טהורה שילדה כמין בהמה טמאה\u0004 — הוולד \u0003מותר באכילה, וטמאה שילדה כמין בהמה טהורה\u0004 — \u0003אסור באכילה, שהיוצא מן הטמא\u0004 — \u0003טמא, והיוצא מן הטהור\u0004 — \u0003טהור.\u0004","ובענין ששנינו במשנתנו מביאים, \u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 בפרק השני של מסכת זאת: \u0003רחל\u0004 (כבשה) \u0003שילדה מין עז, ועז שילדה מין רחל\u0004 — הרי הולד \u0003פטור מן הבכורה, ואם יש בו מקצת סימנין\u0004 של אמו — הרי הוא \u0003חייב.\u0004","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר רב יהודה,\u0004 ש\u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בענין בכור בהמה טהורה: \"אך בכור שור או בכור כשב או בכור עז לא תפדה קדש הם\" וכו' (במדבר יח, יז). ולא הוצרך להזכיר שמדובר בבכור, שהרי על כך מדובר שם, אלא נאמר \u0003\"אך בכור שור\"\u0004 ללמד שאין חל עליו דין בכורה עד \u0003שיהא הוא\u0004 (האם) \u0003שור ובכורו שור,\u0004 ולא כמין בעל חיים אחר. וכן \u0003\"בכור כשב\"\u0004 — \u0003שיהא הוא כשב ובכורו כשב, \"בכור עז\"\u0004 — \u0003שיהא הוא עז ובכורו עז.\u0004","\u0003יכול אפילו יש בו מקצת סימנין\u0004 של אימו גם כן יהא פטור, שהרי אינו ממש כאמו? תלמוד לומר: \"אך\", והיא לשון מיעוט, ובכך \u0003חלק\u0004 הכתוב, והוציא מקרים שיש בו מקצת סימנים של אמו, שבכור הוא, בהם לא יחול דין זה. ושואלים: ומדוע נזקק רב יהודה לדרשה זו? \u0003והא\u0004 \u0005[והרי]\u0006 ה","\u0003תנא\u0004 של משנתנו, את הלימוד \u0003\"פטר\u0004 חמור\" \u0003\"פטר\u0004 חמור\" \u0003קנסיב לה\u0004 \u0005[הוא מביא],\u0006 \u0003לפרה\u0004 שילדה כמין חמור, ללמד שהיא פטורה מן הבכורה!","ומשיבים: \u0003הוא\u0004 ש\u0003אמר כ\u0004דברי \u0003ר' יוסי הגלילי,\u0004 ולא מעצמו. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי הגלילי אומר: \"אך בכור שור\"\u0004 — \u0003עד שיהא הוא שור ובכורו שור, \"בכור כשב\"\u0004 — \u0003עד שיהא הוא כשב ובכורו כשב. \"או בכור עז\"\u0004 — \u0003עד שיהא הוא עז ובכורו עז.\u0004","\u0003יכול אפילו יש בו מקצת סימנין? תלמוד לומר: \"אך\"\u0004 — \u0003חלק.\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חלוקים],\u0006 שהם למדים מכתובים שונים? ומשיבים: \u0003תנא דידן סבר\u0004 \u0005[התנא שלנו סבור]:\u0006 \u0003גלי רחמנא\u0004 \u0005[גילתה התורה]\u0006 \u0003בקדושת דמים,\u0004 כלומר, בפטר חמור (שאין גופו קדוש, אלא רק צריך לתת את פדיונו לכהן), שאינו בכור עד שיהא כאמו, \u0003והוא הדין\u0004 \u0003בקדושת הגוף,\u0004 כלומר, בבכור בהמה טהורה (שגופו קדוש להקרבה על המזבח).","\u0003ור' יוסי סבר\u0004 \u0005[סבור]:\u0006 \u0003גלי רחמנא\u0004 \u0005[גילתה התורה]\u0006 \u0003בקדושת הגוף והוא הדין בקדושת דמים. ו\u0004טעמו, שהוא \u0003גמר\u0004 \u0005[לומד]\u0006 באופן כללי \u0003קדושת דמים מקדושת הגוף.\u0004","ושואלים: \u0003ותנא דידן\u0004 \u0005[והתנא שלנו],\u0006 \u0003האי\u0004 \u0005[זה,\u0006 הייתור\u0005]\u0006 של \u0003\"בכור\" \"בכור\",\u0004 בשור בכבש ובעז, ממנו לומד ר' יוסי הגלילי דין זה, \u0003מאי עביד ליה\u0004 \u0005[מה הוא עושה בו]?\u0006 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריך הוא אותו]\u0006 \u0003ל\u0004למד על הקטרת אימוריהם (חלקיהם הפנימיים) על גבי המזבח, הנזכרת בפסוק זה (\"ואת חלבם תקטיר\"). \u0003כ\u0004מו שדרש \u0003ר' יוסי בר' חנינא,\u0004 ש","אמר ר' יוסי בר' חנינא: למה נאמרו אימורין \u0003בבכור שור, אימורין בבכור כשב, אימורין בבכור עז\u0004 בפסוק זה?","\u0003צריכא\u0004 \u0005[צריך\u0006 הדבר להיאמר\u0005],\u0006 \u0003דאי כתב רחמנא\u0004 \u0005[שאילו היתה כותבת התורה]\u0006 רק \u0003בבכור שור\u0004 — הייתי אומר: דווקא את חלבו צריך להקטיר, \u0003שכן\u0004 קרבן שור \u0003נתרבה בנסכים,\u0004 שכמות הנסכים שצריך להביא עמו, יתירה על זו של כבשים ועזים, ואם כן יש בו צד חמור.","וכן אילו היה נאמר רק ב\u0003כשב\u0004 — הייתי אומר דווקא את חלבו מקטירים, \u0003שכן נתרבה ב\u0004הקטרת ה\u0003אליה\u0004 (הזנב) על המזבח, וכיוצא בזה","\u0003בעז\u0004 — הייתי אומר שדווקא את חלבו מקטירים, \u0003שכן נתרבה אצל עבודה זרה ביחיד,\u0004 שהשוגג באיסור עבודה זרה צריך להביא דווקא עז לחטאת, שלא כשאר שגגות, שרשאי להביא גם כשבה.","ולגופם של דברים אלה, שואלים: \u0003חדא מחדא לא אתיא\u0004 \u0005[אחת מאחת אינה באה,\u0006 נלמדת\u0005],\u0006 ואולם \u0003תיתי חדא מתרתי\u0004 \u0005[תבוא,\u0006 תילמד \u0005אחת משתים]!\u0006","ומשיבים: \u0003בהי לא ליכתוב\u0004 \u0005[באיזה\u0006 מהם \u0005לא יכתוב]\u0006 וילמד מן השניים האחרים? אם תאמר: \u0003לא ליכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 הקטרת אימורים \u0003ב\u0004בכור \u0003שור, ותיתי מהנך\u0004 \u0005[ותבוא,\u0006 תילמד \u0005מאלה,\u0006 מכבש ועז\u0005]\u0006 — יש לדחות: \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן נתרבו\u0004 לענין הקרבה \u0003אצל פסחים,\u0004 שכבש ועז (זכר) כשרים לקרבן הפסח, ושור אינו כשר לפסח!","ואם תאמר: \u0003לא לכתוב\u0004 \u0005[תכתוב\u0006 התורה\u0005]\u0006 \u0003בכשב, ותיתי מהנך\u0004 \u0005[ותבוא,\u0006 תילמד \u0005מאלה],\u0006 שור ועז — יש לדחות: \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן נתרבו אצל\u0004 שגגת \u0003עבודה זרה בציבור,\u0004 שציבור ששגג באיסור עבודה זרה, מביא פר לחטאת, ויחיד ששגג בעבודה זרה מביא דווקא עז, ולא כבשה!","אלא תאמר: \u0003לא ניכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 \u0003בעז, ותיתי מהנך\u0004 \u0005[ותבוא,\u0006 ותילמד, \u0005מאלה],\u0006 משור וכבש — יש לדחות: \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן יש בהן צד רבוי אצל מזבח,\u0004 שנסכי הפר מרובים יותר משל עז, ואליית הכבש מוקטרת על המזבח, מה שאין כן בעז! \u0003הילכך צריכי\u0004 \u0005[על כן צריכים הם]\u0006 שלושתם.","ושואלים: \u0003ור' יוסי הגלילי,\u0004 כיצד הוא דורש פסוק זה (\"אך בכור שור\" וכו') לענין שיהא הבכור ממין אמו? והרי פסוק זה נצרך לענין הקטרת האימורים! ומשיבים: \u0003אם כן,\u0004 רק כדי ללמד דבר זה, \u0003ליכתוב קרא\u0004 \u0005[שיכתוב המקרא]\u0006 \u0003\"אך בכור שור כשב ועז\", \"בכור\u0004 כשב\" \"בכור עז\" \u0003למה לי? אלא לאו שמע מינה\u0004 \u0005[האם לא נשמע מכאן]:\u0006 \u0003עד שיהא הוא שור ובכורו שור.\u0004","ושואלים: \u0003ור' יוסי הגלילי, האי\u0004 \u0005[זה]\u0006 \u0003\"פטר חמור\" \"פטר חמור\",\u0004 ממנו למד התנא במשנתנו, שאינו בכור עד שיהא ממין אמו, \u0003מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006","ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[צריך\u0006 הוא \u0005אותו לכמו ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי הגלילי אומר: מתוך שנאמר \"אך פדה תפדה את בכור האדם ואת בכור הבהמה הטמאה תפדה\"\u0004 (במדבר יח, טו), \u0003שומע אני אפילו פטרי סוסים וגמלים\u0004 יש לפדות? שהרי גם הם בכלל בכור הבהמה הטמאה! \u0003תלמוד לומר: \"פטר חמור\u0004 תפדה בשה\" (שמות יג, יג) — \u0003פטר חמור אמרתי לך, ולא פטרי סוסים וגמלים.\u0004","\u0003ועדיין אני אומר: פטרי חמור\u0004 פודים \u0003בשה, פטרי סוסים וגמלים\u0004 פודים \u0003בכל דבר!\u0004"],["\u0003תלמוד לומר: \"פטר חמור\" \"פטר חמור\" שני פעמים\u0004 (שמות יג, יג. שמות לד, ל), ומן הכתוב הנוסף אתה למד כי \u0003פטרי חמורים אמרתי לך ולא פטרי סוסים וגמלים,\u0004 שאין בהם כלל דין בכורה.","\u0003פריך\u0004 \u0005[הקשה\u0006 על כך\u0005]\u0006 \u0003רב אחאי:\u0004 וכיצד אתה פוטרם לגמרי מן הבכורה בגלל הכתוב הנוסף? והרי \u0003אי כתב רחמנא חד\u0004 \u0005[אם היתה כותבת התורה\u0006 \"פטר חמור\" \u0005אחד]\u0006 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 חמור הריהו \u0003דבר שהיה בכלל\u0004 בהמה טמאה, \u0003ויצא מן הכלל,\u0004 כלומר, נזכר לעצמו, כדי \u0003ללמד\u0004 שצריך לפדותו בשה (שמות לד, ל). ולפי המדות שהתורה נדרשת בהן, \u0003לא ללמד על עצמו\u0004 בלבד \u0003יצא, אלא ללמד על הכלל כולו יצא, ולעולם\u0004 כל בהמה טמאה נפדית דווקא \u0003בשה.\u0004","לכך \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"פטר חמור\u0004 תפדה בשה\" \u0003אחרינא\u0004 \u0005[אחר,\u0006 פעם נוספת\u0005],\u0006 לומר: \u0003פטרי חמורים\u0004 פודים בשה, \u0003ולא פטרי סוסים וגמלים.\u0004 \u0003ואימא\u0004 \u0005[ואמור,\u0006 איפוא, כפי שהצענו מתחילה\u0005]:\u0006 \u0003מעטינהו\u0004 \u0005[מיעט אותם\u0006 הכתוב\u0005],\u0006 את פטרי סוסים וגמלים, \u0003מ\u0004פדיון ב\u0003שה, ולעולם\u0004 פודים אותם, \u0003בכל דבר!\u0004","ומשיבים: \u0003אם כן,\u0004 שלא הוצרך הכתוב אלא למעטם מפדיון בשה — \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]:\u0006 \u0003\"פטר חמור תפדה בשה\", ו\u0004בפעם השניה רק: \u0003\"חמור תפדה בשה\",\u0004 ודי בכך. \u0003\"פטר חמור תפדה בשה\"\u0004 ושוב \u0003\"פטר חמור תפדה בשה\" למה לי?\u0004 הרי כפילות זו של \"פטר חמור\" באה להדגיש: \u0003פטרי חמורים אמרתי לך ולא פטרי סוסים וגמלים.\u0004","ושואלים: \u0003ותנא דידן\u0004 \u0005[והתנא שלנו],\u0006 שלמד את דין משנתנו מכפילות זו, \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003סוסים וגמלים\u0004 מן הבכורה \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006","\u0003אמר רב פפא:\u0004 נאמר \"כל מקנך תזכר פטר שור ושה. ופטר חמור תפדה בשה\" (שמות לד, יט—כ), \u0003\"כל מקנך תזכר\"\u0004 — הרי זה \u0003כלל, שור ושה וחמור\u0004 — \u0003פרט,\u0004 ולפי המדות שהתורה נדרשת בהן, \u0003כלל ופרט\u0004 — \u0003אין בכלל אלא מה שבפרט,\u0004 ועל כן \u0003שור ושה וחמור\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 חייב בבכורה, \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא.\u0004","ושואלים: \u0003ור' יוסי הגלילי,\u0004 מה הוא אומר? ומשיבים: לשיטתו, החמור אינו אחד הפרטים של \"כל מקנך תזכר\", שהרי \u0003\"פטר\"\u0004 שהוזכר קודם חמור — הפסיק הענין. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 מה הם עונים לטענה זו? ומשיבים: על ידי \u0003וי\"ו\u0004 שב\"ופטר\", \u0003הדר ערביה קרא\u0004 \u0005[חזר ועירב אותו המקרא],\u0006 את החמור.","ושואלים: \u0003ור' יוסי הגלילי\u0004 מה הוא אומר? ומשיבים: לדעתו, אם אכן חמור הוא פרט של הכלל הראשון — \u0003לא לכתוב\u0004 \u0005[שלא תכתוב\u0006 התורה\u0005]\u0006 \u0003לא וי\"ו ולא \"פטר\".\u0004","ומן הצד האחר, ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 מה הם עונים לטענה זו? ומשיבים: \u0003איידי דהא\u0004 \u0005[מתוך שזה],\u0006 פטר חמור, הריהו \u0003קדושת דמים,\u0004 שאינו קדוש אלא לדמיו, שצריך לפדותו בשה, \u0003והא\u0004 \u0005[וזה],\u0006 בכור שור ושה, הריהו \u0003קדושת הגוף,\u0004 שמקריבים אותו על המזבח — \u0003פסיק להו\u0004 \u0005[פסק אותם]\u0006 זה מזה ב\"פטר\", \u0003והדר עריב להו\u0004 \u0005[ואחר כך חזר ועירב אותם]\u0006 בוי\"ו, ללמד שגם החמור פרט של הכלל שנאמר בתחילה \"כל מקנך תזכר\".","כפי שנזכר לעיל, שנינו בפרק השני: רחל שילדה כמין עז וכו' פטורה מן הבכורה, ואם יש בו מקצת סימנים של אמו — חייבת. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003פרה שילדה מין חמור,\u0004 ששנינו במשנתנו שהוא פטור מן הבכורה, \u0003ויש בו מקצת סימנין\u0004 של אמו, \u0003מהו\u0004 דינו?","מה ששנינו לגבי \u0003עז שילדה מן רחל, ורחל שילדה מין עז, דכי\u0004 \u0005[שכאשר]\u0006 \u0003יש\u0004 בולד \u0003מקצת סימנין\u0004 של האם \u0003חייבת בבכורה,\u0004 הרי זה משום שממילא יש צדדי דמיון בין רחל ועז, \u0003דהא\u0004 \u0005[שזו]\u0006 \u0003טהורה והא\u0004 \u0005[וזו]\u0006 \u0003טהורה,\u0004 וכן \u0003הא\u0004 \u0005[זו]\u0006 יש לבכורות שבה \u0003קדושת הגוף\u0004 ליקרב על המזבח, \u0003והא\u0004 \u0005[וזו]\u0006 יש לבכורות שבה \u0003קדושת הגוף.\u0004","אבל \u0003הכא\u0004 \u0005[כאן],\u0006 בפרה שילדה כמין חמור, \u0003דהא\u0004 \u0005[שזה]\u0006 הולד, כמין בהמה \u0003טמאה, והא\u0004 \u0005[וזו]\u0006 האם \u0003טהורה.\u0004 וכן \u0003הא\u0004 \u0005[זו],\u0006 הפרה, יש לבכורות שבמינה \u0003קדושת הגוף, והא\u0004 \u0005[וזו]\u0006 הולד, הריהו ממין שיש לבכורותיו רק \u0003קדושת דמים\u0004 — \u0003לא,\u0004 וגם אם יש לולד מקצת סימני אמו אינו קדוש בבכורה. \u0003או דלמא\u0004 \u0005[שמא]:\u0006 \u0003כיון דאידי ואידי\u0004 \u0005[שזה וזה],\u0006 פרה וחמור, \u0003בני מיקדש\u0004 \u0005[ראויים להתקדש]\u0006 \u0003בבכורה\u0004 — הרי הוא \u0003קדוש?\u0004","\u0003ואם תמצי\u0004 \u0005[תוכל]\u0006 \u0003לומר: כיון דאידי ואידי מיקדש\u0004 \u0005[שזה וזה ראויים להתקדש]\u0006 \u0003בבכורה\u0004 כשיש בו מסימני אמו הריהו \u0003קדוש,\u0004 יש לשאול: \u0003חמור שילדה מין סוס\u0004 ויש בו מקצת סימני חמור, \u0003מהו? הכא\u0004 \u0005[כאן]\u0006 \u0003ודאי\u0004 אין מקום לומר שהולד קדוש בבכורה, שהרי הסוס \u0003לא בת מיקדש\u0004 \u0005[אינה ראויה להתקדש]\u0006 \u0003בבכורה הוא. או דלמא\u0004 \u0005[שמא]\u0006 נאמר: \u0003כיון\u0004 ש\u0003מין טמאה הוא,\u0004 האם והולד — \u0003קדוש,\u0004 הואיל ויש בו מקצת סימני אמו, שהיא חמורה?","ועוד, \u0003אם תמצא\u0004 \u0005[תוכל]\u0006 \u0003לומר:\u0004 חמור שילדה כמין סוס, ויש בו מקצת סימני חמור, \u0003כיון\u0004 ש\u0003מין טמאה הוא\u0004 — \u0003קדוש, פרה שילדה מין סוס, מהו\u0004 הדין? \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ודאי\u0004 אין מקום לחייבו בבכורה, שהרי \u0003הא\u0004 \u0005[זו]\u0006 \u0003טהורה והא\u0004 \u0005[וזו]\u0006 \u0003טמאה, הא בת מיקדש\u0004 \u0005[ראויה להתקדש]\u0006 \u0003בבכורה, והא לא בת מיקדש\u0004 \u0005[וזו לא ראויה להתקדש]\u0006 בבכורה. או דלמא \u0005[שמא]\u0006 נאמר: על כל פנים, מקצת \u0003סימנין\u0004 של אימו \u0003מילתא היא\u0004 \u0005[דבר\u0006 חשוב \u0005הוא],\u0006 והולד קדוש בבכורה?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא: \u0003בהמה טהורה שילדה מין בהמה טמאה\u0004 — \u0003פטורה מן הבכורה,\u0004 ו\u0003אם יש בו מקצת סימנין\u0004 — \u0003חייבת בבכורה. מאי לאו\u0004 \u0005[האם לא]\u0006 כולל הדבר \u0003אפילו פרה שילדה מין סוס?\u0004 ודוחים: \u0003לא,\u0004 דווקא \u0003פרה שילדה מין חמור,\u0004 שבשניהם יש קדושת בכורה.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה ממה ששנינו בברייתא: \u0003פרה שילדה מין חמור, וחמור שילדה מין סוס\u0004 — \u0003פטורה מן הבכורה,\u0004 ו\u0003אם יש בו מקצת סימנין\u0004 — \u0003חייבת בבכורה, מאי לאו אתרוייהו\u0004 \u0005[האם לא על שניהם]\u0006 מדובר, שאם יש בו מקצת סימני אמו הריהו בכור, גם על פרה שילדה מין חמור, וגם על חמור שילדה כמין סוס? ואם כן, יש מכאן פתרון לשתיים מן השאלות שנשאלו! ודוחים: \u0003לא,\u0004 מדובר רק על \u0003פרה שילדה מין חמור.\u0004","ושואלים: \u0003אבל חמור שילדה מין סוס, למאי קתני לה\u0004 \u0005[ל\u0006שם \u0005מה שונה אותה]\u0006 בברייתא? \u0003לפטורא\u0004 \u0005[לפטור]\u0006 מן הבכורה, כשאין בו מקצת סימני אמו? והרי \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003ומה פרה שילדה מין חמור, דאידי ואידי בני מיקדש בבכורה נינהו\u0004 \u0005[שזה וזה ראויים להתקדש בבכורה הם],\u0006 \u0003אמרת\u0004 \u0005[אומר אתה]:\u0006 \u0003אם יש בו מקצת סימנין\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 קדוש בבכורה, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא, חמור שילדה מין סוס\u0004 שאין בו קדושת בכורה, \u0003מיבעיא\u0004 \u0005[נצרכה לומר]\u0006 שהוא פטור כשאין בו מקצת סימנים?","ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך הדבר],\u0006 גם לאחר ששנינו שפרה שילדה כמין חמור פטורה. שכן \u0003סלקא דעתך\u0004 \u0005[יעלה על דעתך\u0006 לומר\u0005]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 שנפטרה מן הבכורה, לפי שפרה וחמור שונים לגמרי זה מזה, שפרה \u0003יש לה קרנים, והא\u0004 \u0005[וזו,\u0006 החמור\u0005]\u0006 \u0003אין לה קרנים, הא\u0004 \u0005[זו,\u0006 פרה\u0005]\u0006 \u0003פרסותיה סדוקות,\u0004 יש שסע באמצען, \u0003והא\u0004 \u0005[וזו,\u0006 חמור\u0005]\u0006 \u0003פרסותיה קלוטות\u0004 (שלמות).","\u0003אבל הכא\u0004 \u0005[כאן],\u0006 חמור שילדה כמין סוס, שיש דמיון רב בין מין האם ומין הוולד, \u0003דאידי ואידי\u0004 \u0005[שזו וזו]\u0006 \u0003אין לה קרנים, אידי ואידי\u0004 \u0005[זו וזו]\u0006 \u0003פרסותיה קלוטות, אימא\u0004 \u0005[אמור]\u0006 שולד זה \u0003חמור אדום בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא,\u0004 והוא נחשב כבכור לאמו, על כן \u0003קמשמע לן\u0004 \u0005[משמיע לנו]\u0006 התנא שהוא מין אחר, ופטור מן הבכורה.","שנינו במשנה בענין בהמה שילדה שלא כמינה: \u0003ומה הן באכילה?\u0004 בהמה טהורה שילדה כמין בהמה טמאה — מותר באכילה, וטמאה שילדה כמין בהמה טהורה — אסור באכילה. והוסיף התנא: שהיוצא מן הטמא טמא והיוצא מן הטהור טהור. ושואלים: \u0003למה לי למיתני\u0004 \u0005[לשנות]\u0006 \u0003שהיוצא\u0004 מן הטמא טמא והיוצא מן הטהור טהור?","ומשיבים: \u0003סימנא בעלמא\u0004 \u0005[סימן בלבד]\u0006 \u0003הוא,\u0004 ש\u0003לא תיחלף\u0004 \u0005[תתחלף]\u0006 \u0003לך\u0004 גרסת המשנה בטעות, \u0003דלא תימא: זיל בתריה דידיה\u0004 \u0005[שלא תאמר: לך אחריו,\u0006 אחרי הנולד \u0005בעצמו],\u0006 \u0003והאי טהור מעליא\u0004 \u0005[וזה,\u0006 למרות שנולד לטמאה, \u0005טהור מעולה]\u0006 \u0003הוא, והאי טמא מעליא\u0004 \u0005[וזה,\u0006 למרות שנולד לטהורה, \u0005טמא מעולה]\u0006 \u0003הוא. אלא זיל בתר אימיה\u0004 \u0005[לך אחר אימו].\u0006","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שלענין היתר ואיסור אכילה הולכים אחר האם? ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים],\u0006 נאמר: \u0003\"אך את זה לא תאכלו ממעלי הגרה וממפריסי הפרסה\"\u0004 (ויקרא יא, ד), ומכאן משמע: \u0003יש לך שהוא מעלה גרה ומפריס פרסה ואי\u0004 (ואין) \u0003אתה אוכלו, ואיזה זה? טהור שנולד מן הטמא.\u0004 ויש לשאול: \u0003או אינו אלא\u0004 בא למעט \u0003טמא,\u0004 שאינו מעלה גרה ומפריס פרסה, \u0003הנולד מן הטהור, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"ממעלי הגרה וממפריסי הפרסה\"\u0004 — ד"],["\u0003הכי קאמר\u0004 \u0005[כך הוא אומר],\u0006 לכך כוונתו: \u0003דבר הבא ממעלי הגרה וממפריסי הפרסה לא תיכול\u0004 \u0005[תאכל]!\u0006 \u0003תלמוד לומר\u0004 בהמשך הפסוק: \u0003\"גמל טמא הוא\"\u0004 (\"את הגמל כי מעלה גרה ופרסה איננו מפריס טמא הוא לכם\", ויקרא יא, ד), ויש כאן הדגשה: \u0003הוא טמא, ואין טמא הנולד מן הטהור טמא, אלא טהור.\u0004","\u0003ר' שמעון אומר:\u0004 נאמר \u0003\"גמל\" \"גמל\" שני פעמים,\u0004 לענין איסור אכילה, פעם בספר ויקרא (יא, ד) ופעם בספר דברים (יד, ז), הרי זה בא לומר: \u0003אחד גמל הנולד מן הגמלה, ואחד גמל הנולד מן הפרה\u0004 טמא. שלדעתו, אם טהורה ילדה כמין טמאה — אסור הולד באכילה, שלא כשיטת משנתנו. ומבררים את דעות החכמים שבברייתא.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 החולקים על ר' שמעון, \u0003האי\u0004 \u0005[אותו]\u0006 כפל לשון של \u0003\"גמל\" \"גמל\", מאי עבדי ליה\u0004 \u0005[מה\u0006 הם \u0005עושים בו]?\u0006 ומשיבים: \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 בא \u0003לאסור\u0004 את הגמל \u0003עצמו, וחד\u0004 \u0005[ואחד מהם]\u0006 בא \u0003לאסור\u0004 את \u0003חלבו,\u0004 שחלב הנקבה גם הוא אסור. ושואלים: \u0003ור' שמעון, לאסור חלבו\u0004 של גמל, ושאר בהמות טמאות, \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו\u0006 הדבר\u0005]\u0006 \u0003מ\u0004מה שנאמר \u0003\"את הגמל\",\u0004 ולשון \"את\" הריהי באה לרבות את חלבו. \u0003ו\u0004מן הצד האחר, \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003\"אתים\"\u0004 המילה \"את\" בתור ריבוי \u0003לא דרשי\u0004 \u0005[אינם דורשים].\u0006","\u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003שמעון העמסוני היה דורש כל \"את\" ו\"את\" שבתורה\u0004 לרבות, \u0003כיון שהגיע ל\"את ה' אלהיך תירא\"\u0004 (דברים ו, יג) ולא מצא מה לרבות מ\"את\" האמורה בו, שאין דבר שמוראו שווה למורא המקום — \u0003פירש,\u0004 כלומר, הפסיק לדרוש לשון \"את\". \u0003אמרו לו תלמידיו: רבי,\u0004 מאחר ולא ניתן לדרוש בדרך זו, \u0003כל \"אתין\" שדרשת\u0004 עד עכשיו \u0003מה תהא עליהם?\u0004 וכי לשוא דרשת? \u0003אמר להם: כשם שקבלתי שכר על הדרישה\u0004 שדרשתי כך את הכתובים, \u0003כך אני מקבל שכר על הפרישה.\u0004","\u0003עד שבא ר' עקיבא ולימד: \"את ה' אלהיך תירא\"\u0004 — הרי זה \u0003לרבות תלמידי חכמים,\u0004 שצריך לירא מהם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: אלא מעתה,\u0004 שאנו אומרים כי \u0003טעמא דרבנן\u0004 \u0005[טעמם של חכמים],\u0006 שהם למדים לאסור אף חלב גמל מ\"גמל\" \"גמל\", ור' שמעון \u0003מ\"את הגמל\",\u0004 יש להסיק: \u0003הא לאו הכי הוה אמינא\u0004 \u0005[הרי לולא זה הייתי אומר]\u0006 \u0003חלב\u0004 \u0003בהמה טמאה שרי\u0004 \u0005[מותר]?\u0006","\u0003מאי שנא מהא דתניא\u0004 \u0005[במה שונה\u0006 דינו של חלב \u0005מזו ששנויה\u0006 בברייתא\u0005]:\u0006 נאמר \"אלה \u0003הטמאים\u0004 לכם בכל השרץ\" (ויקרא יא, לא) ומה' הידיעה למדו חכמים \u0003לאסור\u0004 גם \u0003צירן\u0004 (שומנם, הנוזל היוצא מגופם), \u0003ו\u0004גם \u0003רוטבן\u0004 (הרוטב היוצא מהם תוך כדי בישול), \u0003ו\u0004גם \u0003קיפה שלהן\u0004 (התבשיל הנקפה ומצטבר בשולי הקדירה)?","השיב לו רב אשי: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 חלב הגמל ללימוד בפני עצמו, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003הואיל\u0004 וחלב של \u0003בהמה טהורה נמי\u0004 \u0005[גם כן]\u0006 \u0003חידוש הוא\u0004 שמותר, שהרי נוצר מן הדם, וכפי ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 אשה שילדה ומניקה — אינה רואה דם נידה, משום ש\u0003דם\u0004 הנקבה המניקה \u0003נעכר\u0004 (נעשה עכור) \u0003ונעשה\u0004 ממנו \u0003חלב.\u0004 \u0003וכיון\u0004 ש\u0003חידוש הוא\u0004 שחידשה תורה, שחלב מותר, אם כן \u0003בבהמה טמאה נמי לישתרי\u0004 \u0005[גם כן יהיה מותר],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב שהוא אסור.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 שמניקה אינה רואה דם משום ש\u0003דם נעכר ונעשה חלב,\u0004 ואם כן יש חידוש במה שהותר החלב בטהורה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי טעם הדבר שמניקה אינה רואה דם, הוא משום שהיולדת \u0003איבריה מתפרקין הימנה ואין נפשה חוזרת עליה,\u0004 כלומר, אינה חוזרת לבריאותה \u0003עד עשרים וארבעה חדש,\u0004 ולשיטתו החלב אינו נוצר מן הדם — \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 מדוע הוצרך הכתוב לאסור במיוחד חלב בהמה טמאה?","ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך\u0006 הדבר\u0005],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וליכא מידי דאתי מחי ושרייה רחמנא\u0004 \u0005[ואין דבר שבא מן החי והתירה אותו התורה],\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 ה\u0003חלב כי\u0004 \u0005[כמו]\u0006 \u0003אבר מן החי הוא, ו\u0004בכל זאת \u0003שרי\u0004 \u0005[מותר].\u0006 \u0003ו\u0004הואיל וחידוש הוא שחידשה תורה, \u0003הילכך\u0004 \u0005[על כן]\u0006 יש לומר כי \u0003אפילו בבהמה טמאה לישתרי\u0004 \u0005[יהיה מותר],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב שאסור.","ושואלים: \u0003ו\u0004באמת, \u0003חלב\u0004 של \u0003בהמה טהורה מנלן דשרי\u0004 \u0005[מנין לנו ש\u0006הוא \u0005מותר\u0006 באכילה\u0005]?\u0006 \u0003אילימא מדאסר רחמנא\u0004 \u0005[אם תאמר ממה שאסרה התורה]\u0006 \u0003בשר בחלב,\u0004 ונסיק מכאן: \u0003הא לחודיה שרי\u0004 \u0005[אבל לעצמו מותר\u0006 החלב\u0005]\u0006 — יש לדחות הוכחה זו, שכן יכול אתה להסיק מסקנה אחרת, \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: \u0003חלב לחודיה\u0004 \u0005[כשלעצמו]\u0006 — \u0003אסור באכילה ומותר בהנאה,\u0004 שלא בדרך אכילה, \u0003בשר בחלב\u0004 — \u0003בהנאה נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור! ו\u0004גם","\u0003לר' שמעון דשרי\u0004 \u0005[שמתיר]\u0006 בשר בחלב \u0003בהנאה, משכחת לה\u0004 \u0005[מוצא אתה]\u0006 טעם מיוחד להוסיף איסור לגבי בשר בחלב, גם אם חלב נאסר כשלעצמו — \u0003למילקי על בישוליה\u0004 \u0005[ללקות על בישולו]\u0006 של בשר בחלב!","\u0003אלא\u0004 מכאן יש להוכיח שחלב מותר באכילה — \u0003מדגלי רחמנא\u0004 \u0005[מ\u0006כיון \u0005שגילתה התורה]\u0006 \u0003בפסולי המוקדשין,\u0004 כלומר, קדשים שנפל בהם מום ונפדו, שנאמר בהם: \"תזבח ואכלת בשר\" (דברים יב, טו), ודורשים שם: \u0003\"תזבח\"\u0004 — כוונתו — \u0003ולא גיזה,\u0004 שאינך רשאי ליהנות מצמרם, \u0003\"בשר\"\u0004 — \u0003ולא חלב.\u0004 ותלמד מכאן: \u0003הא\u0004 \u0005[אבל]\u0006 חלב של \u0003חולין\u0004 — \u0003שרי\u0004 \u0005[מותר].\u0006","ודוחים: והרי יכול אתה לדייק באופן אחר, \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: חלב של \u0003חולין\u0004 — \u0003אסור באכילה ושרי\u0004 \u0005[ומותר]\u0006 \u0003בהנאה,\u0004 חלב של \u0003קדשים\u0004 — \u0003בהנאה נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור!\u0004","\u0003אלא\u0004 יש להביא ראיה שחלב מותר \u0003מדכתיב\u0004 \u0005[מ\u0006מה \u0005שנאמר]:\u0006 \u0003\"ודי חלב עזים ללחמך ללחם ביתך וחיים לנערותיך\"\u0004 (משלי כז, כז), הרי שחלב העזים משמש למזונו של אדם (\"ללחמך\").","ודוחים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 הכוונה היא \u0003לסחורה,\u0004 שמוכר חלב על מנת שיהא לו לחם לאכול, אבל לא שהחלב עצמו משמש לאכילה! \u0003אלא\u0004 יש להביא ראיה \u0003מדכתיב\u0004 \u0005[מ\u0006מה \u0005שנאמר]\u0006 כאשר שלח ישי את דוד בנו למלחמה עם הפלשתים: \u0003\"ואת עשרת חריצי החלב\u0004 תביא לשר האלף\" (שמואל א יז, יח), משמע שהיו אוכלים דברים של חלב.","ודוחים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 כוונתו \u0003לסחורה,\u0004 שימכרם שר האלף! על כך משיבים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003דרכה של מלחמה\u0004 שהולכים בה \u0003לסחורה?\u0004 אלא ודאי שלח להם את חריצי הגבינה כדי שיאכלום. ואם כן, יש מכאן ראיה.","\u0003ואיבעית אימא מהכא\u0004 \u0005[ואם תרצה אמור מכאן]\u0006 ראיה, שנאמר בשבחה של ארץ ישראל: \u0003\"ארץ זבת חלב ודבש\"\u0004 (שמות ג, יז), \u0003ואי לא דשרי\u0004 \u0005[ואם לא ש\u0006חלב \u0005מותר],\u0006 \u0003משתבח לן קרא במידי דלא חזי\u0004 \u0005[\u0006וכי \u0005משתבח לנו הכתוב בדבר שאיננו ראוי]\u0006 לאכילה? \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003מהכא\u0004 \u0005[מכאן]\u0006 יש ראיה, שאמר הנביא: \u0003\"לכו שברו\u0004 (קנו אוכל) \u0003ואכלו, ולכו שברו בלא כסף ובלא מחיר יין וחלב\"\u0004 (ישעיהו נה, א). ושבים למחלוקת ר' שמעון וחכמים, ששניהם דורשים את הכפילות \"גמל\" \"גמל\" שבספר ויקרא ובספר דברים, כל אחד לשיטתו.","ושואלים: \u0003אלא מעתה, \"שפן\" \"שפן\", \"ארנבת\" \"ארנבת\", \"חזיר\" \"חזיר\",\u0004 שהוזכרו גם הם פעמיים לאיסור, גם הם \u0003להני הוא דאתו\u0004 \u0005[ל\u0006לימודים \u0005אלו הוא שבאו]?\u0006","והרי לא הובאו \u0003אלא לכדתניא\u0004 \u0005[לכמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003למה\u0004 חזרו ו\u0003נשנו\u0004 כל הבהמות הטמאות והעופות הטמאים בספר דברים (דברים יד, ז—כ)? \u0003בבהמה\u0004 הטמאה — \u0003מפני השסועה\u0004 (דברים יד, ז) שלא נזכרה בספר ויקרא, \u0003ובעופות מפני הראה\u0004 (דברים יד, יג).","ואם כן \u0003\"גמל\" \"גמל\" נמי להכי הוא דאתא\u0004 \u0005[גם כן לצורך זה הוא שבא],\u0006 משום השסועה שנזכרה בספר דברים, ולא כדי לחדש דין לעצמו! ומשיבים: אף על פי כן, \u0003כל היכא דאיכא למידרש דרשינן\u0004 \u0005[כל מקום שאפשר לדרוש דורשים],\u0006 ורק במקום שאי אפשר לדרוש אומרים שלא הובא אלא אגב דבר אחר שנתחדש בפרשה.","ועוד בבירור דעת ר' שמעון בעניינים אלה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003רחל שילדה מין עז ועז שילדה מין רחל\u0004 — \u0003פטורה מן הבכורה, ואם יש בו מקצת סימנים\u0004 של אמו — \u0003חייבת. ר' שמעון אומר:\u0004 אינה פטורה מן הבכורה \u0003עד שיהא ראשו ורובו\u0004 של הולד \u0003דומה לאמו.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 שאלה ללומדים\u0005]:\u0006 \u0003ל\u0004ענין היתר \u0003אכילה\u0004 של טמאה הנולדת מן הטהורה, \u0003מי בעי\u0004 \u0005[האם צריך]\u0006 \u0003ר' שמעון ראשו ורובו\u0004 דומה לאמו הטהורה, \u0003או לא,\u0004 ודי שיש מקצת סימנים כדי להתירה באכילה?","ומפרטים: \u0003לענין בכורה כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"אך בכור שור\"\u0004 (במדבר יח, יז), ולמדים מכאן: \u0003עד שיהא הוא שור ובכורו שור,\u0004 ואם אין ראשו ורובו שור — אין בו דין בכורה, לדעת ר' שמעון. אבל לענין \u0003אכילה,\u0004 שדרש ר' שמעון מן הכתובים, שגמל שנולד מן הטהורה גם הוא אסור, יש לומר כי \u0003גמל\u0004 גמור \u0003הוא דאמר רחמנא דאסיר\u0004 \u0005[שאומרת התורה שאסור],\u0006 \u0003הא\u0004 \u0005[אבל]\u0006 אם"],["\u0003אישתני\u0004 \u0005[השתנה]\u0006 \u0003מגמל,\u0004 ויש בו מקצת סימני אמו — \u0003שפיר דמי\u0004 \u0005[ראוי\u0006 הוא \u0005נחשב],\u0006 ומותר לאכילה. \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה],\u0006 וגם לענין היתר אכילה — מצריך ר' שמעון שיהא ראשו ורובו דומה לאמו הטהורה?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא: \u0003בהמה טהורה שילדה מין בהמה טמאה\u0004 — \u0003אסור באכילה\u0004 (וכשיטת ר' שמעון), ואם דומה ראשו ורובו לאמו — \u0003חייב בבכורה. שמע מינה\u0004 \u0005[למד מכאן]\u0006 לכאורה כי \u0003ל\u0004היתר \u0003אכילה נמי בעי\u0004 \u0005[גם כן צריך]\u0006 \u0003ר' שמעון\u0004 שיהא ראשו ורובו דומה לאמו!","ודוחים: \u0003לא, לבכורה דוקא\u0004 צריך ראשו ורובו. ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 הדבר מלשון הברייתא, \u0003דקא שבקה לאכילה וקם ליה\u0004 \u0005[שהניח\u0006 התנא \u0005את האכילה,\u0006 ששנה בתחילה, \u0005ועמד לו על דין]\u0006 ה\u0003בכור, שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003לבכורה הוא דבעי\u0004 \u0005[שצריך]\u0006 \u0003ר' שמעון ראשו ורובו, אבל לאכילה\u0004 — \u0003לא,\u0004 ודי במקצת סימנים.","ודוחים: \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך: ל\u0004היתר \u0003אכילה נמי בעי\u0004 \u0005[גם כן צריך]\u0006 ראשו ורובו, \u0003ו\u0004דווקא לגבי \u0003בכורה איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"אך בכור שור\"\u0004 (במדבר יח, יז), ללמדנו שאין דין בכורה \u0003עד שיהא הוא שור ובכורו שור, ו\u0004לפי זה \u0003לא תיסגי ליה\u0004 \u0005[לא יהיה די לו]\u0006 \u0003בראשו ורובו,\u0004 ואינו בכור \u0003עד דאיכא כוליה\u0004 \u0005[שיש\u0006 ולד ש\u0005כולו]\u0006 שור, על כן \u0003קמשמע לן\u0004 \u0005[משמיע לנו]\u0006 שדי שיהא ראשו ורובו שור.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא: נאמר \u0003\"אך את זה לא תאכלו ממעלי הגרה וממפריסי הפרסה\u0004 את הגמל\" וכו' (ויקרא יא, ד), ומכאן משמע כי גמל (או אחד משאר בעלי החיים הטמאים) הנולד מבהמה טהורה (\"ממעלי הגרה, וממפריסי הפרסה\") אסור באכילה. ומן ההדגשה \"זה\" יש ללמוד: \u0003זה,\u0004 בעל חיים שכל סימניו כשל טמא, \u0003אי\u0004 (אין) \u0003אתה אוכל\u0004 כשנולד לבהמה טהורה, \u0003אבל אתה אוכל\u0004 טמא \u0003הבא בסימן אחד\u0004 של אמו, כלומר, שהוא דומה לה במקצת,","\u0003ואי זה\u0004 הוא \u0003זה הבא בסימן אחד\u0004 של אמו, שמותר באכילה? \u0003זה טמא הנולד מן הטהור\u0004 \u0003ועבורו מן הטהור,\u0004 שגם אביו בהמה טהורה.","\u0003יכול\u0004 יהא מותר באכילה אפילו היה \u0003עבורו מן הטמא,\u0004 כגון שאביו גמל? \u0003תלמוד לומר:\u0004 \"זאת הבהמה אשר תאכלו \u0003שה כשבים ושה עזים\"\u0004 (דברים יד, ד), ולשון רבים (\"כשבים\") באה ללמד שאינו מותר באכילה (אפילו יש בו סימן אחד של אמו) \u0003עד שיהא אביו כבש ואמו כבשה,\u0004 אלו \u0003דברי ר' יהושע.\u0004","\u0003ר' אליעזר אומר:\u0004 ולד שאביו ואמו טהורים הריהו מותר, ו\u0003לא בא הכתוב\u0004 הזה, המתיר ולד הדומה לאמו במקצת, \u0003להתיר את המותר,\u0004 כשגם אמו וגם אביו טהורים, \u0003אלא להוסיף על המותר, ואיזה זה? טמא הנולד מן הטהור ועבורו מן הטמא.\u0004 ויש לשאול: \u0003או אינו\u0004 בא להתיר \u0003אלא\u0004 דווקא כשגם \u0003עבורו מן הטהור! תלמוד לומר: \"שור שה כשבים ושה עזים\"\u0004 (דברים יד, ד)ד והחזרה על המלה \"שה\" מלמדת כי הוא מותר באכילה \u0003מכל מקום,\u0004 גם אם רק אמו מן הכבשים.","על כל פנים, התנא ששנה מחלוקת זו \u0003קרי ליה\u0004 \u0005[קורא לו]\u0006 למין טמא הנולד מן הטהורה \u0003\"טמא\",\u0004 והוא \u0003כ\u0004שיטת \u0003ר' שמעון,\u0004 שאוסר גמל הנולד מן הפרה, \u0003וקאמר\u0004 \u0005[והוא אומר]:\u0006 \u0003אבל אתה אוכל הבא בסימן אחד,\u0004 כלומר, שאם יש בו מקצת סימני אמו הריהו מותר באכילה. ומכאן שר' שמעון אינו מצריך שיהא ראשו ורובו כאמו, כדי להתירו באכילה!","ודוחים: מכאן אין ראיה, שיש לומר כי \u0003האי תנא סבר ליה כוותיה בחדא\u0004 \u0005[תנא זה סבור כמותו באחת],\u0006 שטהורה שילדה מין טמאה — טמא, \u0003ופליג עליה בחדא\u0004 \u0005[וחולק עליו באחת],\u0006 שהוא מתירו באכילה אם יש בו מקצת סימני אמו, ולדעת ר' שמעון אינו מותר באכילה עד שיהא ראשו ורובו דומה לאמו.","ומעירים: \u0003ואיכא דמקשי ומותיב\u0004 \u0005[ויש\u0006 מי ש\u0005מקשה\u0006 על הברייתא שהבאנו, \u0005ומשיב],\u0006 ובדרך זו רוצה להביא תשובה לשאלתנו. וכך הוא מקשה: מה ששנינו בברייתא זו ביחס לטהורה שילדה מין טמאה: \u0003עבורו מן הטמא\u0004 — \u0003מי מעברא\u0004 \u0005[האם\u0006 בהמה טהורה \u0005מתעברת]\u0006 מן הטמא?","\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יהושע בן לוי: לעולם אין\u0004 בהמה \u0003מתעברת לא טמאה מן הטהור,\u0004 כגון גמלה (נאקה) מן השור, \u0003ולא טהורה מן הטמא,\u0004 כגון פרה מן הסוס, \u0003ולא\u0004 בהמה \u0003גסה מן הדקה,\u0004 כגון פרה מתיש, \u0003ולא דקה מן הגסה\u0004 כגון רחל משור, \u0003ולא בהמה מן חיה,\u0004 כגון עז מן הצבי, \u0003ולא חיה מן בהמה,\u0004 כגון צביה מן התיש,","\u0003חוץ מר' אליעזר ומחלוקתו,\u0004 כלומר, ומן החולקים עליו, \u0003שהיו אומרים חיה מתעברת מבהמה,\u0004 שנחלקו האם חייבים על שחיטת ולד הצביה שנתעברה מן התיש משום \"אותו ואת בנו\"!","\u0003ו\u0004בתשובה לכך \u0003אמר ר' ירמיה:\u0004 מה שנאמר \"עבורו מן הטמא\" כוונתו \u0003דאיעבר\u0004 \u0005[שנתעברה]\u0006 הטהורה \u0003מקלוט\u0004 (שפרסותיו קלוטות, ללא שסע) שהוא \u0003בן פרה,\u0004 שפרה יכולה להתעבר ממנו, משום שהוא בן פרה. \u0003ו\u0004נמצא שהתנא של הברייתא \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' שמעון קאמר\u0004 \u0005[הוא אומר],\u0006 שטהורה שילדה מין טמאה נקרא \"טמא\". \u0003וקאמר\u0004 \u0005[והוא אומר]:\u0006 \u0003אבל אתה אוכל הבא בסימן אחד,\u0004 כלומר, שכשיש בו מקצת סימני אמו הריהו מותר באכילה. ומכאן שכך סובר ר' שמעון!","ודוחים: מכאן אין להוכיח, ויש לומר כי \u0003האי תנא סבר לה כוותיה בחדא\u0004 \u0005[תנא זה סבור כמותו באחת],\u0006 שטמא בן טהורה קרוי טמא, \u0003ופליג עליה בחדא\u0004 \u0005[וחולק עליו באחת],\u0006 שלדעת תנא זה, אם יש בו מקצת סימני אמו הריהו מותר באכילה, ולדעת ר' שמעון הריהו אסור באכילה עד שיהא ראשו ורובו דומה לאמו.","ולגופה של מחלוקת ר' אליעזר ור' יהושע שבברייתא, שואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 מתוך מחלוקת זו ש\u0003ר' אליעזר סבר\u0004 \u0005[סבור]\u0006 כי כאשר \u0003זה וזה,\u0004 איסור והיתר, \u0003גורם\u0004 להיווצרות של דבר — הריהו \u0003מותר,\u0004 ולכן הוא מתיר באכילה ולד של טהורה שנתעברה מן הטמא, \u0003ור' יהושע\u0004 האוסר \u0003סבר\u0004 \u0005[סבור]\u0006 כי \u0003זה וזה גורם\u0004 — \u0003אסור?\u0004","\u0003והא איפכא שמעינן להו\u0004 \u0005[והרי ההיפך שמענו אותם],\u0006 ששנינו: \u0003ולד\u0004 שנולד ל\u0003טריפה,\u0004 שאסורה בהקרבה על המזבח, \u0003ר' אליעזר אומר: לא יקרב לגבי מזבח,\u0004 למרות שאביו כשר, \u0003ור' יהושע אומר: יקרב לגבי מזבח,\u0004 למרות שהוא ולד טריפה, מכיון שיש בו גורם היתר!","ואומרים: \u0003בעלמא\u0004 \u0005[בכלל]\u0006 \u0003סבר\u0004 \u0005[סבור]\u0006 \u0003ר' אליעזר\u0004 כי \u0003זה וזה גורם\u0004 — \u0003אסור, ו\u0004אולם \u0003שאני הכא\u0004 \u0005[שונה כאן],\u0006 לגבי היתר אכילה של טהורה שנתעברה מן הטמא, ש\u0003אם כן\u0004 שהוולד אסור — \u0003נכתוב קרא\u0004 \u0005[שיכתוב המקרא]:\u0006 \"זאת הבהמה אשר תאכלו \u0003שה כשבים ועזים\", \"שה\u0004 כשבים \u0003ושה\u0004 עזים\" \u0003למה לי?\u0004 מדוע לחזור על המלה \"שה\"? \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003שה\u0004— \u0003מכל מקום,\u0004 וגם אם רק אמו מן הכשבים הריהו מותר באכילה.","\u0003ו\u0004כן מן הצד האחר, \u0003ר' יהושע אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך: בעלמא\u0004 \u0005[בכלל]\u0006 \u0003זה וזה גורם\u0004 — \u0003מותר, והכא\u0004 \u0005[וכאן]\u0006 שונה הדבר, שאם ולד של טהורה שנתעברה מטמא מותר, \u0003אם כן לכתוב קרא\u0004 \u0005[שיכתוב המקרא]:\u0006 \"זאת הבהמה אשר תאכלו \u0003שור כשב ועז\",\u0004 \"שור \u0003כשבים ועזים\"\u0004 בלשון רבים \u0003למה לי? שמע מינה\u0004 \u0005[למד מכאן]\u0006 שאינו מותר באכילה \u0003עד שיהא אביו כבש ואמו כבשה.\u0004","ושבים לעיקר הסוגיה, האם טהורה שילדה מין טמא ויש בו מקצת סימני אמו, מותר באכילה לדעת ר' שמעון, או שמא צריך שיהא ראשו ורובו דומה לאמו, כבדין בכורה. ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא, \u0003ר' שמעון אומר:\u0004 מה שנזכר בתורה \u0003\"גמל\" \"גמל\" שני פעמים\u0004 לאיסור, בספר ויקרא (יא, ד) ובספר דברים (יד, ד), בא לאסור \u0003אחד גמל הנולד מן הגמל, ואחד גמל הנולד מן הפרה, ואם ראשו ורובו דומה לאמו\u0004 הפרה — \u0003מותר באכילה.\u0004","\u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003לאכילה נמי בעי\u0004 \u0005[גם כן צריך]\u0006 \u0003ר' שמעון ראשו ורובו,\u0004 ואין די במקצת סימנים. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","שנינו במשנה: \u0003שהיוצא מן הטמא\u0004 טמא, והיוצא מן הטהור טהור. \u0003בעו מינה\u0004 \u0005[שאלו אותו]\u0006 \u0003מרב ששת: מי רגלים של חמור, מהו?\u0004 האם הם אסורים, כמו חלב החמורה?","ושואלים: \u0003ותיבעי להו\u0004 \u0005[ושתישאל להם]\u0006 שאלה זו גם לגבי מי רגלים של \u0003סוסים וגמלים!\u0004 ומשיבים: על של \u0003סוסים וגמלים לא מיבעיא להו\u0004 \u0005[נצרכה להם]\u0006 לשאול, \u0003דלא עכירי\u0004 \u0005[שאינם עכורים],\u0006 \u0003ולא דמו\u0004 \u0005[ואינם דומים]\u0006 \u0003לחלב, מיא עול מיא נפוק\u0004 \u0005[מים נכנסו\u0006 לגופם, \u0005מים יצאו].\u0006 \u0003כי קמיבעיא להו\u0004 \u0005[כאשר נשאלה להם]\u0006 השאלה, הרי זה בשל \u0003חמור, דעכירי ודמו\u0004 \u0005[שהם עכורים ודומים]\u0006 \u0003לחלב, מאי\u0004 \u0005[מהו\u0006 דינם\u0005]?\u0006 \u0003מגופיה קא מימצצי ואסירי\u0004 \u0005[מגופו הם מתמצים ואסורים],\u0006 \u0003או דלמא\u0004 \u0005[שמא]:\u0006 \u0003מיא עול מיא נפוק\u0004 \u0005[מים נכנסו מים יצאו],\u0006 \u0003והאי דעכירי הבלא דבישרא\u0004 \u0005[וזה ש\u0006הם \u0005עכורים\u0006 — \u0005מחום הבשר]\u0006 \u0003הוא?\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ששת, תניתוה\u0004 \u0005[שניתם אותה]\u0006 במשנתנו: \u0003שהיוצא מן הטמא\u0004 — \u0003טמא, והיוצא מן הטהור\u0004 — \u0003טהור.\u0004 ויש לדייק: \"היוצא \u0003מטמא\" לא קאמר\u0004 \u0005[אינו אומר],\u0006 כלומר, כל שיוצא מגופו של טמא, \u0003אלא: \"מן\u0004"],["\u0003הטמא\",\u0004 וכוונת התנא לרבות כל שהוא ממין הטמא, \u0003והני נמי מינא דטמא\u0004 \u0005[ואלה גם כן,\u0006 מי רגלים של חמור, \u0005מין של\u0006 ה\u0005טמא]\u0006 \u0003הוא,\u0004 שהרי הם נראים כחלב החמור, ואסורים.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בלשון אחרת את הדיון בענין מי רגלים של חמור: לגבי מי רגלים של \u0003סוסים וגמלים לא קא מיבעיא להו\u0004 \u0005[לא נשאלה להם]\u0006 השאלה, לתלמידי רב ששת, משום \u0003דלא שתו אינשי\u0004 \u0005[שאין אנשים שותים\u0006 אותם\u0005].\u0006 \u0003כי קמיבעיא להו\u0004 \u0005[כאשר נשאלה להם]\u0006 הרי זה בשל \u0003חמור, דשתו אינשי ומעלו לירקונא\u0004 \u0005[ששותים\u0006 אותם \u0005אנשים והם\u0006 \u0005טובים ל\u0006מחלת ה\u0005ירקון],\u0006 \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ששת, תניתוה\u0004 \u0005[שניתם אותה]\u0006 במשנתנו: \u0003היוצא מן הטמא\u0004 — \u0003טמא, והיוצא מן הטהור\u0004 — \u0003טהור, והני נמי\u0004 \u0005[ואלה גם כן]\u0006 \u0003מ\u0004חמור שהוא \u0003טמא קאתי\u0004 \u0005[הם באים],\u0006 ולכן הם אסורים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עליו ממה ששנינו במשנה: \u0003מפני מה אמרו דבש דבורים מותר? מפני ש\u0004הן רק \u0003מכניסות אותו,\u0004 את צוף הפרחים, \u0003לגופן,\u0004 \u0003ו\u0004אולם \u0003אין\u0004 הן \u0003ממצות\u0004 (מפיקות) \u0003אותו מגופן.\u0004 ואף מי רגלים, שאינם מתמצים מגופו של החמור, אלא מים שנכנסו הם מים שיצאו, מפני מה ייאסרו?","ומשיבים: \u0003הוא,\u0004 רב ששת, ש\u0003אמר כ\u0004דעת \u0003ר' יעקב,\u0004 ש\u0003אומר: דובשא רחמנא שרייה\u0004 \u0005[הדבש, התורה התירה אותו]\u0006 באופן מיוחד, אף שבעיקרו של דבר, כל היוצא מן הטמא — טמא.","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יעקב אומר:\u0004 נאמר לגבי שרץ העוף הטהור \u0003\"אך את זה תאכלו מכל שרץ העוף\"\u0004 (ויקרא יא, כא), והלשון \"זה\" באה להדגיש: \u0003זה אתה אוכל, ואי\u0004 (ואין) \u0003אתה אוכל שרץ עוף טמא.\u0004","ותוהים: איסורו של \u0003שרץ עוף טמא בהדיא כתיב\u0004 \u0005[במפורש כתוב]:\u0006 \"וכל שרץ העוף ההולך על ארבע שקץ הוא לכם\" (ויקרא יא כ), ומדוע צריך למיעוט זה! \u0003אלא\u0004 כך יש לדייק: \u0003שרץ עוף טמא אי אתה אוכל, אבל אתה אוכל מה שעוף טמא משריץ,\u0004 כלומר, מוציא מתוכו, \u0003ואיזה זה? זה דבש דבורים.\u0004","\u0003יכול אף דבש\u0004 של שרצי עוף אחרים, כגון \u0003הגזין והצירעין,\u0004 יהיה מותר? \u0003אמרת\u0004 (אומר אתה): \u0003לא.\u0004 ושואלים: \u0003ומה ראית לרבות\u0004 דבש \u0003דבורים,\u0004 ולהתירו באכילה, \u0003ולהוציא\u0004 דבש \u0003הגזין והצירעין\u0004 לאיסור? ומשיבים: \u0003מרבה אני דבש דבורים\u0004 להיתר, מפני \u0003שאין לו שם לווי,\u0004 שסתם דבש הוא דבש דבורים. \u0003ומוציא אני דבש הגזין והצירעין שיש לו שם לווי.\u0004","ומעירים: \u0003כמאן אזלא הא דתניא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת\u0006 הלכה \u0005זו ששנויה\u0006 בברייתא]: \u0003דבש הגזין והצירעין טהור\u0004 (אינו ראוי לקבל טומאה) \u0003ומותר באכילה\u0004 — ש\u0003לא כ\u0004שיטת \u0003ר' יעקב.\u0004","ומדייקים בלשונה של הלכה זו: מה ששנינו שדבש גזין וצירעין \u0003טהור\u0004 — \u0003אלמא בעי\u0004 \u0005[מכאן שהוא צריך]\u0006 \u0003מחשבה\u0004 מפורשת לאוכלו, ורק אז יהא ראוי לקבל טומאה כדין אוכל. ומכאן שדבש דבורים, שהוזכר אף הוא באותה משנה, ולא נאמר בו שהוא טהור — אינו צריך מחשבה מפורשת לאוכלו, כדי לקבל טומאה, משום שבסתמו הוא עומד לאכילה. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003דבש\u0004 (דבורים) כשהוא עדיין \u0003בכוורתו,\u0004 קודם שרדו אותו — \u0003מטמא טומאת אוכלין\u0004 אף \u0003שלא במחשבה.\u0004","ועוד בענין דברים היוצאים מן החי. \u0003חלי דיחמורתא\u0004 \u0005[גושים של יחמורה,\u0006 שהיא פולטת מרחמה\u0005],\u0006 \u0003סבור רבנן למימר\u0004 \u0005[חשבו חכמים לומר]:\u0006 \u0003ביעי נינהו ואסירן\u0004 \u0005[ביצים הן,\u0006 חלק מגופה, ואסורות], כדין איבר מן החי. \u0003אמר רב ספרא: זרעא דאילא\u0004 \u0005[זרע של אייל]\u0006 \u0003הוא, דאזיל בתר אילתא\u0004 \u0005[שהולך\u0006 האייל \u0005אחרי האיילה]\u0006 כדי להזדווג עמה, \u0003ואיידי דרחמה צר לא מזדקקא\u0004 \u0005[ומתוך שרחמה צר אינה מזדקקת לו],\u0006 \u0003ואזיל בתר יחמורתא\u0004 \u0005[והולך אחר היחמורה],\u0006 ונזקק לה, ומעין גושים של שכבת זרעו הם, שנתקשתה — \u0003ונתרי\u0004 \u0005[ו\u0006הם ה\u0005נושרים]\u0006 מגופה.","\u0003אמר רב הונא: עור הבא כנגד פניו של חמור\u0004 כשהוא נולד, כלומר, כעין עור העוטף אותו — \u0003מותר, מאי טעמא? פירשא בעלמא\u0004 \u0005[פרש בלבד]\u0006 \u0003הוא,\u0004 ואינו חלק מגוף האם או הולד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא: תניא דמסיע\u0004 \u0005[שנויה\u0006 ברייתא \u0005שמסייעת]\u0006 \u0003לך: עור הבא כנגד פניו של\u0004 (ולד) \u0003אדם, בין חי בין מת\u0004 — \u0003טהור\u0004 מלטמא טומאת מת. \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה: \u0003בין הוא חי ואמו חיה, בין הוא מת ואמו מתה,\u0004 שאינו נחשב חלק מגוף העובר, ולא חלק מגוף האם, אלא כפרש בלבד, ולכן, גם כששניהם מתים אינו מטמא?","השיב לו רב הונא: \u0003לא,\u0004 אין מברייתא זו ראיה, שכן יש לפרש: \u0003בין הוא חי ואמו מתה, בין הוא מת ואמו חיה,\u0004 כלומר, רק אם אחד מהם חי — עור זה טהור, אבל אם שניהם מתים — אסור. אמר לו רב חסדא: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 כך: \u0003בין הוא חי ואמו חיה, בין הוא מת ואמו מתה!\u0004 אמר לו: \u0003אי תניא, תניא\u0004 \u0005[אם שנויה, שנויה].\u0006","\u0003דג טמא שבלע דג טהור,\u0004 ונמצא בתוכו — \u0003מותר\u0004 הטהור באכילה. וטהור שבלע דג טמא — הדג הטמא \u0003אסור באכילה, לפי שאינו גידולו,\u0004 לא גדל ממנו.","ומדייקים בלשון המשנה \"דג טמא שבלע דג טהור\": \u0003טעמא דחזיניה דבלע\u0004 \u0005[הטעם,\u0006 דווקא משום \u0005שראינו אותו,\u0006 את הטמא, \u0005שהוא בולע]\u0006 את הדג הטהור, מותר הטהור באכילה. \u0003הא לא חזיניה דבלע\u0004 \u0005[אבל\u0006 אם \u0005לא ראינו אותו ש\u0006הוא \u0005בולע]\u0006 — \u0003אמרי: אשרוצי אשריץ\u0004 \u0005[אומרים\u0006 אנו: שמא הדג הטמא \u0005השריץ\u0006 אותו\u0005]\u0006 במעיו, והוא אסור.","\u0003מנלן\u0004 \u0005[מנין לנו]\u0006 חשש זה? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא]: \u0003דג טמא משריץ\u0004 את ולדותיו, \u0003דג טהור מטיל ביצים\u0004 ומהם יוצאים הולדות. ומקשים: \u0003אי הכי, כי חזינא דבלע אמרינן\u0004 \u0005[אם כך,\u0006 גם \u0005כאשר רואים אנו אותו שהוא בולע\u0006 דג טהור, \u0005צריכים אנו לומר]:\u0006 \u0003האי איעכלא, והאי אשרוצי אשריץ\u0004 \u0005[זה\u0006 שבלע \u0005התעכל, ו\u0006את \u0005זה\u0006 שמצאנו במעיו \u0005השריץ,\u0006 וייאסר\u0005]!\u0006","\u0003אמר רב ששת:\u0004 מדובר \u0003כגון שמצאו\u0004 את הדג הטהור \u0003דרך הריעי,\u0004 כלומר, במערכת העיכול, ולא במקום שבו משריץ הדג הטמא את ולדותיו. \u0003רב פפא אמר\u0004 בדומה לכך: \u0003כגון שמצאו\u0004 את הטהור \u0003דרך בית הבליעה. רב נחמן אמר: כגון שמצאו שלם\u0004 שצורתו שלמה וגמורה, שלא כעובר.","\u0003רב אשי אמר:\u0004 אין לדייק מלשון המשנה שמדובר דווקא כשראינוהו שבלע דג טהור. אלא מסתמכים על כך ש\u0003רוב\u0004 ה\u0003דגים במינן\u0004 (בני מינם) הם \u0003משריצין, ו\u0004לפיכך, כשמוצאים דג טהור במעי דג טמא — \u0003כמי שבלע\u0004 אותו \u0003לפנינו דמי\u0004 \u0005[נחשב]\u0006 הדבר.","ומביאים את הברייתא שחלק ממנה נזכר קודם לכן. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003דג טמא משריץ, דג טהור מטיל ביצים. כל המוליד\u0004 ולדות — \u0003מניק\u0004 אותם, \u0003וכל המטיל ביצים\u0004 — \u0003מלקט\u0004 אוכל, ומאכיל בו את ולדותיו, \u0003חוץ מעטלף, שאף על פי שמטיל ביצים\u0004 — \u0003מניק.\u0004"],["\u0003הדולפנין פרין ורבין כבני אדם.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה הם]\u0006 \u0003דולפנין? אמר רב יהודה:\u0004 היצורים הקרויים \u0003בני ימא\u0004 \u0005[הים].\u0006","וממשיכה הברייתא: \u0003כל שביציו\u0004 (אשכיו של הזכר) ניכרים \u0003מבחוץ\u0004 — \u0003מוליד,\u0004 כלומר, הנקבה יולדת ולד. \u0003וכל ש\u0004ביציו \u0003בפנים\u0004 — \u0003מטיל\u0004 (מטילה) הנקבה \u0003ביצים.\u0004","ותוהים: \u0003איני\u0004 \u0005[כן הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: אווז\u0004 הבית \u0003ואווז בר\u0004 — \u0003כלאים זה בזה,\u0004 ואסור להרביעם. \u0003והוינן\u0004 \u0005[והיינו עוסקים,\u0006 מתקשים\u0005]\u0006 \u0003בה: מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 ובתשובה לכך \u0003אמר אביי: זה,\u0004 אווז הבר, \u0003ביציו\u0004 של הזכר \u0003מבחוץ, וזה,\u0004 אווז הבית, \u0003ביציו מבפנים. ו\u0004הרי \u0003תרוייהו\u0004 \u0005[שניהם]\u0006 \u0003מטילי ביצים!\u0004","\u0003אלא\u0004 כך צריך לומר: \u0003כל שזכרותו\u0004 איבר ההולדה, נראה \u0003מבחוץ\u0004 — \u0003מוליד,\u0004 זכרותו \u0003מבפנים\u0004 — \u0003מטיל ביצים.\u0004 ואווז הבר, למרות שביציו מבחוץ — זכרותו מבפנים.","וממשיכה הברייתא בעניינים אלה: \u0003כל\u0004 בעל חיים \u0003שתשמישו\u0004 (הזדווגותו) \u0003ב\u0004שעות ה\u0003יום\u0004 — \u0003יולד ביום, בלילה\u0004 — \u0003יולד בלילה. כל שתשמישו בין ביום בין בלילה\u0004 — \u0003יולד בין ביום בין בלילה.\u0004","ומפרטים: \u0003תשמישו ביום יולד ביום\u0004 — \u0003תרנגול, בלילה יולד בלילה\u0004 — \u0003עטלף, תשמישו בין ביום בין בלילה יולד בין ביום בין בלילה\u0004 — \u0003אדם וכל דדמי ליה\u0004 \u0005[וכל הדומה לו\u0006 בענין זה\u0005].\u0006","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 להלכה? ומשיבים: \u0003ל\u0004כמו שאמר \u0003רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב כהנא,\u0004 ש\u0003אמר רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב כהנא: בדק בקינה\u0004 (קן) \u0003של תרנגולין מערב יום טוב ולא מצא בה ביצה, ולמחר\u0004 קודם עליית השחר \u0003השכים ומצא בה ביצה\u0004 — \u0003מותרת\u0004 הביצה \u0003באכילה ביום טוב,\u0004 ואינה אסורה כדין ביצה שנולדה ביום טוב, לפי שכאמור, אין התרנגולת יולדת בלילה. ואף שבדק ולא מצא בה ביצה בערב יום טוב — \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003לא בדק יפה.\u0004","ומקשים: \u0003והלא\u0004 מן הסתם \u0003בדק יפה!\u0004 ומשיבים: גם אם בדק יפה, \u0003אימר\u0004 \u0005[אמור]:\u0006 \u0003יצתה\u0004 (יצאה) \u0003רובה\u0004 של הביצה בערב יום טוב, \u0003וחזרה\u0004 למעי התרנגולת קודם שבדק, \u0003הוה\u0004 \u0005[היה]\u0006 המעשה. \u0003ו\u0004כמו שאמר \u0003ר' יוחנן,\u0004 ש\u0003אמר ר' יוחנן: ביצה שיצתה רובה מערב יום טוב וחוזרת\u0004 לגוף התרנגולת — \u0003מותרת לאוכלה ביום טוב,\u0004 שכיון שיצאה ברובה הרי היא כילודה כבר.","עוד שנינו בברייתא: \u0003כל\u0004 בעל חיים \u0003ש\u0004דרך \u0003תשמישו ו\u0004זמן \u0003עיבורו\u0004 (הריונו) \u0003שוה\u0004 לשל חבירו, אם נזדווגו — הריהם יולדים, ומגדלים (יונקים) \u0003זה מזה.\u0004 ובענין זה של דרך תשמיש, אמרו: \u0003הכל,\u0004 כל בעלי החיים, \u0003משמשין פנים כנגד עורף,\u0004 כלומר, הזכר בא על הנקבה מאחור, \u0003חוץ משלשה שמשמשין פנים כנגד פנים, ואלו הן: דג ואדם ונחש.\u0004","ושואלים: \u0003ומאי שנא הני תלתא\u0004 \u0005[ו\u0006ב\u0005מה שונים שלושה אלה]?\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, מסר כי כך \u0003אמרי במערבא\u0004 \u0005[אומרים בארץ ישראל]\u0006 בטעם הדבר: \u0003הואיל ודיברה עמהם שכינה,\u0004 עם הדג שבלע את יונה (יונה ב, יא), עם אדם הראשון ושאר נביאים, ועם הנחש שהחטיא את אדם וחוה (בראשית ג, יד).","ועוד בענין זה, \u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003גמל\u0004 משמש \u0003אחור כנגד אחור.\u0004","ובאותו ענין של עיבור ולידה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003תרנגולת\u0004 מולידה לעשרים ואחד יום, וכנגדה באילן — \u0003לוז,\u0004 כלומר, שקד, שמבשיל עשרים ואחד יום מזמן הנצת הפרח. \u0003כלב\u0004 מוליד \u0003לחמשים יום, וכנגדו באילן\u0004 — \u0003תאינה. חתול\u0004 — \u0003לחמשים ושנים יום, וכנגדו באילן\u0004 — \u0003תות. חזיר\u0004 — \u0003לששים יום, כנגדו באילן\u0004 — \u0003תפוח. שועל וכל מיני שרצים\u0004 — \u0003ששה חדשים. וכנגדם באילן\u0004 — \u0003תבואה.\u0004","\u0003בהמה דקה טהורה,\u0004 רחל ועז — יולדת \u0003לחמשה חדשים, וכנגדן באילן\u0004 — \u0003גפן. בהמה גסה טמאה,\u0004 כגון הגמל והחמור — מולידה \u0003לשנים עשר חודש, וכנגדו באילן\u0004 — \u0003דקל.\u0004 בהמה גסה \u0003טהורה,\u0004 כגון פרה — \u0003לתשעה חדשים, וכנגדה באילן\u0004 — \u0003זית. הזאב והארי והדוב והנמר והברדלס והפיל והקוף והקיפוף\u0004 — \u0003לשלש שנים, וכנגדן באילן\u0004 — \u0003בנות שוח.\u0004","\u0003אפעה\u0004 מוליד \u0003לשבעים שנה, וכנגדו באילן\u0004 — \u0003חרוב. חרוב זה, משעת נטיעתו עד שעת גמר פירותיו\u0004 — \u0003שבעים שנה, וימי עיבורו שלש שנים. נחש\u0004 נולד \u0003לשבע שנים, ולאותו רשע,\u0004 הנחש — \u0003לא מצינו חבר\u0004 כנגדו במיני האילן. \u0003ויש אומרים:\u0004 מצאנו לו — \u0003מוכססים,\u0004 שהם גם כן נגמרים לשבע שנים.","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו],\u0006 שזמן עיבורו של נחש שבע שנים? \u0003אמר רב יהודה אמר רב, ומטו בה\u0004 \u0005[ו\u0006יש \u0005מגיעים בה]\u0006 בשמועה זו, לאומרה \u0003משום\u0004 (משמו של) \u0003ר' יהושע בן חנניא, שנאמר: \"ארור אתה מכל הבהמה ומכל חית השדה\"\u0004 (בראשית ג, יד), שזמן עיבורו יהא ארוך משל כולם. ויש לשאול: ומדוע להזכיר את חיית השדה? \u0003אם מבהמה נתקלל(ה), מחיה לא כל שכן?\u0004 שהרי ימי העיבור הקצרים ביותר של מין הבהמה (עז — חמישה חדשים) ארוכים משל ימי העיבור הקצרים ביותר של מין החיה (חתול — חמישים ושנים יום)!","\u0003אלא\u0004 דבר זה בא הכתוב \u0003לומר לך:\u0004 \u0003כשם\u0004 (באותו שיעור) \u0003שנתקללה הבהמה\u0004 יותר \u0003מחיה,\u0004 והוא \u0003אחד לשבעה,\u0004 \u0003ומאי ניהו\u0004 \u0005[ומה הוא]?\u0006 \u0003חמור מחתול,\u0004 שימי עיבורו של חמור, שנים עשר חודש (כשאר בהמה גסה טמאה) וימי עיבורו של חתול, חמישים ושנים יום — \u0003כך נתקלל הוא,\u0004 הנחש, \u0003מבהמה\u0004 כלומר, מן החמור, \u0003אחת לשבע, דהוה ליה שב שני\u0004 \u0005[שהוא לו שבע שנים].\u0006","ומקשים, \u0003אימא\u0004 \u0005[אמור]\u0006 ופרש באופן אחר: \u0003כשם שנתקללה חיה מבהמה,\u0004 שנה \u0003אחת ל\u0004עומת \u0003שלש שנים, ומאי ניהו\u0004 \u0005[ומי הוא]?\u0006 \u0003ארי מחמור,\u0004 שימי עיבורו של חמור שנים עשר חודש, ושל אריה שלוש שנים — \u0003כך נתקלל הוא,\u0004 הנחש, \u0003מחיה\u0004 כלומר, מארי, \u0003אחת\u0004 \u0003לשלש שנים, דהוה ליה\u0004 \u0005[שהוא לו]\u0006 \u0003תשע שנים!\u0004"],["ודוחים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \"ארור אתה \u0003מכל החיה ומכל הבהמה\"? \"מכל הבהמה ומכל החיה\" כתיב\u0004 \u0005[נאמר],\u0006 כלומר, \u0003ארור הוא מבהמה שנתקללה מחיה.\u0004 ומקשים עוד, ומדוע לפרש שנתקלל מחמור, כשם שנתקלל החמור מחתול?","\u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: \u0003כשם שנתקללה בהמה מחיה אחד לשלש, ומאי ניהו\u0004 \u0005[ומה הוא]?\u0006 \u0003עז מחתול,\u0004 שחתול מוליד לחמישים ושנים יום, ועז לחמישה חדשים — \u0003כך נתקלל הוא,\u0004 הנחש, \u0003מבהמה\u0004 זו, כלומר, מעז, \u0003אחד לשלש, דהוה ליה חמיסר ירחי\u0004 \u0005[שהריהם חמישה עשר חדשים]!\u0006","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \"ארור אתה \u0003מכל הבהמה\" כתיב\u0004 \u0005[נאמר],\u0006 וגם מזו המקוללת ביותר. \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 הלוא \u0003קללה הוא\u0004 שנתקלל הנחש בפסוק זה, ואם כן, כל \u0003קללה\u0004 שאתה יכול למצוא בכתוב זה \u0003שדי עילויה\u0004 \u0005[הטל עליו].\u0006","ובענין זמן עיבורו של הנחש, מסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003קיסר לר' יהושע בן חנניה: נחש לכמה מיעבר\u0004 \u0005[מתעבר]\u0006 \u0003ומוליד? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לשב שני\u0004 \u0005[לשבע שנים].\u0006 אמר לו: \u0003והא סבי דבי אתונא ארבעינהו, ואוליד לתלת\u0004 \u0005[והרי הזקנים,\u0006 החכמים \u0005של בית\u0006 חכמי \u0005אתונה הרביעו אותם, והוליד לשלוש\u0006 שנים\u0005]?\u0006 השיב לו: \u0003הנהו מיעברי הוו מעיקרא\u0004 \u0005[אלו מעוברים היו מתחילה]\u0006 כבר \u0003ארבע\u0004 שנים. שאלו הקיסר: \u0003והא קמשמשי שמושי\u0004 \u0005[והרי היו משמשים,\u0006 מזדווגים\u0005],\u0006 ובעל חיים אינו משמש אלא כדי להוליד, ולא כשהוא מעובר! ענה לו: \u0003אינהו נמי משמשי\u0004 \u0005[הם,\u0006 הנחשים, \u0005גם כן משמשים]\u0006 \u0003כאדם,\u0004 ולא להולדה דווקא. אמר לו: כיצד יכול אתה לחלוק על זקני אתונה?","\u0003והא חכימי אינהו\u0004 \u0005[והרי חכמים הם]!\u0006 אמר לו ר' יהושע: \u0003אנן חכימינן מינייהו\u0004 \u0005[אנו חכמים\u0006 יותר \u0005מהם].\u0006 אמר לו: \u0003אי חכימת, זיל זכינהו ואיתינהו לי\u0004 \u0005[אם חכם אתה\u0006 מהם, \u0005לך נצח אותם והבא אותם אלי]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע: \u0003כמה הוו\u0004 \u0005[הם]?\u0006 אמר לו: \u0003שיתין גברי\u0004 \u0005[שישים איש].\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עביד לי ספינתא דאית בה שיתין בתי\u0004 \u0005[עשה לי ספינה שיש בה שישים בתים,\u0006 חדרים\u0005],\u0006 \u0003וכל ביתא אית בה שיתין ביסתרקי\u0004 \u0005[וכל בית יש בו שישים מצעות].\u0006 \u0003עבד ליה\u0004 \u0005[עשה לו]\u0006 הקיסר כן. הפליג ר' יהושע עם הספינה לאתונה. \u0003כי מטא להתם לבי טבחא\u0004 \u0005[כאשר הגיע לשם, לבית הטבח,\u0006 הקצב\u0005],\u0006 \u0003אשכחיה לההוא גברא דקא פשיט חיותא\u0004 \u0005[מצאו לאותו אדם,\u0006 את הקצב, \u0005שהיה פושט\u0006 עור \u0005בהמה],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רישך לזבוני\u0004 \u0005[ראשך למכירה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע: \u0003בכמה? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בפלגא דזוזא\u0004 \u0005[בחצי זוז].\u0006 \u0003יהב ליה\u0004 \u0005[נתן לו].\u0006","\u0003לסוף,\u0004 לאחר ששילם לו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע: \u0003אנא רישא דחיותא אמרי\u0004 \u0005[אני את ראש הבהמה אמרתי]\u0006 \u0003לך?\u0004 על ראשך שלך דיברתי, וצריך אתה לעמוד בדיבורך. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע: \u0003אי בעית דאשבקך, סגי אחוי לי פיתחא דבי אתונא\u0004 \u0005[אם אתה רוצה שאניח לך, לך והראה לי\u0006 את \u0005הפתח של בית\u0006 חכמי \u0005אתונה]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מסתפינא, דכל דמחוי קטלי ליה\u0004 \u0005[מתיירא אני,\u0006 לפי \u0005שכל שמראה\u0006 את מקומם \u0005הורגים\u0006 הם \u0005אותו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דרי כריכא דקניא\u0004 \u0005[קח חבילת קנים],\u0006 \u0003וכי מטית להתם זקפה כמאן דקא מתפח\u0004 \u0005[וכאשר תגיע לשם זקוף,\u0006 העמד \u0005אותה כמי שנח].\u0006 עשה כן, וכך הגיע ר' יהושע אל המקום.","\u0003אשכח דרבנאי מגואי ודרבנאי מבראי\u0004 \u0005[מצא שומרים מבחוץ ושומרים מבפנים],\u0006 לשמור שלא ייכנס לשם אדם ולא יצא משם אדם. ופיזרו הממונים חול בכניסה, כדי לגלות עקבות נכנסים ויוצאים, \u0003דאי חזו כרעא דעיילא קטלי להו לבראי\u0004 \u0005[שאם\u0006 היו הממונים \u0005רואים\u0006 עקבות \u0005רגל שנכנסת\u0006 — \u0005הורגים את\u0006 השוטרים \u0005שבחוץ],\u0006 על שנתנו לאדם להיכנס, \u0003ודנפקא קטלי להו לגואי\u0004 \u0005[ו\u0006כשרואים רגל \u0005שיוצאת הורגים את ה\u0006שומרים \u0005שבפנים],\u0006 על שנתנו לאדם לצאת משם.","\u0003אפכה לסנדליה\u0004 \u0005[הפך את סנדלו]\u0006 ודרך על החול כאילו יצא מן המקום, והתחמק. וכשראו הממונים את העקבות \u0003קטלי להו לגואי\u0004 \u0005[הרגו את הפנימים],\u0006 לאחר מכן שוב \u0003אפכה לסנדליה\u0004 \u0005[הפך את סנדלו]\u0006 חזרה והשאיר עקבות של כניסה, וכך \u0003קטלי להו לכולהו\u0004 \u0005[הרגו את כולם],\u0006 גם את החיצונים. בין כך ובין כך הצליח ר' יהושע להיכנס פנימה.","\u0003אשכח ינוקי מלעיל סבי מלתחת\u0004 \u0005[מצא את הצעירים\u0006 יושבים \u0005מלמעלה\u0006 במקום המכובד יותר, \u0005ואת הזקנים מלמטה],\u0006 \u0003אמר\u0004 לעצמו: צריך אני להקדים שלום ליושבים למעלה מן האחרים, והם הצעירים. ואולם \u0003אי יהיבנא שלמא להני קטלי לי הני\u0004 \u0005[אם אתן\u0006 תחילה \u0005שלום לאלה,\u0006 הצעירים, \u0005יהרגו אותי אלה,\u0006 הזקנים\u0005],\u0006 \u0003סברי\u0004 \u0005[כסבורים\u0006 הם\u0005]\u0006 \u0003אנן עדיפינן דאנן קשינן טפי ואינהו דרדקי\u0004 \u0005[אנו עדיפים, שאנו זקנים יותר והם צעירים].\u0006","\u0003אמר: שלמא לכו\u0004 \u0005[שלום לכם]!\u0006 ולא פנה לקבוצה מסויימת. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מאי עבידתיך\u0004 \u0005[מה מעשיך\u0006 כאן\u0005]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנא חכימא דיהודאי אנא\u0004 \u0005[אני חכם היהודים אני],\u0006 \u0003בעינא למיגמר חכמתא מינייכו\u0004 \u0005[רוצה אני ללמוד חכמה מכם].\u0006 אמרו לו: \u0003אי הכי, ניבעי לך\u0004 \u0005[אם כך, נשאל אותך\u0006 שאלות\u0005],\u0006 ונראה אם ראוי אתה לכך. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לחיי\u0004 \u0005[בסדר],\u0006 \u0003אי זכיתו\u0004 \u0005[אם תנצחו]\u0006 — \u0003כל דבעיתו עבידו בי\u0004 \u0005[כל שתרצו עשו בי],\u0006 \u0003ואי זכינא בכו\u0004 \u0005[ואם אני אנצח אתכם]\u0006 — \u0003איכלו גבאי בספינתא\u0004 \u0005[איכלו בספינה\u0006 שלי\u0005].\u0006","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ההוא גברא דאזיל ובעי אתתא ולא יהבו ליה\u0004 \u0005[אדם זה שהולך ומבקש אישה\u0006 ממשפחה אחת \u0005ולא נתנו לו],\u0006 \u0003מאי חזי ליה דאזיל היכא דמדלו מיניה\u0004 \u0005[מה הוא רואה לו,\u0006 מה הוא סבור, \u0005שהוא הולך למקום שהוא גבוה ממנו],\u0006 למשפחה חשובה ומיוחסת מזו הראשונה? \u0003שקל סיכתא\u0004 \u0005[לקח יתד],\u0006 \u0003דצה לתתאי לא עאל\u0004 \u0005[נעץ אותה למטה\u0006 בקיר ו\u0005לא נכנסה],\u0006 \u0003לעילאי\u0004 — \u0003עאל\u0004 \u0005[\u0006נעץ אותה \u0005למעלה\u0006 — \u0005נכנסה]\u0006 שהיה שם חור, \u0003אמר\u0004 להם: \u0003האי נמי מיתרמי בת מזליה\u0004 \u0005[זה גם כן,\u0006 הולך לחפש במקום גבוה יותר, שמא \u0005תזדמן\u0006 לו שם \u0005בת מזלו].\u0006","ועוד שאלוהו: \u0003גברא דאוזיף\u0004 \u0005[אדם שמלוה\u0006 לחבירו\u0005]\u0006 לצורך עיסקה, ואין הלה פורע את חובו, \u0003וטריף\u0004 \u0005[ו\u0006המלוה \u0005טורף,\u0006 נוטל את קרקעותיו\u0005]\u0006 כדי לגבות את חובו, ויש בכך טורח גדול, \u0003מאי חזא דהדר אוזיף\u0004 \u0005[מה ראה ש\u0006הוא \u0005חוזר ומלוה]\u0006 לאנשים אחרים? \u0003אמר להו\u0004 \u0005[להם]:\u0006 כן דרכם של אנשים, \u0003גברא אזל לאגמא, קטל קמא טונא ולא מצי ביה\u0004 \u0005[אדם הולך לאגם, חותך בתחילה משא של קנים ולא יכול\u0006 להרים \u0005אותו],\u0006 אינו מפסיק לחתוך קנים, אלא \u0003קטיל ומנח עילויה, עד דאיתרמי איניש מדלי ליה\u0004 \u0005[חותך\u0006 עוד \u0005ומניח עליו, עד שיזדמן אדם שירים אותו]\u0006 על כתפיו, והוא נושאו לביתו. כך אדם ממשיך להלוות מתוך הנחה שבסופו של דבר יזדמן לידיו לווה הגון.","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אימא לן מילי דבדיאי\u0004 \u0005[אמור לנו דברי כזב]!\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הוה ההוא כודניתא דילידא\u0004 \u0005[היתה פרדה אחת שילדה],\u0006 \u0003והוה תלי ליה פיתקא\u0004 \u0005[והיה תלוי לו,\u0006 לולד, \u0005פתק\u0006 על צוארו\u0005],\u0006 \u0003וכתב ביה דמסיק בבי אבא מאה אלפא זוזי\u0004 \u0005[וכתוב בו ש\u0006הוא \u0005נושה,\u0006 שחייבים לו \u0005בבית אביו מאה אלף זוז].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003וכודניתא מי ילדה\u0004 \u0005[ופירדה האם\u0006 היא \u0005יולדת]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הי ניהו מילי דבדיאי\u0004 \u0005[הם אלו דברי כזב],\u0006 שדבר זה לא ייתכן כלל.","ועוד שאלו אותו: \u0003מילחא כי סריא, במאי מלחי לה\u0004 \u0005[מלח כאשר הוא מסריח, במה מולחים אותו]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003בסילתא דכודניתא\u0004 \u0005[בשיליה של פירדה].\u0006 אמרו לו: לא ייתכן הדבר, \u0003ומי איכא סילתא לכודנתא\u0004 \u0005[והאם יש שיליה לפירדה]?\u0006 אמר להם: גם מה ששאלתם לא ייתכן, \u0003ומילחא מי סרי\u0004 \u0005[ו\u0006כי \u0005מלח האם\u0006 הוא \u0005מסריח]?\u0006","אמרו לו: \u0003בני לן ביתא באוירא דעלמא\u0004 \u0005[בנה לנו בית באויר העולם]!\u0006 \u0003אמר שם\u0004 משמותיו של הקדוש ברוך הוא, \u0003תלא בין רקיעא לארעא\u0004 \u0005[ונתלה בין השמים לארץ],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אסיקו לי ליבני וטינא\u0004 \u0005[העלו לי\u0006 אתם \u0005לבנים וטיט],\u0006 ואבנה לכם בית. שאלו אותו: \u0003מציעתיה דעלמא היכא\u0004 \u0005[אמצעו של העולם היכן]?\u0006 \u0003זקפה לאצבעתיה אמר להו\u0004 \u0005[זקף את אצבעו ואמר להם]:\u0006 \u0003הכא\u0004 \u0005[כאן].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ומי יימר\u0004 \u0005[ומי יאמר]\u0006 מניין שדבריך נכונים? אמר להם: \u0003אייתו אשלי ומשחו\u0004 \u0005[הביאו חבלים ומדדו]!\u0006","אמרו לו: \u0003אית לן בירא בדברא, עיילא למתא\u0004 \u0005[יש לנו בור בשדה, הכנס\u0006 אותו \u0005לעיר]!\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אפשילו לי חבלי מפארי ואעייליה\u0004 \u0005[הפשילו,\u0006 עשו \u0005לי\u0006 חבלים עשויים \u0005מסובין ואכניס\u0006 לעיר \u0005אותו]\u0006 בעזרתם. ועוד אמרו לו: \u0003אית לן ריחיא דתבירא, חייטיה\u0004 \u0005[יש לנו ריחיים שנשברו, תפור אותם]!\u0006 \u0003אמר: כרוכו לי מיניה גרדי ואיחייטיה\u0004 \u0005[עשו לי ממנה חוטים ואתפור אותם].\u0006","שאלו אותו: \u0003משרא דסכיני במאי קטלי\u0004 \u0005[שדה של סכינים במה קוצרים\u0006 אותה\u0005]?\u0006 אמר להם: \u0003בקרנא דחמרא\u0004 \u0005[בקרן של חמור].\u0006 אמרו לו: \u0003ומי איכא קרנא לחמרא\u0004 \u0005[והאם יש קרן לחמור]?\u0006 אמר להם: \u0003ומי איכא משרא דסכיני\u0004 \u0005[והאם יש שדה של סכינים]?\u0006","\u0003אייתו ליה תרי ביעי\u0004 \u0005[הביאו לו שתי ביצים],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003הי דזגתא אוכמתי והי דזגתא חיוורתי\u0004 \u0005[איזו היא של תרנגולת שחורה ואיזו של תרנגולת לבנה]?\u0006 \u0003אייתי להו איהו תרי גביני\u0004 \u0005[הביא להם הוא שתי גבינות],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הי דעיזא אוכמתי והי דעיזא חיוורתי\u0004 \u0005[איזו מהם של עז שחורה ואיזו של עז לבנה]?\u0006","שאלו אותו: \u0003ורצוצא דמית, מהיכא נפיק רוחיה\u0004 \u0005[ואפרוח שמת\u0006 בביצה, \u0005מהיכן יוצאת רוחו]?\u0006 אמר להם: \u0003מהיכא דעל נפק\u0004 \u0005[ממקום ש\u0006היא \u0005נכנסת\u0006 משם \u0005יוצאת].\u0006 אמרו לו: \u0003אחוי לן מנא דלא שוי חביליה\u0004 \u0005[הראה לנו כלי שאינו שווה\u0006 את \u0005נזקו שהוא גורם]!\u0006 אמר להם: \u0003אייתו בודיא, פשטוה\u0004 \u0005[הביאו מחצלת, פרשו אותה],\u0006 \u0003לא הוה עייל בתרעא\u0004 \u0005[לא נכנסה בשער],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אייתו מרי סיתרוה\u0004 \u0005[הביאו מעדרים\u0006 ו\u0005שברו אותו\u0006 את השער\u0005],\u0006 כדי שתוכלו להכניס אותה; \u0003היינו מנא דלא שוו חביליה\u0004 \u0005[זהו כלי שאינו שווה את נזקו].\u0006","משניצח ר' יהושע את חכמי אתונה, \u0003איתינהו\u0004 \u0005[הביא אותם]\u0006 לספינה שהכין, כפי שהתנה עמם מתחילה, והכניס כל אחד מהם לחדר אחר. \u0003כל חד וחד כי חזי שיתין ביסתרקי\u0004 \u0005[כל אחד ואחד\u0006 מהם \u0005כאשר ראה שישים מצעות]\u0006 בחדרו, \u0003אמר: כולהו חבראי להכא אתו\u0004 \u0005[כל חבירי לכאן הם באים],\u0006 והמתין להם, וכך לא יצא אף אחד מחדרו. בינתיים \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע \u0003לספונא\u0004 \u0005[לספן]:\u0006 \u0003שרי\u0004 \u0005[התר את]\u0006 \u0003ספינתך\u0004 והפלג. \u0003בהדי דקאתו שקל עפרא מעפרייהו\u0004 \u0005[בזמן שבאו\u0006 איתו לספינה \u0005לקח עפר מעפרם],\u0006 מאתונה,"],["\u0003כי מטי לבי בליעי\u0004 \u0005[כאשר הגיעו לבית הבלועים,\u0006 מקום בים שבו בולעים המים כל מה שמגיע לשם\u0005],\u0006 \u0003מלא כוזא דמיא מבי בליעי\u0004 \u0005[מילא כד קטן של מים מבית הבלועים].\u0006 \u0003כד אתו אוקמינהו קמי קיסר\u0004 \u0005[כאשר באו, העמיד אותם לפני הקיסר].\u0006 \u0003חזנהו דהוו מעני\u0004 \u0005[ראה אותם\u0006 הקיסר \u0005שהם מעונים],\u0006 מפני שהיו בשבי, \u0003אמר ליה\u0004 \u0005[לו]\u0006 הקיסר לר' יהושע בן חנניה: \u0003הני לאו נינהו\u0004 \u0005[אלה אינם הם]!\u0006 שזקני אתונה תקיפים הם וגאים. \u0003שקל מעפרייהו ושדא עילוייהו\u0004 \u0005[לקח\u0006 ר' יהושע \u0005מעפרם\u0006 שנטל עמו \u0005וזרק עליהם],\u0006 וכיון שהריחו ריח מקומם — חזרה נפשם אליהם, \u0003אקשו לאפי מלכא\u0004 \u0005[העיזו ודיברו קשות בפני המלך].\u0006 כיון שכך \u0003אמר ליה\u0004 \u0005[לו]\u0006 הקיסר לר' יהושע: \u0003כל דבעית עביד בהו\u0004 \u0005[כל שאתה רוצה עשה בהם].\u0006","\u0003אייתינהו מיא דאייתי מבי בליעי\u0004 \u0005[הביא\u0006 את ה\u0005מים שהביא מבית הבלועים],\u0006 שבולעים הכל, \u0003שדינהו בתיגדא\u0004 \u0005[שפך אותם בכלי],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מליוה להו ואיזילו לכו\u0004 \u0005[מלאו אותו ולכו לכם]\u0006 לדרככם. \u0003מלו ושדו ביה קמאי קמאי ובלע להו\u0004 \u0005[ומילאו ושפכו בו ראשונים ראשונים ובלע אותם]\u0006 הכלי, וכך \u0003מלו\u0004 \u0005[מילאו,\u0006 עוד ועוד\u0005]\u0006 \u0003עד דשמיט כתפייהו\u0004 \u0005[שנשמטו כתפיהם],\u0006 \u0003ובלי להו ואזול\u0004 \u0005[ובלו להם והלכו,\u0006 כלו\u0005]\u0006 אותם חכמי אתונה.","\u0003חמורה ש\u0004עדיין \u0003לא ביכרה, וילדה שני זכרים\u0004 — \u0003נותן טלה אחד לכהן\u0004 כפדיון פטר חמור, שהרי אחד מהם בוודאי בכור. אם ילדה החמורה \u0003זכר ונקבה,\u0004 ואינו יודע אם הזכר נולד ראשון וחייב בפדיונו, או אם הנקבה נולדה תחילה ואין כאן דין בכורה — \u0003מפריש טלה אחד\u0004 מספק, שמא הזכר נולד ראשון, ואולם הבעלים נוטל את הטלה \u0003לעצמו,\u0004 שאין זה אלא חוב כספי לכהן, ובכל ספק שבדיני ממונות — המוציא מחבירו עליו הראיה.","\u0003שתי חמוריו שלא ביכרו וילדו שני זכרים\u0004 — \u0003נותן שני טלאים לכהן,\u0004 ששניהם בכורות ודאים. ילדו \u0003זכר ונקבה, או שני זכרים ונקבה\u0004 — \u0003נותן טלה אחד לכהן,\u0004 שאחד מן הזכרים ודאי בכור. ילדו \u0003שתי נקבות וזכר או שני זכרים ושתי נקבות\u0004 — \u0003אין לכהן כלום,\u0004 שמא שתי החמורות ילדו נקבות בתחילה.","ומקרה נוסף: היו לו שתי חמורות, \u0003אחת\u0004 שכבר \u0003ביכרה\u0004 ונפטרה מן הבכורה, \u0003ואחת ש\u0004עדין \u0003לא ביכרה, וילדה\u0004 (וילדו) \u0003שני זכרים\u0004 — \u0003נותן טלה אחד לכהן,\u0004 לפדיון הזכר של זו שלא ביכרה. ילדו \u0003זכר ונקבה\u0004 — \u0003מפריש טלה אחד,\u0004 מספק, שמא הזכר נולד לזו שלא ביכרה, ואולם נוטל אותו \u0003לעצמו,\u0004 שהמוציא מחבירו עליו הראיה. ומנין שפודים פטר חמור בטלה?","\u0003שנאמר: \"ופטר חמור תפדה בשה\"\u0004 (שמות לד, ב). ונותן שה בין \u0003מן הכבשים ו\u0004בין \u0003מן העזים,\u0004 בין \u0003זכר ו\u0004בין \u0003נקבה, גדול\u0004 או \u0003קטן, תמים\u0004 או \u0003בעל מום.\u0004 ו\u0003פודה בו\u0004 באותו שה\u0003פעמים הרבה,\u0004 אם חזר הכהן ונתנו לו. וכשמפריש טלה מספק, והוא נוטלו לעצמו — הריהו שלו לכל דבר, ולכן \u0003נכנס לדיר להתעשר,\u0004 כלומר, להיות חלק מן העדר שמפריש ממנו מעשר בהמה. \u0003ואם מת\u0004 — \u0003נהנין בו,\u0004 כאשר יבואר בגמרא.","שנינו במשנה כי חמורה שלא ביכרה וילדה שני זכרים — נותן טלה אחד לכהן. ושואלים: \u0003מאן תנא\u0004 \u0005[מיהו התנא]\u0006 של משנתנו, הסבור כי אין הכהן מקבל אלא טלה אחד במקרה כזה? \u0003אמר ר' ירמיה:\u0004 הרי זה ש\u0003לא כ\u0004שיטת \u0003ר' יוסי הגלילי,\u0004 אלא כשיטת החולקים עליו. דאי \u0005[שאם]\u0006 כשיטת \u0003ר' יוסי הגלילי\u0004 — \u0003האמר\u0004 \u0005[הרי\u0006 הוא \u0005אומר]\u0006 במשנה להלן (יז,א) לגבי בהמה טהורה שילדה שני זכרים, ויצאו שני ראשיהם כאחד, ש\u0003אפשר לצמצם,\u0004 כלומר, ייתכן ושני דברים יחולו בו זמנית, ושניהם בכורות. אבל לדעת חכמים החולקים עליו אי אפשר לצמצם, אלא אחד בכור ואחד אינו בכור, והיא איפוא שיטת משנתנו.","\u0003אמר אביי:\u0004 יש להסביר את משנתנו \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיא כדעת \u0003ר' יוסי הגלילי,\u0004 שכן \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 לענין בהמה טהורה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"וכל פטר שגר בהמה... \u0003הזכרים לה' \"\u0004(שמות יג, יב) בלשון רבים, לומר: אפילו יצאו שנים כאחד — הריהם בכורות. אבל לא נאמר כן לגבי פטר חמור, ולכן רק אחד מהם בכור.","ושואלים: \u0003וליגמר מיניה\u0004 \u0005[ונלמד ממנו],\u0006 ממה שנאמר בבכור בהמה טהורה לפטר חמור! ומשיבים: \u0003הא מיעט רחמנא\u0004 \u0005[הרי מיעטה התורה]\u0006 בלשון \u0003\"הזכרים\",\u0004 בה' הידיעה, לומר: דווקא הזכרים הללו, ולא של פטר חמור.","ומעירים: \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 סוגיה זו בלשון אחרת: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 שמשנתנו ש\u0003לא כ\u0004שיטת \u0003ר' יוסי הגלילי? דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003ר' יוסי הגלילי\u0004 — \u0003האמר\u0004 \u0005[הרי\u0006 הוא \u0005אומר]\u0006 לגבי בכור בהמה טהורה: \u0003אפשר לצמצם,\u0004 ואם נולדו כאחד — שניהם בכורות! \u0003אמר אביי: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו שיטת \u0003ר' יוסי הגלילי\u0004 היא, \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 לגבי בהמה טהורה, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"הזכרים לה' \".\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' ירמיה, דלא מוקי לה\u0004 \u0005[שאינו מעמיד אותה,\u0006 את משנתנו\u0005]\u0006 \u0003כר' יוסי הגלילי\u0004 — \u0003היינו דלא קתני\u0004 \u0005[זהו שאינו שונה\u0006 בה\u0005]\u0006 \u0003\"ויצאו שני ראשיהן כאחד\",\u0004 משום שלא ייתכן מקרה כזה, וכדעת חכמים החולקים עליו. אלא לדעת \u0003אביי,\u0004 שסבור שמשנתנו היא כשיטתו של ר' יוסי הגלילי, שמקרה כזה ייתכן — \u0003ליתני\u0004 \u0005[שישנה]\u0006 במשנתנו: \u0003\"ויצאו שני ראשיהן כאחד\",\u0004 ללמד שאפילו במקרה זה אינו נותן לכהן אלא טלה אחד!","\u0003ועוד, תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003חמורו שלא ביכרה וילדה שני זכרים, ויצאו שני ראשיהן כאחד, ר' יוסי הגלילי אומר: שניהן לכהן, שנאמר \"הזכרים לה' \".\u0004","ויש להקשות: \u0003והא\u0004 \u0005[והרי]\u0006 לדברי אביי, \u0003כי כתיב האי\u0004 \u0005[כאשר נאמר\u0006 פסוק \u0005זה],\u0006 \u0003בקדושת הגוף הוא דכתיב\u0004 \u0005[שנאמר],\u0006 לשיטת ר' יוסי הגלילי, כלומר, בבכור בהמה טהורה, ולא בפטר חמור! \u0003אלא\u0004 רואים אנו כי \u0003משום שנאמר \"הזכרים לה' \"\u0004בבהמה טהורה, למדים אנו גם לבהמה טמאה שהדין כן, ואם כן \u0003תיובתא\u0004 \u0005[קושיה\u0006 חמורה\u0005]\u0006 היא זו על דברי \u0003אביי!\u0004 ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה\u0006 חמורה \u0005היא],\u0006 ונדחו דבריו. ומשנתנו היא איפוא כשיטת חכמים החולקים על ר' יוסי, וסבורים כי אי אפשר לצמצם, וגם כשיצאו ראשיהם כאחד — רק אחד מהם בכור."],["ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003לימא קסברי רבנן\u0004 \u0005[האם נאמר\u0006 ש\u0005סבורים חכמים]\u0006 כי אפילו \u0003מקצת\u0004 פתח ה\u0003רחם מקדיש\u0004 \u0005[מקדש]\u0006 בבכורה, גם אם לא נגע הולד בכולו? \u0003דאי כוליה\u0004 \u0005[ש\u0006הרי \u0005אם\u0006 דוקא \u0005כל]\u0006 פתח ה\u0003רחם מקדיש,\u0004 הרי במקרה שיצאו ראשיהם כאחד — נהי \u0005[אם אמנם]\u0006 ש\u0003אי אפשר לצמצם,\u0004 ואחד מהם יצא ראשון — \u0003חציצה מיהא איכא\u0004 \u0005[על כל פנים יש\u0006 \u0005כאן],\u0006 על ידי ראשו של הולד האחר!","\u0003אמר רב:\u0004 אין מכאן ראיה שגם מקצת רחם מקדש, שהרי \u0003מין במינו אינו חוצץ,\u0004 ולכן אין אחד נחשב חציצה לחבירו.","שנינו במשנה שחמורה שלא ביכרה וילדה \u0003זכר ונקבה,\u0004 ואין ידוע מי מהם נולד ראשון — \u0003מפריש טלה\u0004 לפדיון הזכר, והוא לעצמו. ושואלים: \u0003וכיון\u0004 ש\u0003לעצמו הוא, למה לי לאפרושי\u0004 \u0005[להפריש\u0006 אותו\u0005]?\u0006 ומשיבים: \u0003לאפקועי לאיסוריה מיניה\u0004 \u0005[\u0006כדי \u0005להפקיע את האיסור ממנו].\u0006","ומעירים: \u0003אלמא\u0004 \u0005[מכאן]\u0006 יש להסיק כי קודם ההפרשה, \u0003כיון\u0004 ש\u0003לא מפקע\u0004 \u0005[מופקעת\u0006 הקדושה ממנו\u0005]\u0006 \u0003אסור\u0004 פטר החמור \u0003בהנאה.\u0004 ואם כן, \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי\u0006 היא\u0005]\u0006 — כשיטת \u0003ר' יהודה היא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003פטר חמור אסור בהנאה,\u0004 אלו דברי ר' יהודה, \u0003ור' שמעון מתיר.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה\u0006 ה\u0005טעם]\u0006 של \u0003ר' יהודה? אמר עולא:\u0004 וכי \u0003יש לך\u0004 \u0003דבר שצריך פדייה, ו\u0004בכל זאת \u0003מותר\u0004 בהנאה? ותוהים: \u0003ולא?\u0004 האם אין דבר כזה? \u0003והרי בכור אדם שצריך פדייה\u0004 בחמשה סלעים, \u0003ומותר,\u0004 שאין איסור ליהנות ממעשה ידיו של בכור שלא נפדה! ומשיבים: \u0003אלא\u0004 כך צריך לומר: וכי \u0003יש לך דבר שהקפידה עליו תורה\u0004 והחמירה בדינו, שדרך פדיונו \u0003בשה\u0004 דווקא, \u0003ומותר?\u0004","ותמהים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003הקפידה\u0004 התורה על כך? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב נחמיה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף פריק ליה בשילקי\u0004 \u0005[\u0006היה \u0005פודה לו,\u0006 לפטר חמור, \u0005בשלקות,\u0006 עשבים מבושלים\u0005]\u0006 \u0003בשויו!\u0004 ומשיבים: פדיון \u0003בשויו לא קאמר\u0004 \u0005[אין\u0006 עולא \u0005אומר],\u0006 לא לכך התייחס עולא. \u0003כי קאמרינן\u0004 \u0005[כאשר אנו אומרים]\u0006 שאין לך דבר שהקפידה עליו התורה בשה, הרי זה במקרה שפודהו \u0003שלא בשויו. והכי קאמר\u0004 \u0005[וכך אומר]\u0006 עולא: וכי \u0003יש לך דבר שהקפידה עליו תורה לאפקועי לאיסוריה\u0004 \u0005[להפקיע את איסורו]\u0006 דווקא \u0003בשה,\u0004 ולא בבעל חיים אחר, ומותר? ומשום כך סבור ר' יהודה שפטר חמור אסור בהנאה.","ומקשים על הסבר זה: \u0003והרי מעשר\u0004 שני, \u0003שהקפידה עליו תורה\u0004 שיפדו אותו דווקא \u0003בכסף צורי,\u0004 כלומר, במטבע שיש עליו צורה, ולא באסימון שלא הוטבעה בו צורה. \u0003ותנן\u0004 \u0005[ו\u0006מכל מקום \u0005שנינו],\u0006 \u0003ר' יהודה אומר:\u0004 אם קידש אשה במעשר שני \u0003במזיד\u0004 — \u0003קידש,\u0004 ומכאן שלדעתו אינו אסור בהנאה קודם פדיונו!","ומשיבים: אין להוכיח מדין קידושי אשה, שכן לדעת ר' יהודה, אם קידש אדם אשה \u0003בפטר חמור נמי מיקדשא\u0004 \u0005[גם כן\u0006 היתה \u0005מתקדשת],\u0006 אף אם נאמר שהוא אסור בהנאה. שהרי טעם הדבר שאשה מתקדשת במעשר שני, אינו משום שהוא מותר בהנאה באותה שעה, אלא \u0003כ\u0004דברי \u0003ר' אלעזר,\u0004 ש\u0003אמר ר' אלעזר: אשה\u0004 המתקדשת במעשר שני יודעת שאין מעשר שני מתחלל על ידה כאשר היא מתקדשת בו, והוא נשאר באיסורו, \u0003ו\u0004היא מתקדשת בו משום שהיא \u0003עולה ואוכלתו בירושלים,\u0004 ששם הוא מותר באכילה, ובהנאה זו היא מתקדשת.","\u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 כשמקדש אשה בפטר חמור, למרות שהוא אסור בהנאה — הרי אלו קידושין, משום ש\u0003אשה יודעת\u0004 ש\u0003פטר חמור איסורא אית ביה\u0004 \u0005[איסור יש בו],\u0006 \u0003ופרקא ליה\u0004 \u0005[ו\u0006היא \u0005פודה אותו]\u0006 \u0003בשה, ומקדשא בהך דביני וביני\u0004 \u0005[ומתקדשת באותו\u0006 הבדל המחיר \u0005ש\u0006יש \u0005בין זה ובין זה],\u0006 בין ערך החמור שנשאר בידיה, לבין ערך השה, שהוא נמוך יותר.","ושואלים: \u0003ור' שמעון מאי טעמא\u0004 \u0005[מה טעם]\u0006 אמר שפטר חמור מותר בהנאה קודם שייפדה? \u0003אמר עולא:\u0004 וכי \u0003יש לך דבר שפדיונו מותר והוא אסור?\u0004 שהרי השה הניתן לכהן בפדיונו מותר לגמרי.","ותוהים: \u0003ולא? והרי שביעית\u0004 ש\u0003פדיונה מותר,\u0004 שהמוכר פירות שביעית — הדמים שקיבל תמורתם מותרים, \u0003והיא אסורה\u0004 בהנאה, משיכלה אותו מין מן השדה, ויגיע זמן הביעור מן הבית!","ומשיבים: \u0003שביעית נמי\u0004 \u0005[גם כן]\u0006 \u0003פדיונה אסור,\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 הלוקח בשר בפירות שביעית — גם הפירות וגם הבשר אסורים מזמן הביעור. לקח בבשר יין — הותר הבשר ונאסר היין, וכך הלאה, ו\u0003האחרון אחרון\u0004 שלוקח בו פירות שביעית — הרי זה \u0003אסור.\u0004 עד כאן הובאו טעמים מן הסברה למחלוקת ר' יהודה ור' שמעון, האם פטר חמור אסור בהנאה קודם פדייה.","ומוסיפים, \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0005ר' יהודה ור' שמעון\u0006 \u0003בהאי קרא קמיפלגי\u0004 \u0005[בפסוק זה הם חלוקים].\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 ביחס לאיסור עבודה וגיזה בבכור בהמה טהורה: נאמר \u0003\"לא תעבד בבכור שורך\"\u0004 (דברים טו, יט), ומלשון זו למדו: \u0003אבל אתה עובד בשלך ובשל אחרים\u0004 (גוים), שהמשתתף עם הגוי בבהמה — אין הבכור קדוש, והוא מותר בהנאה. \u0003\"ולא תגז בכור צאנך\"\u0004 — \u0003אבל אתה גוזז\u0004 בכור שהוא \u0003שלך ושל אחרים,\u0004 אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' שמעון אומר,\u0004 כך יש לדרוש את הכתוב: \u0003\"לא תעבד בבכור שורך\"\u0004 — \u0003אבל אתה עובד בבכור אדם,\u0004 שאין איסור ליהנות ממעשה ידיו של בכור, גם קודם שנפדה. \u0003\"לא תגז בכור צאנך\"\u0004 — \u0003אבל אתה גוזז בכור חמור,\u0004 שפטר חמור מותר בהנאה. ור' יהודה שאינו דורש כן, סבור שגם בכור חמור אסור בגיזה ושאר הנאות.","ושואלים על נוסח הדברים שבברייתא זו: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' שמעון, היינו דכתיב תרי קראי\u0004 \u0005[זהו שכתובים שני מקראות],\u0006 אחד למעט בכור אדם ואחד למעט בכור חמור, \u0003אלא לר' יהודה, תרי קראי למעוטי\u0004 \u0005[שני מקראות למעט]\u0006 בהמה \u0003שלך ושל אחרים\u0004 (גוים) מאיסור הנאה, \u0003למה לי? ותו\u0004 \u0005[ועוד],\u0006 אם באופן זה נחלקו, \u0003ל\u0004שיטת \u0003ר' יהודה בכור אדם נמי\u0004 \u0005[גם כן],\u0006 \u0003נימא דאסיר\u0004 \u0005[נאמר שאסור]\u0006 ליהנות ממעשה ידיו, הואיל ולא נתמעט בכתוב!","\u0003אלא\u0004 צריך לומר כי \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003\"שורך\"\u0004 — \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003בכור אדם הוא דאתא\u0004 \u0005[שבא],\u0006 שמותר בהנאה. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003\"בצאנך\",\u0004 ש\u0003ר' יהודה\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר: שותפות גוי חייבת בבכורה, וכי איצטריך קרא\u0004 \u0005[וכאשר הוצרך המקרא]\u0006 הרי זה \u0003למישרי\u0004 \u0005[להתיר אותו]\u0006 \u0003בגזה ועבודה.\u0004","\u0003ור' שמעון סבר\u0004 \u0005[סבור]:\u0006 \u0003שותפות גוי פטורה מן הבכורה\u0004 לגמרי, \u0003ולענין\u0004 היתר \u0003גזה ועבודה\u0004 במקרה כזה, ממילא \u0003לא איצטריך קרא\u0004 \u0005[הוצרך המקרא].\u0006 אלא \u0003כי איצטריך קרא\u0004 \u0005[כאשר הוצרך המקרא]\u0006 למעט מאיסור גיזה ועבודה הרי זה \u0003לפטר חמור.\u0004","ושואלים עוד: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לר' יהודה, היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"צאנך\",\u0004 ולא \"צאן\" — למעט צאן שאינו לגמרי שלך, שיש לגוי שותפות בו. \u0003ו\u0004מה שנאמר \u0003\"שורך\"\u0004 למעט בכור אדם, ואף שיכול היה למעטו גם אם היה כתוב רק \"שור\", הוזכר בלשון \"שורך\" \u0003אטו\u0004 \u0005[משום]\u0006 \u0003\"צאנך\",\u0004 כדרכו של הכתוב. \u0003אלא לר' שמעון,\u0004 שלמד מ\"צאנך\" למעט פטר חמור, ולא למעט בכור של שותפות, אם כן ניתן לכתוב \"שור\" ו\"צאן\", \u0003\"שורך\" ו\"צאנך\" למה לי?\u0004 ומעירים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","ועוד באותו ענין \u0003אמר רבה:\u0004 אף שלדעת ר' שמעון, פטר חמור שלא נפדה מותר בהנאה, \u0003ומודה ר' שמעון לאחר עריפה,\u0004 שנאמר בו: \"ואם לא תפדה וערפתו\" (שמות יג, יג) — \u0003שהוא אסור\u0004 בהנאה.","\u0003מאי טעמא\u0004 \u0005[מה\u0006 ה\u0005טעם]?\u0006 היכן מקור הדברים בכתוב? \u0003גמר\u0004 \u0005[למד]\u0006 ר' שמעון בגזירה שווה \u0003עריפה עריפה מעגלה ערופה,\u0004 שכדין עגלה ערופה שנאמר בה לשון עריפה (דברים כא, ד), והיא אסורה מאותה שעה בהנאה, כן דין פטר חמור שמצוה לעורפו.","\u0003אמר רבא: מנא אמינא ליה\u0004 \u0005[מנין אני אומר אותה]\u0006 שכך סבור ר' שמעון? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003הערלה וכלאי הכרם, ו\u0004בשר \u0003שור הנסקל, ו\u0004בשר \u0003עגלה ערופה, ו\u0004בשר \u0003ציפורי מצורע, ו\u0004בשר \u0003פטר חמור, ובשר בחלב,\u0004 למרות שהם אסורים בהנאה, ואינם ראויים לאכילה — \u0003כולן מטמאין טומאת אוכלין.\u0004","\u0003ר' שמעון אומר: כולן אין מטמאין טומאת אוכלין.\u0004 \u0003ומודה ר' שמעון בבשר\u0004 שנתבשל \u0003בחלב שמטמא טומאת אוכלין,\u0004 למרות שהוא אסור בהנאה, \u0003הואיל והיתה לו\u0004 לבשר ולחלב \u0003שעת הכושר\u0004 ליטמא בטומאת אוכלים, שהיה ראוי לאכילה קודם שנתבשל.","\u0003ואמר ר' אסי אמר ר' יוחנן: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון,\u0004 שדבר האסור בהנאה אינו נטמא בטומאת אוכלים? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בענין טומאת אוכלים: \u0003\"מכל האכל אשר יאכל\u0004 וכו' יטמא\" (ויקרא יא, לד), והביטוי \"אשר יאכל\", שהוא מיותר לכאורה, בא ללמד כי רק \u0003אוכל שאתה יכול להאכילו לאחרים,\u0004 גם אם הוא אסור לך באכילה — \u0003קרוי אוכל\u0004 לענין זה, אבל דבר \u0003שאי אתה יכול להאכילו לאחרים\u0004 — \u0003אינו קרוי אוכל,\u0004 ואיסורי הנאה — אסור להאכילם גם לאחרים."],["ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שזה הוא טעמו של ר' שמעון, \u0003בשר בחלב,\u0004 שלדעת ר' שמעון מיטמא טומאת אוכלים, \u0003מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע ר' שמעון מנמק זאת בכך ש\u0003היתה לה שעת הכושר? תיפוק\u0004 \u0005[תצא,\u0006 תילמד\u0005]\u0006 \u0003לי\u0004 הלכה זו מן הטעם ש\u0003אוכל שאתה יכול להאכילו לאחרים הוא,\u0004 שהרי לדעת ר' שמעון בשר בחלב אינו אסור בהנאה,","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן יהודה אומר משום\u0004 (בשם) \u0003ר' שמעון: בשר בחלב אסור באכילה ומותר בהנאה, שנאמר\u0004 באיסור זה: \u0003\"כי עם קדוש אתה לה' אלהיך\u0004 לא תבשל גדי בחלב אמו\" (דברים יד, כא), \u0003ולהלן,\u0004 באיסור טריפה, הוא אומר: \"ואנשי קדש תהיון לי ובשר בשדה טריפה לא תאכלו\" (שמות כב, ל), ויש ללמוד בגזירה שווה: \u0003מה להלן,\u0004 בטריפה, שנאמר \"אנשי קודש\", \u0003אסור באכילה ומותר בהנאה, אף כאן\u0004 בבשר בחלב, שנאמר \"עם קדוש\" — \u0003אסור באכילה ומותר בהנאה!\u0004","ומשיבים: \u0003חדא ועוד קאמר\u0004 \u0005[\u0006טעם \u0005אחד ועוד\u0006 טעם נוסף \u0005הוא אומר],\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 — כפי שאמר ר' יוחנן, שבשר וחלב \u0003אוכל שאתה יכול להאכילו לאחרים הוא. ועוד,\u0004 שהרי \u0003לדידיה נמי\u0004 \u0005[ל\u0006ישראל \u0005עצמו גם כן]\u0006 הרי זה נחשב בכלל אוכל, ש\u0003הרי היתה לו שעת הכושר.\u0004 עד כאן נתבארה דעתו של ר' שמעון שהובאה בברייתא, שכל איסורי ההנאה שהזכיר התנא אינם מיטמאים בטומאת אוכלים, חוץ מבשר בחלב, מפני שהוא מותר בהנאה.","\u0003ואם איתא\u0004 \u0005[יש]\u0006 מקום לומר שגם \u0003לאחר עריפה שרי\u0004 \u0005[מתיר]\u0006 \u0003ר' שמעון\u0004 את פטר החמור בהנאה, \u0003ליתני\u0004 \u0005[שישנה]\u0006 התנא: \u0003ומודה ר' שמעון ב\u0004בשר \u0003פטר חמור ובשר בחלב שמטמאין טומאת אוכלין!\u0004 אלא מכאן שהוא מודה שפטר חמור אסור בהנאה לאחר עריפה, וכדברי רבה, ולכן אינו מיטמא.","ודוחים: מכאן אין הוכחה, שכך יש לומר: \u0003אי דחשיב עליה\u0004 \u0005[אם\u0006 במקרה \u0005שחושב עליו]\u0006 על פטר החמור, בשעת העריפה, שיאכלו ממנו אנשים — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 הריהו מיטמא טומאת אוכלים, לדעת ר' שמעון, לפי שאינו אסור בהנאה. ואולם \u0003הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 בברייתא זו, \u0005במה אנו עוסקים]\u0006 — במקרה \u0003דלא חשיב עליה\u0004 \u0005[שאינו חושב עליו]\u0006 לאכילה, ואינו נחשב לאוכל משום שאין אנשים רגילים לאכול בשר חמור.","ושואלים: \u0003ו\u0004אם מדובר כשלא חישב עליו לאכילה, \u0003טעמא מאי מטמאי רבנן\u0004 \u0005[מהו הטעם שמטמאים חכמים]\u0006 את בשר פטר החמור טומאת אוכלים? \u0003אמרוה רבנן קמיה\u0004 \u0005[אמרו חכמים לפני]\u0006 \u0003רב ששת\u0004 טעם לדבר: \u0003הואיל ואיסורו חישובו,\u0004 כלומר, האיסור על ישראל לאוכלו, הוא עצמו מחשיב אותו כאוכל.","ומקשים: \u0003ולרבנן מי אמר\u0004 \u0005[ול\u0006שיטת \u0005חכמים האם אומרים]\u0006 \u0003הואיל ואיסורו חישובו? והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003שלשה עשר דברים אמרו בנבלת עוף טהור,\u0004 \u0003וזו אחת מהן\u0004 — \u0003צריכה מחשבה\u0004 מפורשת שיאכלוה אנשים, כדי ליטמא טומאת אוכלים, שהרי אין אנשים רגילים לאכול נבלת עוף, \u0003ו\u0004אולם \u0003אינה צריכה הכשר,\u0004 כלומר, אין צורך שיפלו עליה מים תחילה כדי להכשירה לקבל טומאת אוכלים.","\u0003ואי\u0004 \u0005[ואם]\u0006 אומר אתה כי \u0003איסורו\u0004 של דבר הוא \u0003חישובו, למה לי מחשבה?\u0004 הרי נבילה אסורה באכילה! ומשיבים: \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — שיטת \u0003ר' שמעון היא,\u0004 והוא אינו סבור שאיסורו של דבר הוא חישובו.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממשנה אחרת: \u0003נבלת בהמה טמאה\u0004 (כגון סוסים וחמורים) \u0003בכל מקום\u0004 שהוא, \u0003ו\u0004כן \u0003נבלת עוף טהור, והחלב\u0004 (שומן) של נבלת בהמה טהורה, \u0003בכפרים,\u0004 שאין הגוים המצויים שם רגילים לאוכלם — \u0003צריכים מחשבה\u0004 להאכילם, כדי שייטמאו טומאת אוכלים, \u0003ואינם צריכים הכשר. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 \u0003איסורו חישובו, למה לי מחשבה?\u0004 הרי היא אסורה לישראל באכילה! ומשיבים: \u0003הא מני\u0004 \u0005[זו\u0006 גם כן כשיטת \u0005מי היא]\u0006 — שיטת \u0003ר' שמעון היא.\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת ממה ששנינו: \u0003נבלת בהמה טהורה בכל מקום, ונבלת עוף הטהור והחלב בשווקים,\u0004 כלומר, בערים גדולות שיש בהן שווקים, ויש שם אנשים האוכלים אותם — \u0003אינן צריכין מחשבה ולא הכשר\u0004 כדי שייטמאו טומאת אוכלים. ונדייק: דווקא נבלת בהמה טהורה אינה צריכה מחשבה, \u0003הא\u0004 \u0005[אבל]\u0006 נבלת בהמה \u0003טמאה בעיא\u0004 \u0005[צריכה]\u0006 \u0003מחשבה.\u0004 ואם איסורו חישובו למה לי מחשבה? והרי היא אסורה באכילה לישראל!","\u0003וכי תימא הא מני\u0004 \u0005[ואם תאמר\u0006 שגם משנה \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — שיטת \u0003ר' שמעון היא, הא מדסיפא\u0004 \u0005[הלוא מ\u0006תוך \u0005שסופה]\u0006 שיטת \u0003ר' שמעון הוי\u0004 \u0005[הוא],\u0006 \u0003רישא לאו\u0004 \u0005[תחילתה,\u0006 ששנויה בסתם, \u0005אינה]\u0006 כשיטת \u0003ר' שמעון. דקתני סיפא\u0004 \u0005[ש\u0006הרי \u0005הוא שונה בסוף],\u0006 \u0003ר' שמעון אומר: אף הגמל והארנבת והשפן והחזיר אינן צריכין לא מחשבה ולא הכשר\u0004 כדי ליטמא בטומאת אוכלים. \u0003ואמר ר' שמעון: מה טעם? הואיל ויש בהן\u0004 מקצת \u0003סימני טהרה\u0004 (ראה ויקרא יא, ד—ז). ואם כן לא ניתן להעמיד את מחלוקת ר' שמעון וחכמים בשאלה האם איסורו חישובו!","\u0003אלא אמר רבא: דכולי עלמא לא אמרינן\u0004 \u0005[לדעת הכל אין אנו אומרים]\u0006 \u0003איסורו חישובו,\u0004 וגם לדעת חכמים. \u0003ו\u0004בפטר חמור, \u0003אי דערפיה מיערף\u0004 \u0005[אם\u0006 במקרה ש\u0005ערף אותו]\u0006 — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 גם חכמים סבורים שאינו מיטמא טומאת אוכלים, מאחר שלא חישב עליו."],["\u0003הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 שנחלקו חכמים ור' שמעון, \u0005במה אנו עוסקים]?\u0006 \u0003כגון ששחטו\u0004 את פטר החמור כדי \u0003להתלמד בו\u0004 כיצד שוחטים, ולא על מנת לאוכלו. ונחלקו האם במקרה כעין זה אומרים אנו שאיסורו על ישראל הוא חישובו. \u0003ובפלוגתא\u0004 \u0005[ובמחלוקת]\u0006 של \u0003נימוס ור' אליעזר\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יוסי: סח\u0004 (אמר) \u0003לי נימוס, אחיו של ר' יהושע הגרסי, שהשוחט את העורב להתלמד בו\u0004 — \u0003דמו\u0004 של העורב \u0003מכשיר\u0004 אוכלים לקבל טומאה, שדם הוא אחד משבעת המשקים המכשירים לכך. ואילו \u0003ר' אליעזר אומר: דם שחיטה לעולם מכשיר.\u0004","ותוהים: \u0003ר' אליעזר היינו\u0004 \u0005[הרי זו]\u0006 שיטת \u0003תנא קמא\u0004 \u0005[התנא הראשון],\u0006 נימוס! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 בענין \u0003איסורו חישובו איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 ובכך נחלקו:","\u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 איסורו של עורב באכילה אינו מחשיבו כאוכל. ולפיכך, \u0003דמו\u0004 של עורב \u0003מכשיר לעלמא\u0004 \u0005[\u0006אוכלים \u0005בכלל],\u0006 לקבל טומאה. \u0003אבל לגופיה\u0004 \u0005[לגופו]\u0006 של העורב, להחשיב את בשרו כאוכל — אין די בכך, אלא, \u0003בעי\u0004 \u0005[צריך]\u0006 גם מחשבה מפורשת שיאכלוהו, שאין דרך אנשים לאכול בשר עורב.","\u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' אליעזר למימר\u0004 \u0005[לומר]:\u0006 \u0003דם שחיטה לעולם מכשיר, ו\u0004כוונתו ש\u0003אפילו לגופיה נמי לא בעי\u0004 \u0005[ל\u0006הכשיר \u0005את עצמו\u0006 לקבל טומאה \u0005גם כן אינו צריך]\u0006 מחשבה, משום שלדעתו איסורו מחשיבו. ובאותו אופן נחלקו ר' שמעון וחכמים בפטר חמור — כששחטו להתלמד, ולא כדי להאכילו, שלדעת ר' שמעון צריך מחשבה להאכילו כדי שייטמא טומאת אוכלים, ולכן בשרו טהור מטומאת אוכלים, ולדעת חכמים איסורו חישובו.","ודוחים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מניין] אתה אומר זאת? \u0003דילמא טעמא\u0004 \u0005[שמא הטעם]\u0006 של \u0003ר' אליעזר התם\u0004 \u0005[שם]\u0006 לגבי עורב, ששחיטה להתלמד מכשירה — אין זה משום שאיסורו חישובו, אלא משום \u0003דשאני\u0004 \u0005[ששונה]\u0006 \u0003עורב, הואיל ויש בו\u0004 מקצת \u0003סימני טהרה\u0004 של עוף טהור הראוי לאכילה. אבל חמור, שאין בו כלל סימני בהמה טהורה — אין בשחיטה להתלמד כדי להחשיבו כאוכל!","ומוסיפים: \u0003ומנלן\u0004 \u0005[ומנין לנו]\u0006 ש\u0003סימני טהרה מילתא היא\u0004 \u0005[דבר\u0006 של ממש \u0005הוא]\u0006 לענין טומאת אוכלים? \u0003דקתני עלה דההיא\u0004 \u0005[ששנינו\u0006 על המשנה \u0005ההיא],\u0006 שהובאה בעמוד הקודם, \u0003אמר ר' שמעון: מה טעם\u0004 גמל, ארנבת, שפן וחזיר, אינם צריכים מחשבה כדי להיטמא טומאת אוכלים, ולא הכשר? \u0003הואיל ויש בו סימני טהרה.\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 בשרו של עורב מקבל טומאה כאוכל \u0003משום סימני טהרה\u0004 שבו, \u0003מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע נחלקו ר' אליעזר וחכמים דווקא במקרה ששחטו \u0003להתלמד?\u0004 והלוא לדרך זו, \u0003אפילו\u0004 כששחטו \u0003להתעסק,\u0004 כלומר, כשלא נתכוון כלל לשוחטו, \u0003נמי\u0004 \u0005[גם כן]\u0006 סבור ר' אליעזר שבשרו מוכשר לקבל טומאה! ומשיבים: \u0003אין הכי נמי\u0004 \u0005[אכן, כך הוא גם כן]\u0006 לדעת ר' אליעזר, \u0003ו\u0004לא נחלקו במקרה זה אלא \u0003משום\u0004 דעתו של \u0003נימוס,\u0004 הסבור שאפילו במקרה ששחטו להתלמד אין בשר העורב מוכשר לקבל טומאה.","ועוד בשיטת רבה, שאמר כי גם לדעת ר' שמעון, פטר חמור לאחר עריפה — אסור בהנאה. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 לשיטת רבה, ממה ששנינו בברייתא: \u0003לא רצה לפדותו\u0004 את פטר החמור — \u0003עורפו בקופיץ\u0004 (סכין גדולה) \u0003מאחוריו\u0004 (בעורפו) וקוברו, ואסור בהנאה, אלו \u0003דברי ר' יהודה, ור' שמעון מתיר\u0004 בהנאה, ובניגוד לדברי רבה בדעת ר' שמעון!","ודוחים: \u0003אימא\u0004 \u0005[אמור]\u0006 ופרש את סוף הדברים כך: \u0003ומחיים אסור בהנאה,\u0004 אלו דברי רבי יהודה, \u0003ור' שמעון מתיר.\u0004 אבל לאחר עריפה — גם לדעת ר' שמעון אסור בהנאה.","ומקשים: \u0003והא מדסיפא\u0004 \u0005[והרי ממה שסופה,\u0006 המשכה של ברייתא זו\u0005]\u0006 באיסור הנאה \u0003מחיים הוי\u0004 \u0005[הוא\u0006 עוסק\u0005],\u0006 נלמד כי \u0003רישא\u0004 \u0005[תחילתה],\u0006 ממנה אנו רוצים להוכיח — \u0003לאו\u0004 \u0005[לא]\u0006 עוסק בהנאה \u0003מחיים.\u0004","\u0003דקתני סיפא\u0004 \u0005[ש\u0006כך הוא \u0005שונה בסוף]:\u0006 \u0003לא ימיתנו,\u0004 את פטר החמור, \u0003לא בקנה ולא במגל ולא בקרדום ולא במגירה\u0004 (משור), \u0003ולא יכניסנו לחדר וינעול דלת לפניו בשביל שימות\u0004 מרעב, שאין זו עריפה שציוותה התורה. \u0003ואסור בגיזה ועבודה,\u0004 אלו \u0003דברי ר' יהודה, ור' שמעון מתיר.\u0004 ואיסור גיזה ועבודה — איסור הנאה מחיים הוא!","ומשיבים: \u0003רישא וסיפא\u0004 \u0005[\u0006גם \u0005בתחילה\u0006 וגם \u0005בסוף]\u0006 מדובר באיסור הנאה \u0003מחיים,\u0004 אלא \u0003רישא\u0004 \u0005[\u0006ב\u0005תחילה]\u0006 מדובר \u0003בהנאת דמיו,\u0004 שאסור להשכירו או למוכרו, סיפא \u0005[\u0006ב\u0005סוף]\u0006 מדובר \u0003בהנאת גופו,\u0004 שאסור ליהנות ממנו עצמו, בגיזה ועבודה.","ומוסיפים: \u0003וצריכא\u0004 \u0005[וצריכה]\u0006 מחלוקת ר' יהודה ור' שמעון להיאמר בשני המקרים, \u0003דאי תנא\u0004 \u0005[שאם\u0006 היה \u0005שונה]\u0006 אותה רק ב\u0003הנאת דמיו,\u0004 הייתי אומר: \u0003בההוא קא שרי\u0004 \u0005[בזה מתיר]\u0006 \u0003ר' שמעון\u0004 ליהנות מפטר החמור, \u0003אבל בהנאת גופו אימא מודה ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לר' יהודה\u0004 שאסור. \u0003ואי תנא\u0004 \u0005[ואם\u0006 היה \u0005שונה]\u0006 \u0003בהנאת גופו,\u0004 הייתי אומר: \u0003בההיא קאסר\u0004 \u0005[בזו אוסר]\u0006 \u0003ר' יהודה, אבל בהנאת דמיו אימא\u0004 \u0005[אמור]\u0006 ש\u0003מודה לר' שמעון.\u0004 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמר המחלוקת בשני המקרים.","\u0003ו\u0004כשם שאמר רבה, \u0003כן אמר רב נחמן אמר רבה בר אבוה: מודה ר' שמעון\u0004 בפטר חמור \u0003לאחר עריפה שהוא אסור\u0004 בהנאה.","\u0003ואמר רב נחמן: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה]?\u0006 — \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 על האמור בפטר חמור \"ואם לא תפדה \u0003וערפתו\"\u0004 (שמות יג, יג): \u0003נאמר כאן\u0004 לשון \u0003עריפה, ונאמר להלן,\u0004 בעגלה ערופה, לשון \u0003עריפה\u0004 (דברים כא, ד), \u0003מה להלן אסור\u0004 ליהנות מעגלה ערופה לאחר עריפתה — \u0003אף כאן אסור\u0004 ליהנות מפטר חמור לאחר עריפה.","ונברר: \u0003מני\u0004 \u0005[\u0006כשיטת מי היא] ברייתא זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שיטת \u0003ר' יהודה\u0004 היא, הלוא לדעתו, פטר חמור כבר \u0003מחיים מיסר\u0004 \u0005[להיאסר]\u0006 \u0003אסור\u0004 בהנאה הוא, ומדוע נצרך הכתוב לחזור ולאוסרו! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 שיטת \u0003ר' שמעון היא?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ששת\u0004 לרב נחמן: \u0003ספרא חבריך\u0004 \u0005[חברך]\u0006 \u0003תרגומה\u0004 \u0005[תרגם,\u0006 הסביר \u0005אותה]\u0006 כך: \u0003לעולם\u0004 שיטת \u0003ר' יהודה\u0004 היא, האוסר פטר חמור מחיים, \u0003ו\u0004מכל מקום איצטריך \u0005[הוצרך]\u0006 הכתוב לאוסרו גם לאחר מיתה, שכן, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003עריפה במקום פדייה עומדת,\u0004 שנאמר: \"ואם לא תפדה וערפתו\", ולפיכך, \u0003מה פדייה מתרת\u0004 את פטר החמור בהנאה — \u0003אף עריפה מתרת,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב שאינה מתרת.","הוסיף ו\u0003אמר רב נחמן: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה],\u0006 שלדעת ר' שמעון פטר חמור אסור בהנאה לאחר עריפה? \u0003מדתני\u0004 \u0005[מ\u0006מה \u0005ששנה]\u0006 \u0003לוי\u0004 בברייתא, בטעם עריפת פטר החמור: \u0003הוא,\u0004 בעליו של פטר החמור, \u0003הפסיד ממונו של כהן,\u0004 שלא רצה לתת לו שה תחתיו — \u0003לפיכך יופסד ממונו.\u0004","ונברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 ברייתא זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כשיטת \u0003ר' יהודה\u0004 — \u0003הא מיפסד וקאי\u0004 \u0005[הלוא מופסד ועומד\u0006 הוא\u0005],\u0006 שהרי מחיים הוא אסור בהנאה! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 שיטת \u0003ר' שמעון היא?\u0004 ומכאן שלדעתו העריפה אוסרת את פטר החמור בהנאה על הבעלים!","ודוחים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 והסבר ברייתא זו לשיטת \u0003ר' יהודה, ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 לשיטת \u0003ר' שמעון,\u0004 אם הוא סבור שפטר חמור מותר בהנאה לאחר עריפה.","ומפרטים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 לשיטת \u0003ר' יהודה,\u0004 מדובר כאן \u0003אפסידא דביני ביני\u0004 \u0005[על ההפסד,\u0006 של ההפרש \u0005שבין זה לזה],\u0006 בין מחיר פטר החמור שנשאר בידו, אם היה פודה אותו, לבין מחיר השה שנותן בפדיונו לכהן, שהוא פחות ממנו.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור] ל\u0006שיטת \u0003ר' שמעון,\u0004 שכן למרות שהוא מתיר את פטר החמור לאחר עריפה, מכל מקום יש כאן הפסד של \u0003פחת מיתה,\u0004 שערכו של חמור שמת פחות בהרבה מערכו של חמור חי.","ומעירים: \u0003ו\u0004כדברי רבה ורב נחמן, \u0003כן אמר ריש לקיש: מודה ר' שמעון\u0004 בפטר חמור \u0003לאחר עריפה שהוא אסור\u0004 בהנאה. \u0003ו\u0004אילו \u0003ר' יוחנן, ואי תימא\u0004 \u0005[ואם תאמר,\u0006 יש אומרים\u0005]\u0006 ש\u0003ר' אלעזר אמר: עדיין היא מחלוקת.\u0004 כלומר גם לאחר מיתה חולק ר' שמעון על ר' יהודה, וסבור שפטר חמור מותר בהנאה.","ומעירים: \u0003איכא דמתני לה להא\u0004 \u0005[יש מי ששונה אותה לזו]\u0006 שאמר \u0003רב נחמן\u0004 בשיטת ר' שמעון, \u0003אהא\u0004 \u0005[על\u0006 משנה \u0005זו]\u0006 ששנינו: \u0003המקדש\u0004 אשה \u0003בפטר חמור\u0004 שנותן לה — \u0003אינה מקודשת,\u0004 שהרי הוא אסור בהנאה. ושאלו: \u0003לימא מתניתין\u0004 \u0005[האם לומר שמשנתנו\u0006 זו] ש\u0003לא כ\u0004דעת \u0003ר' שמעון?\u0004 שהרי לדעתו פטר חמור מותר בהנאה. \u0003אמר רב נחמן אמר רבה בר אבוה:\u0004 מדובר כאן \u0003לאחר עריפה, ודברי הכל\u0004 היא, שגם לדעת ר' שמעון פטר חמור לאחר עריפה אסור בהנאה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך דנו על משנה זו: \u0003הא מני\u0004 \u0005[זו,\u0006 כשיטת \u0005מי היא]?\u0006 \u0003לא\u0004 כשיטת \u0003ר' יהודה ולא\u0004 כשיטת \u0003ר' שמעון.\u0004 שכן \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' שמעון,\u0004 המתיר פטר חמור בהנאה — \u0003תיקדש בכוליה\u0004 \u0005[שתתקדש ב\u0006דמי \u0005כולו]!\u0006 \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' יהודה, ש\u0004פטר חמור \u0003אסור בהנאה\u0004 — \u0003תיקדש בהך דביני ביני\u0004 \u0005[תתקדש ב\u0006הפרש \u0005שיש בין זה לזה],\u0006 בין מחיר החמור שיישאר בידה לאחר פדיה, לבין מחיר השה שצריך לתת תחתיו לכהן!","\u0003אמר רבה בר אבוה אמר רב: לעולם\u0004 שיטת \u0003ר' יהודה\u0004 היא, \u0003וכגון ש\u0004פטר החמור \u0003אינו שוה אלא שקל,\u0004 כמחיר שה הראוי לפדיון, ונמצא שאין הפרש בין מחיר החמור ומחיר השה. ומוסיפים: \u0003וסבר לה\u0004 \u0005[ו\u0006ר' יהודה \u0005סבור]\u0006 \u0003כ\u0004דעת \u0003ר' יוסי בר יהודה,\u0004 שלא ניתן לפדות פטר חמור בשה ששווה פחות משקל. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 מה שנאמר לגבי פטר חמור \u0003\"תפדה\"\u0004 בא ללמדנו: \u0003תפדה מיד,\u0004 וכן \u0003תפדה כל שהוא,\u0004 בכל מחיר שהוא. \u0003ר' יוסי בר יהודה אומר: אין פדייה פחותה משקל.\u0004 ומפרשים ברייתא זו.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"תפדה\"\u0004 — \u0003תפדה מיד, תפדה כל שהוא.\u0004 ותמהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר!","משיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ואיתקש\u0004 \u0005[והוקש]\u0006 בכור בהמה טמאה \u0003לבכור אדם,\u0004 שנאמר: \"אך פדה תפדה את בכור האדם ואת בכור הבהמה הטמאה תפדה\" (במדבר יח, טו), אם כן יש ללמוד מזה על זה: \u0003מה בכור אדם\u0004 פודים אותו רק ל\u0003אחר שלשים\u0004 יום, \u0003ו\u0004נותן \u0003חמש\u0004 סלעים, כפי שנאמר מיד לאחר מכן: \"ופדויו מבן חודש תפדה כערך כסף חמשת שקלים\" (במדבר יח, טז), \u0003האי נמי\u0004 \u0005[זה גם כן],\u0006 פטר חמור — פודים אותו \u0003אחר שלשים, ו\u0004נותן שה בשווי \u0003חמש\u0004 סלעים לכהן, על כן","\u0003קא משמע לן\u0004 \u0005[משמיע לנו]:\u0006 \u0003תפדה מיד, תפדה כל שהוא.\u0004","ועוד שנינו בברייתא, \u0003ר' יוסי בר יהודה אומר: אין פדייה פחותה משקל.\u0004 ותוהים: דבר זה קשה \u0003ממה נפשך\u0004 \u0005[מאיזה צד שתרצה],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 הוא \u0003מקיש\u0004 (משווה) פטר חמור \u0003לבכור אדם\u0004 — \u0003חמש\u0004 סלעים \u0003ליבעי\u0004 \u0005[יצטרך]!\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 הוא \u0003לא מקיש\u0004 — ב\u0003שקל מנא ליה\u0004 \u0005[מנין לו]?\u0006","ומשיבים: \u0003לעולם\u0004 הוא \u0003לא מקיש.\u0004 ומה שהוא מצריך שקל, הרי זה כפי ש\u0003אמר רבא: אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין פדיה מיד ההקדש: \u0003\"וכל ערכך יהיה בשקל הקדש\"\u0004 (ויקרא כז, כה) — \u0003כל ערכין שאתה מעריך\u0004 לצורך פדיון, \u0003לא יהו פחותין משקל.\u0004","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 החולקים עליו סבורים: \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב\u0005]\u0006"],["\u0003בהשג יד כתיב\u0004 \u0005[נאמר],\u0006 במי שנודר ערכו של פלוני להקדש, ואין ידו משגת לתת כל ערכו, שאינו יוצא ידי חובה בפחות משקל. ולא לעניינים אחרים.","\u0003אמר רב נחמן: הלכה כדברי חכמים,\u0004 שפודים פטר חמור בשה כל שהוא, ואפילו בפחות משקל. ושואלים: \u0003וכמה?\u0004 מהו שיעורו? \u0003אמר רב יוסף: אפילו פטרוזא בר דנקא\u0004 \u0005[שה כחוש\u0006 ש\u0005שווה מעה\u0006 כסף\u0005].\u0006 \u0003אמר רבא: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 במשנתינו כן, שהשה שפודים בו יכול להיות \u0003גדול וקטן,\u0004 כדברי רב יוסף.","ושואלים על דברי רב יוסף: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, שפודים בשה כזה, שהרי שנינו בברייתא \"כל שהוא\"! ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 בשה ששוויו מועט \u0003כולי האי\u0004 \u0005[כל כך]\u0006 \u0003לא\u0004 יכול לפדות, \u0003אי נמי\u0004 \u0005[או גם כן],\u0006 היינו חושבים ש\u0003פטרוזא\u0004 \u0005[שה כחוש]\u0006 \u0003לא\u0004 יוכל לפדות בו, גם אם הוא שווה מעה, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 רב יוסף שאפילו בזה פודים.","מסופר, \u0003ר' יהודה נשיאה הוה ליה\u0004 \u0005[היה לו]\u0006 \u0003פטר חמור, שדריה לקמיה\u0004 \u0005[שלח אותו לפני]\u0006 \u0003ר' טרפון, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כמה בעינא למיתב\u0004 \u0005[צריך אני לתת]\u0006 \u0003לכהן\u0004 בפדיונו? מהו שוויו של השה שצריך לתת? \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003הרי אמרו\u0004 חכמים: הנותן ב\u0003עין יפה\u0004 — נותן שה \u0003ב\u0004שווי \u0003סלע\u0004, עין רעה — \u0003בשקל, בינונית\u0004 — \u0003ברגיא. אמר\u0004","\u0003רבא: הלכתא\u0004 \u0005[הלכה]\u0006 שצריך לתת שה\u0003ב\u0004שווי \u0003רגיא. וכמה\u0004 שיעורו? \u0003תלתא זוזי\u0004 \u0005[שלושה דינרים],\u0006 והוא קרוי \"רגיא\" על שם שהוא \u0003רגיל הכא\u0004 \u0003ורגיל הכא\u0004 \u0005[קרוב לכאן וקרוב לכאן],\u0006 שהוא ממוצע בין סלע ששוויו ארבעה דינרים, לבין שקל ששוויו שני דינרים.","ומעירים: \u0003קשיא הלכתא אהלכתא\u0004 \u0005[קשה הלכה\u0006 זו, שנותן שה בשלושה דינרים, \u0005על ההלכה\u0006 שאמר רב נחמן\u0005],\u0006 שיכול לתת אפילו שה כל שהוא! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה],\u0006 \u0003כאן\u0004 — \u0003בבא לימלך\u0004 (לשאול), אומרים לו לתת שלושה דינרים, \u0003כאן\u0004 — \u0003בעושה מעצמו,\u0004 שאם נתן שה שווה אפילו מעה — יצא ידי חובה, ואין מחייבים אותו ליתן ביותר.","\u0003אמר ר' יצחק אמר ריש לקיש: מי שיש לו פטר חמור ואין לו שה לפדותו\u0004 — \u0003פודהו בשויו\u0004 של פטר החמור. ושואלים: \u0003למאן\u0004 \u0005[ל\u0006שיטת \u0005מי]\u0006 נאמרו הדברים? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה\u0004 — \u0003הא אמר\u0004 \u0005[הרי\u0006 הוא \u0005אומר]:\u0006 \u0003הקפידה עליו תורה\u0004 לפדותו דווקא \u0003בשה! אלא\u0004 נאמר הדבר \u0003ל\u0004שיטת \u0003ר' שמעון.\u0004","ומעירים: \u0003רב אחא מתני הכי\u0004 \u0005[\u0006היה שונה כך], שדברי ריש לקיש נאמרו דווקא כשיטת ר' שמעון. \u0003רבינא קשיא ליה\u0004 \u0005[קשה היה לו]\u0006 בהסבר זה: והרי בכל מקום בו נחלקים \u0003ר' יהודה ור' שמעון\u0004 — \u0003הלכה כר' יהודה! ו\u0004עוד, הרי","\u0003סתם לן\u0004 \u0005[סותם לנו]\u0006 ה\u0003תנא\u0004 במשנה \u0003כ\u0004שיטת \u0003ר' יהודה, ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 שריש לקיש פוסק \u0003הלכה כר' שמעון?\u0004","\u0003אלא,\u0004 דברי ריש לקיש נאמרו \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כשיטת \u0003ר' יהודה,\u0004 שכן \u0003לא\u0004 ייתכן ש\u0003יהא\u0004 דינו של פטר חמור \u0003חמור מן ההקדש,\u0004 שהפודה בהמה מיד ההקדש — פודה אותה בשוויה. \u0003ולא אמרה תורה\u0004 לפדות פטר חמור \u0003בשה\u0004 על מנת \u0003להחמיר עליו,\u0004 אלא כדי \u0003להקל עליו,\u0004 שלא יהא צריך לפדותו בשוויו. מסופר, \u0003רב נחמן בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף פריק ליה בשילקי\u0004 \u0005[\u0006היה \u0005פודה אותו,\u0006 את פטר החמור, \u0005בשלקות,\u0006 עשבים מבושלים\u0005]\u0006 \u0003בשוויו.\u0004","\u0003אמר רב שיזבי אמר רב הונא: הפודה פטר חמור של חבירו\u0004 — \u0003פדיונו\u0004 (פטר החמור) \u0003פדוי,\u0004 למרות שלא פדוהו הבעלים. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 שאלה לחכמים\u0005]:\u0006 האם במקרה זה \u0003פדיונו\u0004 (פטר החמור) שייך \u0003לפודה, או דלמא\u0004 \u0005[שמא]\u0006 \u0003פדיונו לבעלים?\u0004","ואומרים: \u0003אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003ר' שמעון לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך, כיון\u0004 ש\u0003אמר\u0004 שקודם פדיון הריהו \u0003מותר בהנאה\u0004 לבעליו, שיכול לעבוד בו ולהשכיר אותו — הרי \u0003ממונא\u0004 \u0005[ממון]\u0006 של ה\u0003בעלים הוא,\u0004 ונתינת שה לכהן — אין בכוחה להוציא את החמור מיד בעליו. \u0003כי תיבעי\u0004 \u0005[כאשר תישאל\u0006 השאלה] הרי זה \u0003אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003ר' יהודה,\u0004 ש\u0003אמר\u0004 שפטר חמור \u0003אסור בהנאה\u0004 קודם פדייה, ואם כן, אינו שלו מתחילה, ורק על ידי הפדייה בשה הריהו זוכה בו.","וכך יש לשאול: האם \u0003להקדש מדמי ליה\u0004 \u0005[\u0006הוא \u0005מדמה אותו],\u0006 את פטר החמור, \u0003ורחמנא אמר\u0004 \u0005[והתורה אמרה]\u0006 בפדיון מן ההקדש: \u0003\"ונתן הכסף וקם לו\"\u0004 (ראה ויקרא כז, יט), ומשמע: מי שנותן את הכסף, גם אם לא הוא הקדיש את הדבר, הריהו זוכה בו. \u0003או דלמא\u0004 \u0005[שמא],\u0006 \u0003כיון\u0004 שהבעלים יכול לפדות את פטר החמור בשה, ששוויו פחות מחמור, נמצא \u0003דקני להו בביני וביני\u0004 \u0005[שיש לו קנין\u0006 בחמור, \u0005ב\u0006הפרש \u0005שבין זה לזה],\u0006 ולכן \u0003לא דמי\u0004 \u0005[אינו דומה]\u0006 \u0003להקדש,\u0004 שאין בו כלל קנין למקדיש?","\u0003אמר רב נחמן, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא: \u0003הגונב פטר חמור של חבירו\u0004 קודם שנפדה, ונתפס — \u0003משלם תשלומי כפל לבעלים. ואף על פי שאין לו\u0004 לבעלים \u0003עכשיו\u0004 זכות בו — \u0003יש לו לאחר מכאן,\u0004 לאחר שיפדהו.","ונברר: \u0003מני\u0004 \u0005[\u0006כשיטת מי היא] ברייתא זו? \u0003אילימא\u0004 \u0005[אם תאמר\u0006 כשיטת\u0005]\u0006 \u0003ר' שמעון, אמאי\u0004 \u0005[מדוע]\u0006 \u0003אין לו עכשיו?\u0004 הרי לשיטתו פטר חמור מותר בהנאה לבעליו, ואם כן ממונו הוא! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, ששיטת \u0003ר' יהודה\u0004 היא, האוסר את פטר החמור בהנאה קודם שנפדה.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 ש\u0003להקדש מדמינן ליה\u0004 \u0005[אנו מדמים אותו],\u0006 שנותנים לפטר החמור דין הקדש — מדוע משלם תשלומי כפל? הלוא \u0003\"וגנב מבית האיש\"\u0004 (שמות כב, ו), \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ומדייקים מכאן: \u0003ולא מבית הקדש,\u0004 שהגונב מן ההקדש אינו משלם תשלומי כפל! ומכאן שאין לפטר החמור דין הקדש, ולכן גם אם פדאו אדם אחר — הריהו של הבעלים. ומוסיפים: \u0003ותו לא מידי\u0004 \u0005[ואין\u0006 להוסיף \u0005עוד דבר]\u0006 בענין זה, שהוכחה ברורה היא.","שנינו במשנה: היו לו שתי חמורות, \u0003אחת ביכרה ואחת שלא ביכרה,\u0004 וילדו זכר ונקיבה ואין ידוע איזו ילדה זכר — הרי זה מפריש שה מספק, שמא זו שלא ביכרה ילדה זכר, והשה נשאר ביד הבעלים. ועוד שנינו לגבי השה שפדו בו את פטר החמור, שהוא נכנס לדיר יחד עם שאר הצאן כדי להתעשר מעשר בהמה. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003כיצד,\u0004 באיזה מקרה, \u0003אמרו\u0004 חכמים על פדיון פטר חמור שהוא \u0003נכנס לדיר להתעשר?\u0004","\u0003אי\u0004 (אין) \u0003אתה יכול לומר\u0004 שמדובר פה \u0003ב\u0004שה שכבר \u0003בא ליד כהן, שהרי שנינו: הלקוח\u0004 (הקנוי) \u0003ושניתן לו במתנה\u0004 — \u0003פטור ממעשר בהמה,\u0004 ושה זה הרי ניתן במתנה לכהן. \u0003אלא\u0004 צריך לומר שמדובר \u0003בישראל שהיו לו עשרה ספק פטרי חמורים בתוך ביתו, שמפריש עליהן\u0004 מספק \u0003עשרה שיין\u0004 כדי לפדותם, ומעשרן, צריך לעשר את אותם שיים, \u0003והן שלו.\u0004","ומעירים: מה ששנינו בברייתא זו \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לרב נחמן,\u0004 ש\u0003אמר רב נחמן אמר רבה בר אבוה: ישראל שהיו לו עשרה ספק פטרי חמורים\u0004 — \u0003מפריש עליהן עשרה שיין, ומעשרן, והן שלו.\u0004","ועוד \u0003אמר רב נחמן אמר רבה בר אבוה: ישראל שהיו לו עשרה פטרי חמורים ודאין בתוך ביתו, שנפלו\u0004 לו בירושה \u0003מבית אבי אמו\u0004 שהיה \u0003כהן,\u0004 שפטור מפדיון פטר חמור, \u0003ואותו אבי אמו כהן נפלו לו\u0004 פטרי חמורים אלה בירושה \u0003מבית אבי אמו\u0004 שהיה \u0003ישראל.\u0004 במקרה זה, כבר נתחייבו פטרי החמורים בפדיון, וצריך היה הכהן לפדותם בשיים, אלא שרשאי היה ליטול אותם לעצמו.","ולכן, נכדו הישראל, היורש את זכותו בפטרי חמורים אלה, \u0003מפריש עליהן עשרה שיין, ומעשרן, והן שלו,\u0004 כאילו הפרישם סבו הכהן, והוריש לו אותם.","\u0003ו\u0004כיוצא בזה \u0003אמר רב נחמן אמר רבה בר אבוה: ישראל שהיו לו טבלים ממורחין בתוך ביתו,\u0004 כלומר, פירות שאינם מעושרים, שנגמרה מלאכתם וכבר נתחייבו בתרומה ובמעשר, והיו אלו טבלים \u0003שנפלו\u0004 לו בירושה \u0003מבית אבי אמו כהן, ואותו אבי אמו כהן נפלו לו\u0004 טבלים אלה \u0003מבית אבי אמו ישראל\u0004 — \u0003מעשרן,\u0004 מפריש מהם תרומות ומעשרות, \u0003ו\u0004פירות התרומה והמעשר הראשון שהפריש \u0003הן שלו,\u0004 כאילו עישר סבו הכהן טבלים אלה, וכבר זכה בהם, והוריש לו אותם.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 היה רב נחמן לומר שני דינים אלו, גם בפטרי חמורים וגם בטבלים, מפני \u0003דאי אשמועינן קמייתא\u0004 \u0005[שאם היה משמיע לנו\u0006 את \u0005הראשונה],\u0006 בפטרי חמורים, היינו אומרים: דווקא שם נחשב הדבר כאילו זכה בהם סבו הכהן, \u0003משום דקא מפריש וקאי\u0004 \u0005[ש\u0006השה \u0005מופרש ועומד]\u0006 כלומר, לא צריך היה לעשות מעשה של הפרשה, ודי שיאמר על שה שלו שהוא תחת פטר החמור, והרי הוא שלו.","\u0003אבל הכא\u0004 \u0005[כאן],\u0006 לגבי טבלים — הרי צריך להפריש את התרומה מן הטבל כדי שתיקרא בשם תרומה ויוכל הכהן לזכות בה, ויש לומר כי \u0003מתנות כהונה שלא הורמו\u0004 מן התבואה — \u0003כמי שלא הורמו דמיין\u0004 \u0005[נחשבות],\u0006 ואם כן \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 נחשב הדבר כאילו זכה סבו הכהן בתרומה.","\u0003ו\u0004מן הצד השני, \u0003אי אשמועינן הכא\u0004 \u0005[אם היה משמיע לנו כאן],\u0006 לענין טבלים, שנחשב הדבר כאילו זכה סבו הכהן בתרומה, הייתי אומר כי אין זה אלא משום ש\u0003אפשר לעשורי מיניה וביה\u0004 \u0005[לעשר\u0006 את הטבל \u0005ממנו ובו],\u0006 \u0003דהא מנח\u0004 \u0005[שהרי\u0006 הכל \u0005מונח]\u0006 יחד, הטבל והתרומה שבו. \u0003אבל התם\u0004 \u0005[שם],\u0006 לענין פטר חמור, \u0003כיון דשה מעלמא בעי אתויי\u0004 \u0005[ששה מהחוץ צריך להביא]\u0006 כדי לפדותו, \u0003ו\u0004לומר שהשה כבר \u0003מפריש וקאי\u0004 \u0005[מופרש ועומד]\u0006 ואינו צריך הפרשה \u0003אימא לא\u0004 \u0005[אמור שאין\u0006 אנו אומרים\u0005],\u0006 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני הדברים.","אגב כך מביאים הלכה דומה, \u0003אמר ר' שמואל בר נתן אמר ר' חנינא: הלוקח טבלים\u0004"],["\u0003ממורחין מן הגוי\u0004 — \u0003מעשרן והן שלו,\u0004 שאינו צריך לתת את התרומה והמעשרות שהפריש.","ושואלים: \u0003דמרחינהו מאן\u0004 \u0005[שמירח אותם מי]?\u0006 \u0003אילימא דמרחינהו\u0004 \u0005[אם תאמר שמירח אותם]\u0006 \u0003גוי\u0004 — הלוא \u0003\"דגנך\" אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 לגבי תרומות ומעשרות (ראה דברים יב, יז. דברים יח, ד), כלומר, דווקא מה שאתה עושה אותו לדגן, שנגמרה מלאכתו ונתמרח על ידך, חייב במעשרות, \u0003ולא דגן גוי!\u0004","\u0003אלא דמרחינהו\u0004 \u0005[שמירח אותם]\u0006 \u0003ישראל מרשות גוי,\u0004 כלומר, כשהיו ברשות הגוי, ולאחר מכן קנה אותם הישראל מידו. ולפיכך \u0003מעשרן\u0004 — מפני ש\u0003אין קנין לגוי בארץ ישראל להפקיע\u0004 את התבואה \u0003מיד מעשר,\u0004 והרי נתמרחו על ידי ישראל. \u0003ו\u0004מכל מקום \u0003הן שלו\u0004 — מפני \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 לכהן: \u0003קאתינא מכח גברא דלא מצית אישתעיה דינא בהדיה\u0004 \u0005[אני בא מכוחו של אדם שאין אתה יכול להתדיין איתו],\u0006 שהרי הגוי אינו חייב לתת תרומות ומעשרות לכהן, ומידו קניתי את התבואה. ומביאים דיון שהוזכרו בו דברים אלו, בענין לוקח טבלים ממורחים מן הגוי.","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006] במשנה במסכת דמאי: \u0003המפקיד פירותיו אצל הכותי\u0004 (שומרוני) או \u0003אצל עם הארץ,\u0004 והחזירו לו — הרי הם \u0003בחזקתן למעשר ולשביעית,\u0004 שאין לחשוש שמא החליפם, והחזיר לו פירות שאינם מעושרים, או שמא פירות שביעית הם, שצריכים ביעור.","אבל המפקיד \u0003אצל הגוי\u0004 — הרי הם \u0003כפירותיו\u0004 של הגוי, שבוודאי החליפם. \u0003ר' שמעון אומר: דמאי,\u0004 כלומר, ספק אם הם מעושרים, שמא לא החליפם.","\u0003אמר ר' אלעזר: להפריש\u0004 תרומות ומעשרות ממה שהחזיר לו הגוי — \u0003כולי עלמא לא פליגי\u0004 \u0005[כולם אינם חלוקים],\u0006 וגם ר' שמעון מודה שצריך להפריש, כדי לצאת מידי ספק איסור. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה לענין \u0003ליתנן לכהן\u0004 לאחר ההפרשה. \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 \u0003ודאי חלפינהו\u0004 \u0005[החליף אותם]\u0006 הגוי, את הפירות שהופקדו אצלו, \u0003ובעי מיתננהו\u0004 \u0005[וצריך לתת אותם]\u0006 את התרומה \u0003לכהן. ור' שמעון סבר\u0004 \u0005[סבור]:\u0006 \u0003דמאי,\u0004 כלומר, ספק הוא, והכהן צריך להביא ראיה כדי להוציא מידיו את התרומה.","מסופר, \u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רב דימי וקאמר להא שמעתא\u0004 \u0005[ואומר את ההלכה הזו],\u0006 שאמר ר' אלעזר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: לדרך זו, \u0003טעמא\u0004 \u0005[טעם\u0006 הדבר\u0005]\u0006 שר' שמעון חולק, הרי זה משום \u0003דמספקא לן אי חלפינהו אי לא חלפינהו\u0004 \u0005[שמסופק לנו אם החליף אותם הגוי או לא החליף אותם],\u0006 \u0003הא\u0004 \u0005[אבל]\u0006 אם \u0003ודאי חלפינהו\u0004 \u0005[החליף אותם]\u0006 — \u0003דכולי עלמא בעי למיתבינהו לכהן\u0004 \u0005[לדעת הכל צריך לתת אותם לכהן],\u0006 את פירות התרומה שמפריש מהם. ומדוע? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' שמואל אמר ר' חנינא: הלוקח טבלים מן הגוי,\u0004 אם היו \u0003ממורחין\u0004 — \u0003מעשרן, ו\u0004אולם \u0003הן שלו,\u0004 ואינו צריך ליתנם לכהן!","אמר לו רב דימי: \u0003דלמא\u0004 \u0005[שמא]\u0006 יש לחלק, \u0003כאן\u0004 ששנינו במשנה שצריך לתת לכהן — מדובר \u0003בתרומה גדולה, כאן,\u0004 שאמר ר' חנינא שמעשרן והן שלו — מדובר \u0003בתרומת מעשר\u0004 (תרומה שמקבל הכהן מן המעשר הראשון הניתן ללוי).","אמר לו אביי: \u0003אזכרתן מילתא\u0004 \u0005[הזכרת לי דבר]\u0006 ש\u0003אמר ר' יהושע בן לוי: מנין ללוקח טבלים ממורחין מן הגוי שהוא פטור מתרומת מעשר? שנאמר: \"ואל הלוים תדבר ואמרת אליהם כי תקחו מאת בני ישראל\u0004 את המעשר וכו' והרמותם ממנו תרומת ה' מעשר מן המעשר\" (במדבר יח, כו), ויש לדייק: \u0003טבלים שאתה לוקח מבני ישראל\u0004 — \u0003אתה מפריש מהן תרומת מעשר ונותנה לכהן, טבלים שאתה לוקח מן הגוי\u0004 — \u0003אי\u0004 (אין) \u0003אתה מפריש מהן תרומת מעשר ונותנה לכהן.\u0004","שנינו במשנה בענין שה שפודים בו את פטר החמור: \u0003ואם מת נהנים בו.\u0004 ושואלים: \u0003דמית היכא\u0004 \u0005[שמת היכן]?\u0006 \u0003אילימא דמית בי כהן\u0004 \u0005[אם תאמר שמת בבית הכהן],\u0006 \u0003ו\u0004הכוונה היא ש\u0003נהנה בו\u0004 ה\u0003כהן\u0004 — \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, שהרי \u0003ממונא דידיה\u0004 \u0005[ממון שלו]\u0006 \u0003הוא! אלא,\u0004 תאמר שמדובר במקרה \u0003דמית בי\u0004 \u0005[שמת בבית]\u0006 ה\u0003בעלים,\u0004 קודם שהספיק ליתנו לכהן, \u0003ו\u0004ללמד ש\u0003נהנה בו כהן\u0004 — \u0003הא נמי פשיטא\u0004 \u0005[זה גם כן פשוט]!\u0006","ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר],\u0006 כי \u0003כל כמה דלא מטא לידיה לא זכה ביה\u0004 \u0005[כל עוד שלא הגיע לידו\u0006 של הכהן \u0005לא זכה בו],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 \u0003דמעידנא דאפרשיה, ברשותיה דכהן קאי\u0004 \u0005[מזמן שהפריש אותו, ברשותו של הכהן הוא עומד],\u0006 ולפיכך, אם מת — נבלתו שייכת לכהן."],["\u0003אין פודין\u0004 פטר חמור אלא בשה, מן הכבשים או מן העיזים, אבל \u0003לא בעגל ולא בחיה.\u0004 ואין פודים אלא בשה חי, אבל \u0003לא בשחוטה, ו\u0004גם \u0003לא בטריפה,\u0004 שיש לה מכה או מחלה, והיא עתידה למות כתוצאה מכך. \u0003ולא\u0004 פודים \u0003בכלאים,\u0004 בשה שהוא הכלאה של כבש ועז, \u0003ולא בכוי,\u0004 בעל חיים שהוא ספק בהמה ספק חיה. \u0003ור' אליעזר מתיר\u0004 לפדותו \u0003בכלאים\u0004 — \u0003מפני שהוא שה, ואוסר בכוי\u0004 — \u0003מפני שהוא ספק.\u0004 אם \u0003נתנו,\u0004 את פטר החמור עצמו, \u0003לכהן\u0004 — \u0003אין הכהן רשאי לקיימו עד שיפריש שה תחתיו\u0004 לפדיון.","בענין ששנינו שאין פודים בעגל וכו', אומרים: \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003בן בג בג היא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003בן בג בג אומר: נאמר כאן\u0004 בפדיון פטר חמור: \"ופטר חמור תפדה ב\u0003שה\"\u0004 (שמות יג, ג), \u0003ונאמר להלן\u0004 לגבי קרבן הפסח: \u0003\"שה\"\u0004 (שמות יב, ג), \u0003מה להלן\u0004 — \u0003פרט לכל השמות הללו,\u0004 עגל וכו', שהם פסולים לקרבן הפסח, \u0003אף כאן,\u0004 לגבי פדיון פטר חמור — \u0003פרט לכל השמות הללו.\u0004","ויש לשאול: \u0003אי\u0004 (אם) מן הפסח אתה למד, אמור גם: \u0003מה להלן,\u0004 בפסח, אינו אלא \u0003זכר תמים ובן שנה\u0004 (שמות יב, ה), \u0003אף כאן\u0004 צריך השה להיות דווקא \u0003זכר תמים ובן שנה! תלמוד לומר: \"תפדה\" \"תפדה\",\u0004 שפעמיים חזר הכתוב על הציווי \"ופטר חמור תפדה בשה\" (שמות יג, ג. שמות לד, כ), ובכך \u0003ריבה\u0004 גם נקיבה, בעל מום, וגדול מבן שנה.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 לשון \u0003\"תפדה\" \"תפדה\" ריבה, אפילו כל הני\u0004 \u0005[אלה]\u0006 ששנינו שאין פודים בהם \u0003נמי\u0004 \u0005[גם כן]!\u0006 ומשיבים: \u0003אם כן,\u0004 הלימוד \u0003\"שה\" \"שה\"\u0004 מן הפסח, שבא למעט דבר אחר, \u0003מאי אהני ליה\u0004 \u0005[מה הועיל לו]?\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 שאלה לחכמים]: \u0003מהו לפדות\u0004 פטר חמור \u0003ב\u0004שה שהוא \u0003בן פקועה,\u0004 כלומר, בולד חי שנמצא במעי בהמה שנשחטה? ומפרטים: \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' מאיר לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה, ש\u0003כיון\u0004 ש\u0003אמר ר' מאיר: בן פקועה טעון שחיטה,\u0004 אם כן \u0003שה מעליא\u0004 \u0005[מעולה,\u0006 גמור\u0005]\u0006 \u0003הוא,\u0004 ופודים בו. \u0003אלא כי תבעי לך אליבא דרבנן\u0004 \u0005[כאשר תישאל לך\u0006 השאלה הרי זה \u0005לפי שיטת חכמים],\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 ש\u0003שחיטת אמו מטהרתו\u0004 ואינו צריך שחיטה, לפי שהוא נחשב כחלק מגופה של אמו.","וכך יש לשאול: האם \u0003כבישרא בדיקולא דמי\u0004 \u0005[כבשר\u0006 המונח בקלחת הוא נחשב], כאילו נשחט, ואם כן הרי זה בכלל האיסור לפדות בשחוטה. \u0003או דלמא\u0004 \u0005[שמא]:\u0006 \u0003כיון דהשתא מיהא רהיט ואזיל\u0004 \u0005[שעכשיו על כל פנים הוא רץ והולך]\u0006 \u0003\"שה\" קרינא ביה\u0004 \u0005[אנחנו קוראים לו]?\u0006","ונחלקו חכמים בדבר זה, \u0003מר זוטרא אמר: אין פודין\u0004 בבן פקועה, \u0003ורב אשי אמר: פודין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי למר זוטרא: מאי דעתיך\u0004 \u0005[מה דעתך]\u0006 שאתה אומר שאין פודים בבן פקועה — משום \u0003דילפת\u0004 \u0005[שאתה לומד]\u0006 \u0003מפסח,\u0004 ובן פקועה פסול לקרבן פסח. \u0003אי\u0004 \u0005[אם כן]\u0006 שמפסח אתה למד, אמור גם: \u0003מה להלן\u0004 בפסח אינו אלא \u0003זכר תמים ובן שנה, אף כאן\u0004 יצטרכו לפדות ב\u0003זכר תמים ובן שנה!\u0004 אמר לו: הציווי הכפול \u0003\"תפדה\" \"תפדה\"\u0004 (שמות יג, יג. שמות לד, כ) \u0003ריבה\u0004 גם מה שאינו זכר תמים ובן שנה.","אמר לו: \u0003אי\u0004 \u0005[אם]\u0006 \u0003\"תפדה\" \"תפדה\" ריבה, אפילו בן פקועה נמי\u0004 \u0005[גם כן]!\u0006 אמר לו: \u0003אם כן, \"שה\" \"שה\" מאי אהני ליה\u0004 \u0005[מה הועיל לו]?\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 שאלה לחכמים: \u0003מהו לפדות\u0004 פטר חמור \u0003ב\u0004שה שהוא \u0003נדמה\u0004 לבעל חיים אחר, כגון ברחל שילדה ולד הנראה כמין עז (למרות שגם אביו כבש)? ומוסיפים: \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' אליעזר\u0004 במשנתינו \u0003לא תיבעי\u0004 \u0005[תסתפק]\u0006 \u0003לך,\u0004 שכן השתא \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003בכלאים,\u0004 שאביו תיש ואמו רחל, פרקינן \u0005[אנחנו פודים],\u0006 אם כן \u0003ב\u0004כבש שאינו כלאיים, אלא רק \u0003נדמה\u0004 לעז, \u0003מיבעיא\u0004 \u0005[נצרכה לומר]\u0006 שפודים?","\u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה, הרי זה \u0003אליבא דרבנן\u0004 \u0005[לפי שיטת חכמים]\u0006 הסבורים שאין פודים פטר חמור בכלאיים. וכך יש לשאול: האם דווקא \u0003בכלאים הוא דלא פרקינן\u0004 \u0005[שאין אנו פודים],\u0006 אבל \u0003בנדמה פרקינן\u0004 \u0005[פודים אנו].\u0006 \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה]?\u0006","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בברייתא: \u0003פרה שילדה מין עז\u0004 — \u0003אין פודין\u0004 בו. ונדייק מכאן: דווקא כשנולד לפרה אין פודים בו, \u0003הא\u0004 \u0005[אבל]\u0006 \u0003רחל שילדה מין עז\u0004 — \u0003פודין.\u0004 ויש לשאול: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 ברייתא זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שיטת \u0003ר' אליעזר\u0004 — לשם מה הוא זקוק לומר זאת? \u0003הא\u0004 \u0005[הרי]\u0006 לשיטתו, אפילו \u0003בכלאים\u0004 של רחל ותיש \u0003נמי פרקינן\u0004 \u0005[גם כן אנחנו פודים],\u0006 וכל שכן כשאינו ממש כלאיים! \u0003אלא לאו רבנן\u0004 \u0005[\u0006האם \u0005לא\u0006 שיטת \u0005חכמים]\u0006 \u0003היא?\u0004 ומכאן שאף לדעתם פודים בנדמה!","ודוחים: \u0003לא, לעולם\u0004 אמור כי ברייתא זו שיטת \u0003ר' אליעזר\u0004 היא, ולא באה ללמדנו שפודים ברחל שילדה כמין עז, אלא \u0003היא גופה קא משמע לן\u0004 \u0005[\u0006הלכה \u0005זו עצמה משמיע לנו]\u0006 ש\u0003פרה שילדה מין עז\u0004 — \u0003אין פודין\u0004 בו. ש\u0003לא תימא\u0004 \u0005[תאמר]:\u0006 \u0003זיל אבתריה דידיה\u0004 \u0005[לך אחריו עצמו],\u0006 אחרי הולד — \u0003והאי\u0004 \u0005[וזה]\u0006 \u0003עז מעליא\u0004 \u0005[מעולה]\u0006 \u0003הוא,\u0004 וכשר לפדיון. \u0003אלא\u0004 להיפך, \u0003זיל בתר אימיה\u0004 \u0005[לך אחרי אמו]\u0006 — \u0003והאי\u0004 \u0005[וזה]\u0006 \u0003עגל הוא\u0004 ואינו ראוי לפדות בו.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מברייתא \u0003דתני\u0004 \u0005[ששנה\u0006\u0005]\u0006 \u0003רבה בר שמואל: איזהו כלאים\u0004 — \u0003רחל שילדה מין עז, ואביו שה,\u0004 כלומר, ממין הכבשים, ולא ממין העזים. ויש לתמוה: במקרה ש\u0003אביו שה\u0004האם \u0003כלאים הוא?\u0004 הרי \u0003נדמה הוא! אלא\u0004 יש להבין כך: \u0003איזהו\u0004 בעל חיים \u0003דמי\u0004 \u0005[הדומה]\u0006 \u0003לכלאים, דשויוה רבנן\u0004 \u0005[שעשו\u0006 אותו \u0005חכמים]\u0006 \u0003כי\u0004 \u0005[כמו]\u0006 \u0003כלאים,\u0004 שהוא פסול — \u0003רחל שילדה מין עז ואביו שה.\u0004 ומעתה יש לשאול: \u0003למאי\u0004 \u0005[למה],\u0006 לאיזה ענין מדובר?","\u0003אי\u0004 \u0005[אם]\u0006 \u0003לקדשים\u0004 לפוסלו לקרבן — מה מקום לתלות את דינו בכלאיים? והרי \u0003מהיכא\u0004 \u0005[מהיכן,\u0006 מאותו מקום\u0005]\u0006 ש\u0003ממעט\u0004 הכתוב \u0003כלאים\u0004 מהקרבה — \u0003מהתם\u0004 \u0005[משם,\u0006 מאותו מקום] \u0003ממעט\u0004 גם \u0003נדמה. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר: \"שור או כשב או עז כי יוולד וכו' ירצה לקרבן לה' \" (ויקרא כב, כז), ודרשו חכמים: \u0003\"שור או כשב\"\u0004 — \u0003פרט לכלאים, \"או עז\"\u0004 — \u0003פרט לנדמה!\u0004","\u0003אי\u0004 \u0005[אם]\u0006 תאמר שנשנתה ברייתא זו \u0003ל\u0004עניין \u0003בכור,\u0004 ללמד שנדמה אינו קדוש בבכורה — כבר למדנו דין זה מן הכתוב, שהרי \u0003\"אך בכור שור\"\u0004 (במדבר יח, יז) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 — \u0003עד שיהא הוא שור ובכורו שור,\u0004 ולא כשהוא נראה כבעל חיים אחר!","\u0003אלא\u0004 תאמר שלענין \u0003מעשר\u0004 בהמה נאמר, שנדמה אינו נכנס לדיר להתעשר — גם לכך לא הוצרכנו, שהרי בגזירה שווה \u0003\"תחת\" \"תחת\" מקדשים גמר\u0004 \u0005[\u0006הוא \u0005למד]\u0006 למעטו! \u0003אלא\u0004 בוודאי מדובר בברייתא זו \u0003ל\u0004ענין שה שפודים בו \u0003פטר חמור,\u0004 ללמדנו שנדמה פסול לכך!","ודוחים: \u0003לא, לעולם\u0004 אמור כי מדובר בברייתא זו \u0003ל\u0004ענין \u0003מעשר, וכגון שיש בו\u0004 בנדמה \u0003מקצת סימנין\u0004 של אמו. והוצרכה הברייתא להשמיענו שהוא פסול למעשר, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 בגזירה שווה של לשונות \u0003\"העברה\" \"העברה\" מבכור גמר\u0004 \u0005[\u0006הוא \u0005למד],\u0006 והרי בכור שיש בו מקצת סימנים של אמו קדוש בבכורה כפי ששנינו להלן (טז,ב) — לכן","\u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 התנא, כי בגזירה שווה \u0003\"תחת\" \"תחת\"\u0004 מעשר \u0003מקדשים גמר\u0004 \u0005[למד],\u0006 והוא פסול. ואין להוכיח מכאן, איפוא, לגבי פדיון פטר חמור.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 שאלה לחכמים: \u0003מהו לפדות\u0004 פטר חמור \u0003ב\u0004שה של \u0003פסולי המוקדשין,\u0004 כלומר, בקדשים שנפסלו להקרבה ונפדו, שיש איסור לגזוז את צמרם ולעבוד בהם? האם יש בכך משום \"אין איסור חל על איסור\"?","ומפרטים: \u0003אליבא\u0004 \u0005[לפי\u0006 שיטתו\u0005]\u0006 של \u0003ר' שמעון לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה, \u0003כיון דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]\u0006 שפטר חמור \u0003מותר בהנאה\u0004 — אם כן \u0003חולין הוא,\u0004 ואין בו איסור שצריך לחול על פדיונו, ומותר הדבר. \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה הרי זה \u0003אליבא\u0004 \u0005[לפי\u0006 שיטתו\u0005]\u0006 של \u0003ר' יהודה דאמר\u0004 \u0005[שאומר]\u0006 שפטר חמור \u0003אסור בהנאה,\u0004","\u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 האם \u0003כיון\u0004 שפטר החמור \u0003אסור בהנאה,\u0004 נמצא שכשהוא פודה אותו בשה — חל האיסור שבו על השה, ולא ניתן לעשות זאת בשה פסולי המוקדשין, שהרי כלל הוא ש\u0003אין איסור חל על איסור.\u0004","\u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר: \u0003כיון\u0004 שפטר החמור \u0003לא תפיס\u0004 \u0005[תופס]\u0006 את \u0003פדיונו\u0004 בקדושת הבכורה, אם כן, פדיון פטר חמור \u0003אפקועי איסורא בעלמא הוא\u0004 \u0005[הפקעת איסור בלבד היא]\u0006 מפטר החמור, ואין בזה החלה של איסור על השה?","\u0003אמר רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב כהנא: מי זוטר מאי דכתיב בהו\u0004 \u0005[האם קטן,\u0006 לא חשוב, \u0005מה שנאמר בהם]\u0006 בפסולי המוקדשין, שדינם \u0003כצבי וכאיל\u0004 (דברים יב, טו)? ואם כן, מכאן יש ללמוד גם לענייננו: \u0003מה צבי ואיל אין פודין\u0004 בהם פטר חמור, וכפי ששנינו במשנתינו שאין פודים פטר חמור בחיה — \u0003אף פסולי המוקדשין אין פודין\u0004 בהם.","ואומרים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שבאת לכך],\u0006 להסבר זה, אם כן"],["\u0003לר' שמעון נמי\u0004 \u0005[גם כן],\u0006 אמור שאין פודים פטר חמור בפסולי המוקדשין, שהרי \"כ \u0003צבי\u0004 \u0003ו\u0004כ\u0003איל\" כתיב בהו\u0004 \u0005[נאמר בהם]\u0006 (דברים יב, טו), ואין פודים בצבי ואייל.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 שאלה לחכמים: \u0003מהו לפדות\u0004 פטר חמור \u0003בבהמת שביעית,\u0004 שקנו אותה בפירות שנת שמיטה, ויש בה גם כן קדושת פירות אלה?","ומפרטים: לפדות פטר חמור \u0003ודאי\u0004 בבהמת שביעית — \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה, ובוודאי אין פודים בה, שהרי נמצא הפודה קונה את פטר חמורו בבהמת שביעית שהוא נותן לכהן. ואינו רשאי לעשות כן, שהרי דווקא \u0003לאכילה אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 שמותר להשתמש בפירות שביעית, שנאמר: \"והיתה שבת הארץ לכם לאכלה\" (ויקרא כה, ו), \u0003ולא לסחורה. כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה, הרי זה במקרה של \u0003ספק\u0004 פטר חמור.","ומפרטים: ואליבא \u0005[ולפי שיטתו]\u0006 של \u0003ר' שמעון לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך, דלית ליה\u0004 \u0005[ש\u0006הרי \u0005אין לו]\u0006 כלל דין פדיון ב\u0003ספק\u0004 פטר חמור. \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה — הרי זה, איפוא, \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' יהודה,\u0004 הסבור כי במקרה זה מפריש שה כדי להפקיע את איסורו, ואולם אינו צריך לתיתו לכהן.","וכך יש לשאול: \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 האם \u0003כיון\u0004 ש\u0003מפריש טלה והוא לעצמו,\u0004 אם כן \u0003\"לאכלה\" קרינא ביה\u0004 \u0005[קוראים אנחנו בו],\u0006 ואין כאן סחורה, שהרי אינו נותנו לכהן כדי לזכות בחמורו. \u0003או דילמא\u0004 \u0005[שמא]:\u0006 \u0003כיון דכמה דלא מפקע איסוריה\u0004 \u0005[שכל עוד שלא מפקיע\u0006 השה \u0005את איסורו]\u0006 של פטר החמור \u0003לא מישתרי\u0004 \u0005[איננו מותר]\u0006 בהנאה, אם כן כשמפריש אותו תחתיו — \u0003כסחורה\u0004 בבהמת שביעית \u0003דמי\u0004 \u0005[נחשב]\u0006 הדבר?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר, מדברים מפורשים ש\u0003אמר רב חסדא: בהמת שביעית אין פודין בה את\u0004 פטר החמור \u0003הודאי, אבל פודין בה את הספק.\u0004","\u0003ו\u0004עוד אמר רב חסדא: בהמת שביעית — \u0003פטורה מן הבכורה,\u0004 שהבכור שתלד אינו קדוש. \u0003וחייבת במתנות,\u0004 זרוע לחיים וקיבה, שצריך כל השוחט בהמת חולין לתת לכהן.","ומסבירים: \u0003פטורה מן הבכורה\u0004 — כי \u0003\"לאכלה\" אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 ביחס לפירות שביעית (ויקרא כה, ו), \u0003ולא לשריפה,\u0004 ובכור בהמה טהורה — אימוריו נשרפים על גבי המזבח. \u0003וחייבת במתנות\u0004 — משום שבמקרה זה \u0003\"לאכלה\" קרינא\u0004 \u0005[קורא אני]\u0006 \u0003בה,\u0004 שהרי הכהן אוכל אותם.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו במסכת שביעית: \u0003האוכל מעיסת שביעית עד שלא הורמה\u0004 (הופרשה) ממנה \u0003חלתה\u0004 — \u0003חייב מיתה,\u0004 כדין כל אוכל עיסה שלא הורמה חלתה.","\u0003ו\u0004לפי דברי רב חסדא, \u0003אמאי\u0004 \u0005[מדוע]\u0006 כלל חייבת עיסת שביעית בחלה? והרי \u0003כיון\u0004 ש\u0003אילו מטמיא\u0004 \u0005[נטמאת]\u0006 החלה \u0003בת שריפה היא,\u0004 אם כן, יש לומר לגבי חיוב הפרשת חלה, כמו לגבי דין בכורה: \u0003\"לאכלה\" אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003ולא לשריפה!\u0004","ומשיבים: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 לגבי חלה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"וראשית עיסותיכם תתנו לה' לתרומה \u0003לדרתיכם\"\u0004 (במדבר טו, כא), והמלה \"לדורותיכם\" באה להדגיש: תמיד, וגם בשביעית, יש דין חלה.","ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003מנין לאוכל מעיסת שביעית עד שלא הורמה חלתה שחייב מיתה\u0004 — \u0003שנאמר: \"לדרתיכם\".\u0004 אבל בדין בכור בהמה לא נאמרה לשון זו, ומשום שאימוריו נשרפים — פטורה בהמת שביעית מן הבכורה.","ושואלים: \u0003ולגמר מינה\u0004 \u0005[ושנלמד ממנה]\u0006 מן האמור בחלה, שבהמת שביעית חייבת בבכורה, ואין אומרים בכגון זה \"לאכלה\" ולא לשריפה! ומשיבים: אין הדברים דומים, \u0003התם\u0004 \u0005[שם,\u0006 בחלה] \u0003עיקר דינה\u0004 הוא \u0003לאכילה,\u0004 ורק אם נטמאה צריך לשורפה, \u0003הכא\u0004 \u0005[כאן,\u0006 בבכור\u0005]\u0006 \u0003עיקר\u0004 דינם של האימורים הוא לכתחילה \u0003לשריפה.\u0004","שנינו במשנה: \u0003נתנו לכהן\u0004 את פטר החמור עצמו — אין הכהן רשאי לקיימו עד שיפריש שה תחתיו. ומעירים: מכאן שאנו חוששים שמא יתרשל הכהן בפדייתו. ואם כן \u0003תנינא להא דתנו רבנן\u0004 \u0005[שנינו\u0006 במשנתינו \u0005את זו ששנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003ישראל שהיה לו פטר חמור בתוך ביתו, ואמר לו הכהן: \"תנהו לי ואני אפדהו\"\u0004 — \u0003הרי זה לא יתנו לו, אלא אם כן פדאו\u0004 הכהן \u0003בפניו.\u0004","\u0003אמר רב נחמן אמר רבה בר אבוה: זאת אומרת\u0004 ש\u0003נחשדו הכהנים על פטרי חמורים,\u0004 להשתמש בהם בלא פדיון. ותמהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, הרי דבר זה נובע במישרין מדברי הברייתא, ומה חידש רב נחמן? ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003היכא דמחזק לן\u0004 \u0005[במקום שמוחזק לנו]\u0006 הכהן בדבר זה, \u0003דמיקרי\u0004 \u0005[שמזדמן\u0006 לו לעיתים\u0005]\u0006 להשתמש בפטר חמור בלא לפדותו, \u0003אבל בסתמא\u0004 \u0005[ב\u0006כהן \u0005סתם]\u0006 \u0003לא.\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 רב נחמן שיש לחשוש לכך בכל כהן, מפני שהוא \u0003מורה בה היתירא\u0004 \u0005[היתר]\u0006 לעצמו, שלא להפריש שה תחתיו, שהרי ממילא הוא שלו.","\u0003המפריש\u0004 שה ל\u0003פדיון פטר חמור, ומת\u0004 השה קודם שנתנו לכהן — ר' אליעזר אומר: חייבין הבעלים \u0003באחריותו,\u0004 וצריכים ליתן לכהן שה אחר, כמו שחייבים באחריות \u0003חמש סלעים של\u0004 פדיון ה\u0003בן,\u0004 שאם אבדו לאחר שהפרישם — צריך ליתן לכהן חמש סלעים אחרים. \u0003וחכמים אומרים: אין חייבין באחריותו, כ\u0004דין \u0003פדיון מעשר שני.\u0004","\u0003העיד ר' יהושע ור' צדוק\u0004 שנקבעה הלכה \u0003על\u0004 המפריש שה ל\u0003פדיון פטר חמור, ש\u0004אם \u0003מת\u0004 השה — \u0003שאין כאן לכהן כלום,\u0004 שכבר נפדה החמור, ואין הבעלים חייבים באחריות השה, וכדברי חכמים. \u0003מת פטר חמור\u0004 עצמו, לאחר שהפריש שה תחתיו, ולא הספיק ליתנו לכהן — \u0003ר' אליעזר אומר:\u0004 אין פטר חמור פדוי, שהרי לא הגיע השה ליד הכהן, ולפיכך \u0003יקבר\u0004 פטר החמור, כדין איסורי הנאה, \u0003ומותר\u0004 הבעלים \u0003בהנאתו של טלה\u0004 שהפריש, כאילו לא הפרישו כלל. \u0003וחכמים אומרים:\u0004 משהפריש את השה — נפדה פטר החמור, כאילו בא השה ליד הכהן, ולכן \u0003אין\u0004 פטר החמור \u0003צריך להקבר, ו\u0004ה\u0003טלה\u0004 ניתן \u0003לכהן.\u0004","בענין שה שהופרש לפדיון פטר חמור, ועדיין לא ניתן לכהן, שלדעת ר' אליעזר חייבים באחריותו, כפדיון הבן, \u0003אמר רב יוסף: מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור\u0005]\u0006 לדבריו של \u0003ר' אליעזר? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אך פדה תפדה\u0004 את בכור האדם ואת בכור הבהמה תפדה\" (במדבר יח, טו), ובכך הקישם הכתוב זה לזה: \u0003מה\u0004 פדיון \u0003בכור אדם חייב באחריותו\u0004 — \u0003אף\u0004 פדיון \u0003בכור בהמה טמאה חייב\u0004 גם כן \u0003באחריותו.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אי\u0004 \u0005[אם]\u0006 הוקשו זה לזה, יש לומר גם: \u0003מה בכור אדם מותר בהנאה,\u0004 שהרי אין איסור ליהנות ממעשה ידיו של בכור שלא נפדה — \u0003אף בכור בהמה טמאה מותר\u0004 בהנאה קודם שנפדה, ומותר לגוזזו ולעבוד בו! \u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר כך גם כן],\u0006 שלדעת ר' אליעזר פטר חמור מותר בהנאה, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה זו\u0005]:\u0006 \u0003מת פטר חמור, ר' אליעזר אומר: יקבר,\u0004 ולכאורה \u0003מאי\u0004 \u0005[מה\u0006 טעם\u0005]\u0006 \u0003יקבר\u0004 — \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 משום שהוא \u0003אסור בהנאה?\u0004","דחה רב יוסף: \u0003לא, יקבר כ\u0004דין \u0003בכור אדם,\u0004 שאם מת יש מצוה לקוברו, שהרי, כאמור, הוקש לו בכתוב. ותמהים: \u0003אלא,\u0004 לפי הסבר זה, אדם בכור שמת הוא \u0003דבעי\u0004 \u0005[שצריך]\u0006 \u0003קבורה, פשוט\u0004 (שאינו בכור) שמת \u0003לא בעי\u0004 \u0005[צריך]\u0006 \u0003קבורה?\u0004","\u0003ועוד,\u0004 איך אתה יכול לומר שפטר חמור מותר בהנאה לדעת ר' אליעזר? והרי \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מודה ר' אליעזר בישראל שיש לו ספק פטר חמור בתוך ביתו\u0004 — \u0003שמפריש טלה עליו, והוא שלו.\u0004 והרי אין צורך להפריש טלה אלא כדי להפקיע מפטר החמור את איסור ההנאה שבו!","\u0003אלא אמר רבא:\u0004 אף שהקיש הכתוב פטר חמור לבכור אדם, וכדברי רב יוסף, אין זה אלא כדי לחייב באחריות פדיונו, אבל לא להתירו בהנאה, שכן \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"אך פדה תפדה\u0004 את בכור האדם ואת בכור הבהמה הטמאה\" (במדבר יח, טו), והחזרה על לשון פדייה באה לומר: \u0003לפדייה הקשיתיו, ולא לדבר\u0004 \u0003אחר.\u0004","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006\u0005]\u0006 בברייתא: \u0003הערכין,\u0004 כשנודר ערכו של פלוני להקדש, לפי הערכים הקצובים בתורה לכל גיל — \u0003בשעתן,\u0004 כלומר, נותן את ערכו שבשעת הנדר, ואם נדר ערכו של תינוק פחות מבן חודש, שאין לו ערך — אינו חייב כלום, גם לאחר שלושים יום. \u0003ופדיון הבן\u0004 — \u0003אחר שלשים יום\u0004 צריך ליתנו לכהן, שנאמר: \"ופדויו מבן חודש תפדה\" (במדבר יח, טז). \u0003פדיון פטר חמור\u0004 — \u0003לאלתר.\u0004","ותוהים: \u0003ופדיון פטר חמור לאלתר? ורמינהי\u0004 \u0005[ומטילים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא: \u0003אין בערכין ובפדיון הבן ובנזירות ובפטר חמור פחות משלשים\u0004 יום,","\u0003ומוסיפין עד עולם!\u0004","\u0003אמר רב נחמן:\u0004 מה ששנינו \"פטר חמור לאלתר\" בא \u0003לומר שאם פדאו\u0004 לאלתר — \u0003פדוי,\u0004 אף שלכתחילה מצוותו לאחר שלושים יום. ותוהים: \u0003מכלל\u0004 הדברים אתה למד, ש\u0003בנו,\u0004 ששנינו לגביו באותה ברייתא: \"אחר שלושים יום\", \u0003אם פדאו\u0004 בתוך הזמן \u0003אינו פדוי? והאיתמר\u0004 \u0005[והרי נאמר]:\u0006 \u0003הפודה את בנו בתוך שלשים יום\u0004 ללידתו, \u0003רב אמר: בנו פדוי!\u0004","ודוחים: \u0003לאו איתמר עלה\u0004 \u0005[האם לא נאמר עליה]\u0006 מה ש\u0003אמר רבא: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 אם אומר בתוך שלושים יום שהוא פודה את בנו \u0003מעכשיו\u0004 — \u0003אין בנו פדוי,\u0004 ורק אם נותן את המעות על מנת שהפדיון יחול לאחר שלושים יום הרי זה פדוי, כשיגיע זמנו."],["\u0003רב ששת אמר:\u0004 מצות פטר חמור — לפדותו לאלתר, כברייתא הראשונה. ומה שנאמר בברייתא השניה שאין בפטר חמור פחות משלושים יום, בא \u0003לומר ש\u0004עד אז \u0003אינו עובר עליו\u0004 אם אינו פודה אותו, אבל לאחר שלושים יום — עובר עליו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רמי בר חמא\u0004 ממה ששנינו בברייתא: \u0003מצותו\u0004 של פטר חמור \u0003כל שלשים יום, מכאן ואילך\u0004 — \u0003או פודהו או עורפו. מאי לאו\u0004 \u0005[האם אין\u0006 הכוונה\u0005]\u0006 ש\u0003מצוה ל\u0004ה\u0003שהותו כל שלשים יום,\u0004 ורק אז לפדותו? ודוחים: \u0003לא, מצוה לפדותו כל שלשים יום,\u0004 אבל לאחר שלושים יום, אם לא פדאו — עובר עליו.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003\"מכאן ואילך או פודהו או עובר עליו\" מיבעי ליה\u0004 \u0005[צריך היה לו לומר],\u0006 ולא \"או פודהו או עורפו\"! \u0003אלא אמר רבא: לא קשיא\u0004 \u0005[קשה]\u0006 הסתירה שבין הברייתות, \u0003הא\u0004 \u0005[זה\u0006\u0005]\u0006 ששנינו שמצות פטר חמור לאחר שלושים יום — הרי זה לשיטת \u0003ר' אליעזר, דמקשי\u0004 \u0005[שמקיש,\u0006 משווה\u0005]\u0006 פטר חמור לבכור אדם, שנאמר בו \"מבן חודש תפדה\" (במדבר יח, טז), \u0003הא\u0004 \u0005[\u0006זה\u0005]\u0006 ששנינו שמצוותו לאלתר — הרי זה לשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003דלא מקשי\u0004 \u0005[שאינם מקישים,\u0006 משווים\u0005]\u0006 אותם.","\u0003לא רצה לפדותו\u0004 את פטר החמור — \u0003עורפו\u0004 (מתיז את ראשו) \u0003מאחוריו וקוברו. מצות הפדייה קודמת למצות עריפה, שנאמר: \"אם לא תפדה\u0004 — \u0003וערפתו\"\u0004 (שמות יג, יג). ומביאים מצוות דומות לזו.","\u0003מצות יעידה\u0004 באמה עבריה, שצריך האדון לקדשה לו לאשה — \u0003קודמת למצות הפדייה,\u0004 שאם לא קידש אותה — פודים אותה בכסף, \u0003שנאמר: \"\u0004אם רעה בעיני אדוניה \u0003אשר לא יעדה\u0004 — \u0003והפדה\"\u0004 (שמות כא, יח).","\u0003מצות הייבום\u0004 של אשת אחיו שמת \u0003קודמת למצות חליצה,\u0004 שאם אינו רוצה ליבמה — חולצת היבמה נעלו של היבם, ושוב אין זיקת אישות ביניהם, כפי שנאמר: \"ואם לא יחפץ האיש לקחת את יבמתו\" וכו' (דברים כה, ז). ומוסיפים: כל זה היה \u0003בראשונה, שהיו מתכוונין\u0004 לייבם \u0003לשם מצוה. ועכשיו שאין מתכוונין\u0004 לייבם \u0003לשם מצוה,\u0004 אלא מתוך טעמים אחרים — משום יופיה של היבמה, או לשם ממון — \u0003אמרו: מצות חליצה קודמת למצות יבום.\u0004","\u0003מצות הגאולה,\u0004 כלומר, הפדייה של בהמה טמאה שהוקדשה למקדש — \u0003באדון\u0004 שהקדיש אותה, ולכן \u0003הוא קודם לכל אדם, שנאמר:\u0004 \"ואם בבהמה הטמאה... \u0003ואם לא יגאל\u0004 (על ידי הבעלים) — \u0003ונמכר\u0004 (לכל אדם) \u0003בערכך\"\u0004 (ויקרא כז, כז).","\u0003הלוקח\u0004 (הקונה) \u0003עובר פרתו של נכרי\u0004 כשהוא במעי אמו, או \u0003המוכר לו\u0004 את עובר פרתו שלו, \u0003אף על פי שאינו רשאי\u0004 למכור לו בהמה גסה, או \u0003המשתתף לו,\u0004 שנעשה שותף עם הגוי בפרה או בעובר. או \u0003המקבל ממנו\u0004 פרה, כדי לטפל בה ולקחת חלק בולדות, או \u0003הנותן לו\u0004 פרה \u0003בקבלה,\u0004 כדי לטפל בה ולהתחלק בולדות — בכל המקרים האלה \u0003פטור מן הבכורה, שנאמר:\u0004 \"הקדשתי לי כל בכור בישראל מאדם עד בהמה\" (במדבר ג, יג), ויש לדייק: \u0003בישראל אבל לא באחרים.\u0004","","\u0003הכהנים והלוים חייבים\u0004 במצות בכור בהמה טהורה שלהם, \u0003שלא נפטרו מבכור בהמה טהורה, אלא\u0004 רק \u0003מפדיון הבן ומ\u0004פדיון \u0003פטר חמור.\u0004","ושואלים על סדר הפרקים במסכת זו: \u0003מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע נוהג כך התנא, \u0003דתני\u0004 \u0005[ש\u0006הוא \u0005שונה]\u0006 ענין \u0003עובר חמורו ברישא\u0004 \u0005[בתחילה],\u0006 בפרק הראשון, \u0003והדר תני\u0004 \u0005[\u0006\u0005ואחר כך שונה]\u0006 ענין \u0003עובר פרתו? ליתני ברישא\u0004 \u0005[שישנה בתחילה]\u0006 \u0003עובר פרתו,\u0004 שהוא קדוש יותר, שהרי קדושת הבכורה שבו \u0003קדושת הגוף הוא,\u0004 ליקרב על המזבח, ואינה פוקעת על ידי פדיון, \u0003והדר ליתני\u0004 \u0005[ואחר כך שישנה]\u0006 \u0003עובר חמורו,\u0004 ש\u0003קדושת דמים הוא,\u0004 שאינו צריך אלא לפדותו, ומשנפדה הוא מותר לגמרי!","\u0003אמרי במערבא\u0004 \u0005[אומרים בארץ ישראל]\u0006 בתשובה לכך, \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003איידי דחביבא ליה\u0004 \u0005[מתוך שחביבה לו\u0006 הלכה זו\u0005]\u0006 של פדיון פטר חמור, שיש בה ענין מיוחד, \u0003כ\u0004דברי \u0003רבי חנינא,\u0004 שהסביר (לעיל ה,ב) מדוע זכה חמור לקדושת הבכורה, ולא שאר בהמה טמאה — לכן הקדים אותה. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003איידי דזוטרן מיליה\u0004 \u0005[מתוך שמועטים ענייניו\u0006\u0005]\u0006 של בכור \u0003בהמה טמאה, פסיק ושדי לה\u0004 \u0005[\u0006הוא \u0005פוסק,\u0006 חותך, \u0005ומשליך אותה],\u0006 ואחר כך עובר לבכור בהמה טהורה, שענייניו מרובים.","ובפרטי ההלכה של הקונה בהמה מגוי, \u0003אמר ר' יצחק בר נחמני אמר ריש לקיש משום\u0004 (משמו של) \u0003ר' אושעיא: ישראל שנתן מעות לגוי\u0004 עבור בהמתו \u0003בדיניהם,\u0004 לפי דיני הגוים, \u0003אף על פי שלא משך\u0004 את הבהמה כדי לקנותה, הרי זה \u0003קנה\u0004 אותה, \u0003ו\u0004אם תתעבר מכאן ואילך — \u0003חייבת בבכורה. ו\u0004כן לצד השני, \u0003גוי שנתן מעות לישראל בבהמתו בדיניהם, אף על פי שלא משך\u0004 — \u0003קנה, ופטור מן הבכורה.\u0004","ודנים בפרטי הדברים שאמר ר' אושעיא. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ישראל שנתן מעות לגוי\u0004 עבור בהמתו \u0003בדיניהם, אף על פי שלא משך\u0004 — \u0003קנה וחייבת בבכורה.\u0004","ושואלים: מאי \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בדיניהם\"? אי נימא\u0004 \u0005[אם נאמר\u0006\u0005]:\u0006 שקנה את הבהמה \u0003בדיניהם דגופיה\u0004 \u0005[של\u0006 הגוי \u0005עצמו],\u0006 כדרך שקונים את הגוי עצמו כעבד, בכסף. ומניין שהוא נקנה בכסף? \u0003דאתי\u0004 \u0005[ש\u0006הוא \u0005בא,\u0006 נלמד\u0005]\u0006 \u0003בקל וחומר: אם גופיה קני ליה\u0004 \u0005[אם\u0006 את הגוי \u0005עצמו\u0006 \u0005קונה]\u0006 \u0003ישראל בכסף, דכתיב\u0004 \u0005[שנאמר]\u0006 בעבד כנעני: \"והתנחלתם אותם לבניכם אחריכם \u0003לרשת אחזה\"\u0004 (ויקרא כה, מו), ובכך","\u0003הקישו\u0004 (השווה אותו) \u0003הכתוב לאחוזה,\u0004 לקרקע: \u0003מה אחוזה נקנית בכסף,\u0004 או \u0003בשטר,\u0004 או \u0003בחזקה,\u0004 כגון שנועל וגודר את השדה — \u0003אף עבד כנעני נקנה בכסף.\u0004 ולפיכך נאמר ש\u0003ממונו,\u0004 כגון בהמתו של הגוי — \u0003לא כל שכן הוא\u0004 שקונה הישראל מידו בכסף?","על כך יש להקשות: \u0003אם כן,\u0004 לפי קל וחומר זה, \u0003אפילו בשטר ובחזקה נמי\u0004 \u0005[גם כן]\u0006 יוכל לקנות את הבהמה, כדרך שקונים את הגוי עצמו. ולא רק במעות, כפי שנזכר בדברי ר' אושעיא! \u0003ועוד,\u0004 דרכי הקנין של \u0003ישראל מישראל יוכיחו\u0004 שאין ללמוד קנין ממונו של אדם מקנין גופו, \u0003דגופיה קני ליה\u0004 \u0005[ש\u0006הרי את ישראל \u0005עצמו קונה]\u0006 ישראל לעבד \u0003בכסף,\u0004 ואילו \u0003ממונו,\u0004 כגון בהמתו של ישראל, אין ישראל קונה בכסף, אלא \u0003במשיכה!\u0004","\u0003אלא אמר אביי:\u0004 מה שנאמר שנתן מעות לגוי בדיניהם, אין כוונתו — כדרך שקונים גוי, אלא: \u0003בדיניהם שפסקה להם תורה,\u0004 ואמרה כיצד קונים מידם מיטלטלים, והוא במעות, שכך דורשים את הפסוק \u0003\"או קנה מיד עמיתך\"\u0004 (ויקרא כה, יד), \u0003מיד עמיתך\u0004 (ישראל) \u0003הוא\u0004 שאתה קונה \u0003במשיכה\u0004 מיד ליד, \u0003הא\u0004 \u0005[אבל]\u0006 \u0003מיד גוי\u0004 אתה קונה \u0003בכסף.\u0004 ומקשים: ומניין שכך יש להסיק מכתוב זה?","\u0003ואימא\u0004 \u0005[ואמור]:\u0006 מיד עמיתך אתה קונה במשיכה, ואילו \u0003מיד גוי\u0004 — \u0003כלל כלל לא\u0004 קונים, ואפילו לא בכסף! בתשובה לכך \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כך, שהרי \u0003קל וחומר הוא: אם\u0004 את \u0003גופו\u0004 של הגוי \u0003קונה\u0004 ישראל בכסף, \u0003ממונו לא כל שכן\u0004 שהוא קונה בכסף? ומקשים: \u0003ואימא\u0004 \u0005[ו\u0006עדיין \u0005אמור\u0006 כך\u0005]:\u0006 מיד עמיתך אתה קונה במשיכה, אבל \u0003מיד גוי\u0004 אינך קונה \u0003עד דאיכא תרתי\u0004 \u0005[שיש שתים],\u0006 שתי דרכי קניה גם כסף וגם משיכה! בתשובה לכך \u0003אמרי\u0004 \u0005[אומרים]:\u0006 בוודאי אינך יכול לומר כן, \u0003ולאו\u0004 \u0005[ו\u0006האם \u0005לא]\u0006 \u0003קל וחומר הוא?\u0004 אם את \u0003גופו\u0004 קונה ישראל \u0003ב\u0004דרך קנין \u0003אחת, ממונו\u0004 צריך לקנות \u0003בשתים?!\u0004 וחוזרים ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ודייק כך: מיד עמיתך אתה קונה במשיכה, מיד הגוי קונים \u0003או בהא\u0004 \u0005[בזה,\u0006 בכסף\u0005]\u0006 \u0003או בהא\u0004 \u0005[בזה,\u0006 במשיכה\u0005]!\u0006 ומשיבים: לא ניתן לומר כן, שהרי דינו של הגוי צריך להיות \u0003דומיא\u0004 \u0005[דומה]\u0006 לדין של \u0003עמיתך,\u0004 ממנו הוא למד,","","\u0003מה\u0004 מיד \u0003עמיתך בחדא\u0004 \u0005[\u0006אתה קונה \u0005ב\u0006דרך \u0005אחת]\u0006 במשיכה — \u0003אף\u0004 מיד \u0003גוי נמי\u0004 \u0005[גם כן]\u0006 \u0003בחדא\u0004 \u0005[באחת],\u0006 בכסף.","ודנים בהמשך דברי ר' אושעיא. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003וגוי שנתן מעות לישראל בבהמתו בדיניהן, אף על פי שלא משך\u0004 — \u0003קנה, ופטור מן הבכורה.\u0004 ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בדיניהן\"? אילימא\u0004 \u0005[אם נאמר]\u0006 \u0003בדיניהן דגופיה\u0004 \u0005[של\u0006 ישראל \u0005עצמו],\u0006 כדרך שהוא קונה את גופו של ישראל בכסף. ויש לומר כן \u0003משום דאתי\u0004 \u0005[ש\u0006הוא \u0005בא,\u0006 נלמד\u0005]\u0006 \u0003בקל וחומר: אם\u0004 את \u0003גופו\u0004 של \u0003ישראל קני ליה\u0004 \u0005[קונה אותו]\u0006 הגוי \u0003בכסף, דכתיב\u0004 \u0005[שנאמר]\u0006 בישראל הנמכר לגוי: \u0003\"מכסף מקנתו\"\u0004 (ויקרא כה, נא), את \u0003ממונו\u0004 של ישראל \u0003לא כל שכן\u0004 שקונה אותו הגוי בכסף?","דבר זה יש לדחות: דרכי הקנין של \u0003ישראל מישראל יוכיחו,\u0004 שהרי את \u0003גופו\u0004 של עבד עברי \u0003קני\u0004 \u0005[קונה]\u0006 ישראל \u0003בכסף,\u0004 ואת \u0003ממונו\u0004 של ישראל אין ישראל קונה בכסף, אלא \u0003במשיכה! אלא אמר אביי:\u0004 מה שנאמר שגוי קונה בהמה בכסף \u0003בדיניהם,\u0004 הכוונה היא: בדרכי הקנין \u0003שפסקה להם תורה\u0004 לגוים, כיצד הם קונים מיד ישראל, והוא בכסף, שנאמר: \u0003\"וכי תמכרו ממכר לעמיתך\"\u0004 (ויקרא כה, יד), ויש לדייק: \u0003לעמיתך\u0004 אתה מוכר \u0003במשיכה, הא\u0004 \u0005[אבל]\u0006 \u0003לגוי\u0004 — \u0003בכסף.\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003לגוי כלל כלל לא,\u0004 שאין הגוי קונה מיד ישראל לא בכסף ולא במשיכה! \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003קל וחומר הוא? אם\u0004 את \u0003גופו\u0004 של ישראל \u0003קנה\u0004 הגוי, \u0003ממונו לא כל שכן\u0004 שהוא קונה?","ומקשים, \u0003אימא\u0004 \u0005[אמור\u0006 ודייק כך\u0005]:\u0006 לעמיתך אתה מוכר במשיכה, אבל \u0003לגוי\u0004 אינך מוכר \u0003עד דאיכא תרתי\u0004 \u0005[שיש שתים],\u0006 שתי דרכי קניה, גם במשיכה וגם בכסף! ומשיבים: \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003קל וחומר הוא?\u0004 אם את \u0003גופו\u0004 של ישראל קונה הגוי \u0003ב\u0004דרך \u0003אחד,\u0004 את \u0003ממונו\u0004 יצטרך לקנות \u0003בשתים?!\u0004","ומקשים, \u0003ואימא\u0004 \u0005[ואמור]:\u0006 את ממונו של ישראל קונה הגוי \u0003או בהא\u0004 \u0005[בזו]\u0006 \u0003או בהא\u0004 \u0005[בזו]!\u0006 ודוחים: קנין הגוי הנלמד מפסוק זה הריהו \u0003דומיא\u0004 \u0005[בדומה]\u0006 לקנין של \u0003עמיתך,\u0004 ממנו הוא נלמד:"],["\u0003מה עמיתך\u0004 — \u0003ב\u0004דרך \u0003אחת, אף גוי נמי\u0004 — \u0003באחת.\u0004","מצאנו, איפוא, מקור בתורה לדרך קניינו של הגוי מיד ישראל בכסף — מדיוק המלה \"עמיתך\". ועל כך \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003ול\u0004שיטת \u0003אמימר דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]:\u0006 \u0003משיכה בגוי קונה, הניחא אי סבר לה\u0004 \u0005[זה נוח,\u0006 מובן, \u0005אם סבור הוא]\u0006 \u0003כ\u0004דעת \u0003ר' יוחנן דאמר\u0004 \u0005[שאומר]:\u0006 \u0003דבר תורה\u0004 (מדין תורה) \u0003מעות קונות\u0004 מיטלטלים מישראל לישראל, \u0003משיכה לא,\u0004 אם כן \u0003אהני\u0004 \u0005[הועיל]\u0006 הכתוב \"וכי תמכרו ממכר \u0003לעמיתך\"\u0004 (ויקרא כה, יד), ללמדנו: \u0003לעמיתך\u0004 — \u0003בכסף, לגוי\u0004 — \u0003במשיכה.\u0004","\u0003אלא אי סבר לה\u0004 \u0005[אם הוא סבור]\u0006 \u0003כ\u0004דעת ריש לקיש \u0003דאמר\u0004 \u0005[שאומר]:\u0006 \u0003משיכה\u0004 כקנין בישראל \u0003מפורשת מן התורה,\u0004 נמצא שגם \u0003לעמיתך\u0004 אתה מוכר \u0003במשיכה, ו\u0004גם \u0003לגוי במשיכה,\u0004 אם כן \u0003\"לעמיתך\" למה לי?\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \"עמיתך\" לא לצורך הקנין נאמר, אלא לעיקר דינו של פסוק זה, שנאמר: \"וכי תמכרו ממכר לעמיתך או קנה מיד עמיתך אל תונו איש את אחיו\", ללמד: \u0003לעמיתך אתה מחזיר אונאה,\u0004 שאם נטלת מן הקונה יותר מערכו של החפץ, או שילמת למוכר פחות מערכו, עליך להשיב לו, \u0003ואי\u0004 \u0005[ואין]\u0006 \u0003אתה מחזיר אונאה לגוי.\u0004 ומקשים: דין זה, שאין אונאה \u0003לגוי\u0004 — \u0003מ\"אל תונו איש את אחיו\" נפקא\u0004 \u0005[יוצא הדבר],\u0006 מדיוק המלה \"אחיו\"!","ומשיבים: \u0003חד\u0004 \u0005[\u0006מיעוט \u0005אחד]\u0006 נאמר \u0003בגוי, וחד\u0004 \u0005[ו\u0006מיעוט \u0005אחד]\u0006 \u0003בהקדש,\u0004 שאין דין אונאה בנכסי המקדש. ומעירים: \u0003ו\u0004למרות שגם הגוי וגם ההקדש אינם בכלל \"עמיתך\", \u0003צריכי\u0004 \u0005[צריכים]\u0006 שני מיעוטים: \u0003דאי כתב רחמנא חד\u0004 \u0005[שאם\u0006 היתה \u0005כותבת התורה\u0006 רק מיעוט \u0005אחד],\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003לגוי הוא\u0004 ש\u0003אין לו אונאה, אבל הקדש\u0004 — \u0003יש לו אונאה,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב דין זה גם בהקדש.","ומקשים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003גזילו,\u0004 לגזול את הגוי, \u0003אסור\u0004 מדין תורה — \u0003היינו דאצטריך קרא\u0004 \u0005[זהו שהוצרך הכתוב]\u0006 \u0003למישרי\u0004 \u0005[להתיר]\u0006 \u0003אונאה\u0004 שלו. \u0003אלא אי סבר לה כמאן דאמר\u0004 \u0005[אם הוא סבור כ\u0006דעת \u0005מי שאומר]\u0006 \u0003גזילו של גוי מותר, אונאה\u0004 שלו \u0003מיבעיא\u0004 \u0005[צריך\u0006 לומר\u0005]\u0006 שאינו צריך להחזיר? וחוזרת איפוא השאלה: לשיטת אמימר, \"לעמיתך\" למה לי, לדעת ריש לקיש? על כך \u0003אמרי\u0004 \u0005[אומרים]:\u0006 אי סבר לה כמאן דאמר \u0005[אם סבור הוא כ\u0006דעת \u0005מי שאומר]\u0006 \u0003גזילו מותר\u0004 — באמת אין צורך ב\"עמיתך\" לשיטת ריש לקיש. ואם כן, \u0003על כורחיך\u0004 עולא \u0003כר' יוחנן סבירא ליה\u0004 \u0005[סבור הוא],\u0006 שדבר תורה מעות קונות מיטלטלים בישראל, והוא דורש כך: לעמיתך אתה מוכר במעות, לגוי — במשיכה.","ושבים לדון בדברי ריש לקיש בשם ר' אושעיא, שקונים מיטלטלים מן הגוי במעות. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003הלוקח\u0004 (הקונה) \u0003גרוטאות\u0004 (שברי כלים) \u0003מן הגוים,\u0004 אם \u0003מצא בהן עבודה זרה\u0004 שאסורה בהנאה, מה יעשה? \u0003אם עד שלא נתן מעות\u0004 לגוי \u0003משך\u0004 את הגרוטאות — \u0003יחזיר\u0004 אותם לגוי, שמשיכה בלא מתן מעות אינה קונה מן הגוי. \u0003ואם משנתן מעות\u0004 לגוי \u0003משך\u0004 הרי זה אלו שלו, ו\u0003יוליך הנאה,\u0004 דמיה של אותה עבודה זרה \u0003לים המלח,\u0004 כלומר, לאיבוד. \u0003ואי אמרת\u0004 \u0005[אם אתה אומר]\u0006 ש\u0003מעות\u0004 לבדן \u0003קונות\u0004 מן הגוי, אם כן, מה ששנינו בסוף הברייתא: ואם משנתן מעות משך — קנה, משיכה בנוסף למעות \u0003למה לי? המלח,\u0004 כלומר, לאיבוד.","\u0003ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 ש\u0003מעות\u0004 לבדן \u0003קונות\u0004 מן הגוי, אם כן, מה ששנינו בסוף הברייתא: ואם משנתן מעות משך — קנה, משיכה בנוסף למעות \u0003למה לי?\u0004 ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003שקיבל עליו\u0004 הגוי \u0003לדון בדיני ישראל,\u0004 ובישראל משיכה קונה. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003מעות\u0004 שהוזכרו \u0003למה לי?\u0004 הרי בישראל די במשיכה! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003אף על פי שנתן מעות, אי משיך\u0004 \u0005[אם משך]\u0006 — \u0003אין\u0004 \u0005[כן],\u0006 קנה, \u0003ואי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 משך — \u0003לא.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כן],\u0006 שמדובר בגוי שקיבל עליו לדון בדיני ישראל, \u0003קשיא רישא\u0004 \u0005[קשה תחילת\u0006 הברייתא\u0005],\u0006 ששנינו: אם עד שלא נתן מעות משך — יחזיר. ומדוע? והרי קנה ממנו במשיכה! \u0003אמר אביי: רישא\u0004 \u0005[בהתחלה],\u0006 הטעם שמחזיר — \u0003משום דאיכא\u0004 \u0005[שיש\u0006 בזה\u0005]\u0006 \u0003מקח טעות,\u0004 שלא היתה כוונתו לקנות עבודה זרה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 בתמיהה: \u0003רישא\u0004 \u0005[בהתחלה]\u0006 אתה מסביר — \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 \u0003מקח טעות,\u0004 וכי \u0003סיפא\u0004 \u0005[בסוף]\u0006 כאשר נתן מעות \u0003ליכא\u0004 \u0005[אין]\u0006 \u0003מקח טעות?\u0004","\u0003אלא אמר רבא: רישא וסיפא\u0004 \u0005[\u0006גם \u0005בהתחלה ו\u0006גם \u0005בסוף]\u0006 מדובר ב\u0003מקח טעות,\u0004 ומעיקר הדין חוזר בשניהם. ואולם \u0003רישא\u0004 \u0005[בהתחלה],\u0006 במקרה \u0003דלא יהיב זוזי\u0004 \u0005[שלא נתן מעות]\u0006 לגוי — \u0003לא מיחזי\u0004 \u0005[אין\u0006 זה \u0005נראה]\u0006 \u0003כעבודה זרה ביד ישראל,\u0004 שהרי רגילים לקנות מן הגוי במעות, וכל עוד לא נתן מעות אין זה נראה כשלו, ולכן יכול להחזיר לגוי. \u0003סיפא דיהיב זוזי\u0004 \u0005[בסוף, שנתן\u0006 כבר \u0005כסף]\u0006 — \u0003מיחזי\u0004 \u0005[נראה הדבר]\u0006 \u0003כעבודה זרה ביד ישראל,\u0004 שהרי רגילים לקנות מן הגוי במעות, וכיון שנתן הרי זה נראה כשלו, ולכן צריך לאבדה, למרות שהיה זה מקח טעות.","ואומרים: \u0003ואביי,\u0004 שהסביר כי דווקא בתחילה מדובר במקח טעות, \u0003אמר\u0004 \u0005[יכול היה לומר]\u0006 \u0003לך:\u0004 דווקא \u0003רישא\u0004 \u0005[בהתחלה]\u0006 ניתן להסביר שהיה זה \u0003מקח טעות\u0004 — משום ש\u0003לא ידע\u0004 שיש בין הגרוטאות גם עבודה זרה, \u0003דהא לא יהיב ליה זוזי\u0004 \u0005[שהרי\u0006 עדיין \u0005לא\u0006 \u0005נתן לו כסף],\u0006 ואין דרכו של קונה לבדוק היטב את החפץ הנקנה עד שהוא בא לתת את המעות. \u0003סיפא\u0004 \u0005[בסוף]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003מקח טעות הוא,\u0004 ש\u0003כיון דיהיב זוזי\u0004 \u0005[ש\u0006כבר \u0005נתן כסף],\u0006 \u0003כי קא משיך\u0004 \u0005[כאשר הוא מושך]\u0006 — \u0003איבעי לעיוני והדר מימשך\u0004 \u0005[צריך\u0006 היה \u0005לבדוק, ואחר כך למשוך],\u0006 ומשלא עשה זאת — התכוון לקנות את הגרוטאות על כל מה שבתוכן.","\u0003רב אשי אמר\u0004 הסבר אחר לברייתא: \u0003מדרישא\u0004 \u0005[מ\u0006תוך \u0005שבהתחלה]\u0006 למדנו ש\u0003משיכה\u0004 בגוי \u0003אינה קונה,\u0004 אלא מעות — \u0003סיפא נמי\u0004 \u0005[בסוף גם כן]\u0006 ששנינו: ואם משנתן מעות משך — קנה, יש להבין כי \u0003משיכה אינה קונה,\u0004 אלא המעות. \u0003ו\u0004אף שלפי זה לא הוצרך להזכיר כלל משיכה, שהרי קנה במתן המעות, מכל מקום \u0003איידי דתנא רישא\u0004 \u0005[מתוך ששנה בהתחלה]\u0006 \u0003\"משך\"\u0004 — \u0003תנא סיפא נמי\u0004 \u0005[שנה בסוף גם כן]\u0006 לשון \u0003\"משך\".\u0004","\u0003רבינא אמר:\u0004 להיפך, \u0003מדסיפא\u0004 \u0005[מ\u0006מה \u0005שבסוף]\u0006 מוכח ש\u0003משיכה קונה\u0004 גם מגוי, שהרי שנינו: אם משנתן מעות משך — קנה, יש ללמוד כי \u0003רישא נמי\u0004 \u0005[בהתחלה גם כן]\u0006 \u0003משיכה קונה, ורישא\u0004 \u0005[ו\u0006מה ששנינו \u0005בהתחלה]:\u0006 אם עד שלא נתן מעות משך — יחזיר, יש להבין כי \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003אם לא נתן\u0004 מעות \u0003ולא משך\u0004 — \u0003יחזור, מאי\u0004 \u0005[מהו]\u0006 \u0003יחזור\u0004 — \u0003יחזור בדברים,\u0004 שאינו צריך לקיים את דבריו.","והוצרך התנא לומר זאת, שכן \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 כי בדרך כלל, \u0003דברים,\u0004 הסכמה של דיבור בלבד, בלי מעשה קנין — \u0003יש בהם משום מחוסרי אמנה,\u0004 כלומר, עבירה של הפרת אמון. \u0003ו\u0004אולם \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא ב\u0003ישראל\u0004 הקונה \u0003מישראל, דקיימו בדבורייהו\u0004 \u0005[ש\u0006הם, הישראלים \u0005עומדים בדיבורם],\u0006 ואחד סומך על חבירו שיקיים את דבריו. \u0003אבל ישראל\u0004 הקונה \u0003מגוים, דאינהו לא קיימי בדבורייהו\u0004 \u0005[שהם,\u0006 הגוים, \u0005אינם עומדים בדיבורם],\u0006 שדיבור אינו מחייב לגביהם בעניינים של קנין — \u0003לא,\u0004 ולכן אם חוזר בו מהסכם שבדיבור אין בכך פגם."]]};
